std::string characterDigestHex(const uint8_t digest[32]) {
    static const char digits[] = "0123456789abcdef";
    std::string text(64u, '0');
    for (size_t index = 0u; index < 32u; ++index) {
        text[index * 2u] = digits[digest[index] >> 4u];
        text[index * 2u + 1u] = digits[digest[index] & 0xFu];
    }
    return text;
}

bool characterPreviewCacheDirectory(std::string &directory) {
    char path[MDKR_MODERN_CHARACTER_PATH_MAX];
    if (!mdkr_user_characters_directory(path, sizeof(path))) return false;
    directory = path;
    return !directory.empty();
}

bool prepareInlineCharacterCapture(
    const MdkrModernCharacterEntry *entry,
    MdkrCharacterPreviewContext context,
    std::string &capturePath,
    bool donorReference = false,
    bool modelAlpha = false) {
    std::string directory;
    std::string error;
    if (entry == nullptr || (donorReference && modelAlpha) ||
        context < MDKR_CHARACTER_PREVIEW_SELECT ||
        context > MDKR_CHARACTER_PREVIEW_PLANE ||
        !characterPreviewCacheDirectory(directory)) {
        setStatus(
            "The launcher could not resolve its bounded local preview cache.",
            AppTheme::bad());
        return false;
    }
    const CharacterVisualReport::Subject subject = donorReference
        ? CharacterVisualReport::Subject::RetailDonor
        : CharacterVisualReport::Subject::CustomCharacter;
    const CharacterPreviewCache::Product cacheProduct = donorReference
        ? CharacterPreviewCache::Product::RetailDonorScene
        : modelAlpha
            ? CharacterPreviewCache::Product::CustomModelAlpha
            : CharacterPreviewCache::Product::CustomScene;
    const CharacterVisualReport::RenderProduct reportProduct = modelAlpha
        ? CharacterVisualReport::RenderProduct::ModelAlpha
        : CharacterVisualReport::RenderProduct::Scene;
    std::string retainedPath;
    const auto retained = g_characterVisualCaptures.find(entry->id);
    if (retained != g_characterVisualCaptures.end()) {
        for (auto capture = retained->second.rbegin();
             capture != retained->second.rend(); ++capture) {
            if (capture->subject == subject &&
                capture->context == characterPreviewResultContext(context) &&
                capture->renderProduct == reportProduct &&
                CharacterPreviewCache::owns(
                    directory, entry->id, capture->pngPath)) {
                retainedPath = capture->pngPath;
                break;
            }
        }
    }
    if (!CharacterPreviewCache::preparePreserving(
            directory, entry->id, static_cast<uint32_t>(context),
            cacheProduct,
            retainedPath,
            capturePath, error)) {
        setStatus(
            error.empty()
                ? "The launcher could not resolve its bounded local preview cache."
                : error.c_str(),
            AppTheme::bad());
        return false;
    }
    auto captures = g_characterVisualCaptures.find(entry->id);
    if (captures != g_characterVisualCaptures.end()) {
        captures->second.erase(
            std::remove_if(
                captures->second.begin(), captures->second.end(),
                [&](const CharacterVisualReport::Capture &capture) {
                    if (capture.pngPath != capturePath) return false;
                    g_characterCaptureThumbnails[entry->id].erase(
                        capture.pngSha256);
                    return true;
                }),
            captures->second.end());
    }
    return true;
}

bool characterCaptureIsLauncherOwned(
    const std::string &packageId, const std::string &capturePath) {
    std::string directory;
    return characterPreviewCacheDirectory(directory) &&
        CharacterPreviewCache::owns(
            directory, packageId, capturePath);
}

CharacterVisualReport::StoreResult bindAndStoreInlineCharacterCapture(
    const std::string &packageId,
    std::vector<CharacterVisualReport::Capture> &captures,
    CharacterVisualReport::Capture &capture,
    std::string &error) {
    std::string directory;
    if (!characterPreviewCacheDirectory(directory)) {
        error = "The launcher could not resolve its bounded local preview cache.";
        return CharacterVisualReport::StoreResult::Invalid;
    }
    const auto replaceable = std::find_if(
        captures.begin(), captures.end(),
        [&](const CharacterVisualReport::Capture &candidate) {
            return candidate.pngPath != capture.pngPath &&
                candidate.subject == capture.subject &&
                candidate.context == capture.context &&
                candidate.renderProduct == capture.renderProduct &&
                CharacterPreviewCache::owns(
                    directory, packageId, candidate.pngPath);
        });
    if (replaceable == captures.end()) {
        return CharacterVisualReport::bindAndStore(
            captures, capture, error);
    }
    const CharacterVisualReport::Capture previous = *replaceable;
    const CharacterVisualReport::StoreResult stored =
        CharacterVisualReport::bindAndReplace(
            captures,
            static_cast<size_t>(replaceable - captures.begin()),
            capture, error);
    if (stored != CharacterVisualReport::StoreResult::Replaced) {
        return stored;
    }
    g_characterCaptureThumbnails[packageId].erase(previous.pngSha256);
    (void)CharacterPreviewCache::removeOwnedPath(
        directory, packageId, previous.pngPath);
    error.clear();
    return stored;
}

void retirePreviousInlineCharacterCaptures(
    const std::string &packageId,
    const CharacterVisualReport::Capture &replacement) {
    std::string directory;
    auto found = g_characterVisualCaptures.find(packageId);
    if (found == g_characterVisualCaptures.end() ||
        !characterPreviewCacheDirectory(directory)) {
        return;
    }
    auto &captures = found->second;
    for (auto capture = captures.begin(); capture != captures.end();) {
        if (capture->pngPath != replacement.pngPath &&
            capture->subject == replacement.subject &&
            capture->context == replacement.context &&
            capture->renderProduct == replacement.renderProduct &&
            CharacterPreviewCache::owns(
                directory, packageId, capture->pngPath) &&
            CharacterPreviewCache::removeOwnedPath(
                directory, packageId, capture->pngPath)) {
            g_characterCaptureThumbnails[packageId].erase(
                capture->pngSha256);
            capture = captures.erase(capture);
        } else {
            ++capture;
        }
    }
}

void removeLauncherOwnedCharacterCaptures(const std::string &packageId) {
    std::string directory;
    if (characterPreviewCacheDirectory(directory)) {
        CharacterPreviewCache::removePackage(directory, packageId);
    }
}

bool characterDigestTextValid(const std::string &digest) {
    return digest.size() == 64u &&
        std::all_of(digest.begin(), digest.end(), [](char byte) {
            return (byte >= '0' && byte <= '9') ||
                   (byte >= 'a' && byte <= 'f');
        });
}

CharacterCandidateIndex::Candidate installedCharacterSummary(
    const MdkrModernCharacterEntry &entry) {
    CharacterCandidateIndex::Candidate summary;
    summary.id = entry.id;
    summary.displayName = entry.display_name;
    summary.shortName = entry.short_name;
    summary.narrationName = entry.narration_name;
    summary.sortLabel = entry.sort_label;
    summary.sourceDigest = characterDigestHex(entry.source_sha256);
    summary.donor = entry.donor;
    summary.vehicleMask = entry.vehicle_mask;
    summary.vertices = entry.stats.vertices;
    summary.triangles = entry.stats.triangles;
    summary.primitives = entry.stats.primitives;
    summary.lodLevels = entry.stats.lod_levels;
    summary.materials = entry.stats.materials;
    summary.textures = entry.stats.textures;
    summary.nodes = entry.stats.nodes;
    summary.skins = entry.stats.skins;
    summary.joints = entry.stats.joints;
    summary.animations = entry.stats.animations;
    summary.animationChannels = entry.stats.animation_channels;
    summary.animationKeys = entry.stats.animation_keys;
    summary.semanticMask = entry.semantic_mask;
    summary.disabledSemanticMask = entry.disabled_semantic_mask;
    summary.semanticIntentPresent = true;
    summary.identityPresent =
        (entry.identity_flags & 1u) != 0u && entry.portrait_bytes != 0u;
    summary.rigMode = entry.rig_present != 0u ? entry.rig_mode + 1u : 0u;
    summary.rigReviewed =
        (entry.rig_flags & MDKR_MODERN_RIG_REVIEWED) != 0u;
    summary.rigRoles = entry.stats.rig_roles;
    summary.jointConstraints = entry.stats.joint_constraints;
    summary.secondaryChains = entry.stats.secondary_chains;
    summary.secondaryJoints = entry.stats.secondary_joints;
    summary.encodedTextureBytes = entry.stats.encoded_texture_bytes;
    summary.decodedTextureBytes = entry.stats.decoded_texture_bytes;
    summary.ktx2Textures = entry.stats.ktx2_textures;
    summary.ktx2SourceBytes = entry.stats.ktx2_source_bytes;
    summary.textureFormatDiagnosticsPresent = true;
    summary.provenancePresent = entry.provenance_present != 0u;
    if (summary.provenancePresent) {
        summary.licenseSpdx = entry.license_spdx;
        summary.attribution = entry.attribution;
        summary.sourceUrl = entry.source_url;
    }
    for (size_t lod = 0u; lod < 4u; ++lod) {
        summary.lodVertices[lod] = entry.lod_vertices[lod];
        summary.lodTriangles[lod] = entry.lod_triangles[lod];
        summary.lodPrimitives[lod] = entry.lod_primitives[lod];
    }
    return summary;
}

