bool characterTestEvidenceMatchesTuning(
    const MdkrModernCharacterEntry *entry,
    const CharacterTuningEdit &tuning,
    const CharacterTestEvidenceStore::Evidence &evidence) {
    if (entry == nullptr || evidence.context < 1u || evidence.context > 4u) {
        return false;
    }
    return evidence.sourceSha256 == characterDigestHex(entry->source_sha256) &&
           evidence.fitSha256 == characterTestTuningSignature(
               entry, tuning, evidence.context - 1u);
}

const CharacterMotionReviewSessionResult *currentCharacterMotionReview(
    const MdkrModernCharacterEntry *entry,
    const CharacterTuningEdit &tuning,
    MdkrCharacterPreviewContext context,
    MdkrCharacterPreviewScene scene =
        MDKR_CHARACTER_PREVIEW_SCENE_BASELINE) {
    if (entry == nullptr || context < MDKR_CHARACTER_PREVIEW_SELECT ||
        context > MDKR_CHARACTER_PREVIEW_PLANE ||
        scene < MDKR_CHARACTER_PREVIEW_SCENE_BASELINE ||
        scene >= MDKR_CHARACTER_PREVIEW_SCENE_COUNT ||
        (context == MDKR_CHARACTER_PREVIEW_SELECT &&
         scene != MDKR_CHARACTER_PREVIEW_SCENE_BASELINE)) return nullptr;
    const auto package = g_characterMotionReviewResults.find(entry->id);
    if (package == g_characterMotionReviewResults.end()) return nullptr;
    const auto session = package->second.find(
        characterMotionReviewSceneKey(context, scene));
    if (session == package->second.end()) return nullptr;
    const CharacterMotionReviewSessionResult &value = session->second;
    const std::string fit = characterTestTuningSignature(
        entry, tuning, static_cast<unsigned>(context - 1));
    const std::string presentation = characterTestPresentationSignature();
    unsigned expectedCount = 0u;
    (void)characterMotionReviewDefinitions(context, expectedCount);
    return value.result.version ==
               MDKR_CHARACTER_MOTION_REVIEW_RESULT_VERSION &&
            value.result.started && value.result.completed &&
            value.result.context == context &&
            value.result.scene == scene &&
            value.result.sample_count == expectedCount &&
            value.result.completed_mask ==
                MDKR_CHARACTER_MOTION_REVIEW_SAMPLE_MASK(expectedCount) &&
            value.result.failed_sample == 0u &&
            characterMotionReviewContactStabilityValid(value.result) &&
            value.sourceSha256 == characterDigestHex(entry->source_sha256) &&
            !fit.empty() && value.fitSha256 == fit &&
            !presentation.empty() &&
            value.presentationSha256 == presentation
        ? &value : nullptr;
}

bool characterPreviewSessionMatchesTuning(
    const MdkrModernCharacterEntry *entry,
    const CharacterTuningEdit &tuning,
    MdkrCharacterPreviewContext context,
    const CharacterPreviewSessionResult &session) {
    if (entry == nullptr || context < MDKR_CHARACTER_PREVIEW_SELECT ||
        context > MDKR_CHARACTER_PREVIEW_PLANE) {
        return false;
    }
    return session.result.version ==
               MDKR_CHARACTER_PREVIEW_RESULT_VERSION &&
           session.result.started && session.result.context == context &&
           session.result.warmup_complete &&
           session.result.replacement_draws != 0u &&
           session.result.fit_diagnostics_valid != 0 &&
           mdkr_modern_character_gpu_timing_metrics_valid(
               &session.result.gpu_timing) != 0 &&
           characterPreviewFitDiagnosticsValid(session.result) &&
           characterPreviewCameraProjectionValid(session.result) &&
           characterPreviewVehicleSurfaceValid(session.result) &&
           characterPreviewOpaqueVisibilityValid(session.result) &&
           characterPreviewProjectionValid(session.result) &&
           characterPreviewContactDiagnosticsValid(session.result) &&
           characterPreviewJointDiagnosticsValid(session.result) &&
           (!characterJointDiagnosticsExpected(entry) ||
            session.result.joint_excursion_mask ==
                MDKR_CHARACTER_RIG_HUMANOID_MASK) &&
           (session.result.capture_requested
                ? session.result.capture_kind >=
                      MDKR_CHARACTER_PREVIEW_CAPTURE_SCENE &&
                      session.result.capture_kind <
                          MDKR_CHARACTER_PREVIEW_CAPTURE_COUNT
                : session.result.capture_kind ==
                      MDKR_CHARACTER_PREVIEW_CAPTURE_SCENE) &&
           ((session.result.pose == MDKR_CHARACTER_PREVIEW_POSE_LIVE &&
             session.result.pose_phase_milli == 0u &&
             session.result.transition_from_pose ==
                 MDKR_CHARACTER_PREVIEW_POSE_LIVE &&
             session.result.transition_from_phase_milli == 0u &&
             session.result.inspection_pose_ticks == 0u &&
             session.result.inspection_pose_fallback_ticks == 0u &&
             session.result.inspection_transition_switches == 0u &&
             session.result.inspection_transition_blending_ticks == 0u &&
             session.result.inspection_transition_completions == 0u &&
             session.result.transition_from_blend_milli == 0u &&
             session.result.transition_to_blend_milli == 0u &&
             session.result.transition_from_motion_source ==
                 MDKR_CHARACTER_PREVIEW_MOTION_NONE &&
             session.result.transition_to_motion_source ==
                 MDKR_CHARACTER_PREVIEW_MOTION_NONE &&
             session.result.view_yaw_degrees == 0 &&
             session.result.view_pitch_degrees == 0 &&
             session.result.lighting ==
                 MDKR_WORKSHOP_PREVIEW_LIGHTING_NEUTRAL &&
             session.result.camera_override_ticks == 0u &&
             session.result.lighting_override_draws == 0u &&
             !session.result.capture_requested &&
             !session.result.capture_armed &&
             session.result.capture_stable_frames == 0u &&
             !session.result.capture_written &&
             session.result.capture_png_bytes == 0u) ||
            (session.result.pose > MDKR_CHARACTER_PREVIEW_POSE_LIVE &&
             session.result.pose < MDKR_CHARACTER_PREVIEW_POSE_COUNT &&
             session.result.pose_phase_milli <= 1000u &&
             session.result.view_yaw_degrees >= -180 &&
             session.result.view_yaw_degrees <= 180 &&
             session.result.view_pitch_degrees >=
                 MDKR_WORKSHOP_PREVIEW_PITCH_MIN_DEGREES &&
             session.result.view_pitch_degrees <=
                 MDKR_WORKSHOP_PREVIEW_PITCH_MAX_DEGREES &&
             session.result.lighting >=
                 MDKR_WORKSHOP_PREVIEW_LIGHTING_NEUTRAL &&
             session.result.lighting <
                 MDKR_WORKSHOP_PREVIEW_LIGHTING_COUNT &&
             (session.result.lighting ==
                      MDKR_WORKSHOP_PREVIEW_LIGHTING_NEUTRAL
                  ? session.result.lighting_override_draws == 0u
                  : session.result.lighting_override_draws != 0u) &&
             ((session.result.view_yaw_degrees == 0 &&
               session.result.view_pitch_degrees == 0)
                  ? session.result.camera_override_ticks == 0u
                  : session.result.camera_override_ticks != 0u) &&
             (context != MDKR_CHARACTER_PREVIEW_SELECT ||
              (session.result.view_yaw_degrees == 0 &&
               session.result.view_pitch_degrees == 0 &&
               session.result.camera_override_ticks == 0u)) &&
             session.result.inspection_pose_ticks != 0u &&
             session.result.inspection_pose_fallback_ticks == 0u &&
             session.result.transition_from_motion_source >
                 MDKR_CHARACTER_PREVIEW_MOTION_NONE &&
             session.result.transition_from_motion_source <
                 MDKR_CHARACTER_PREVIEW_MOTION_COUNT &&
             (session.result.transition_from_pose ==
                      MDKR_CHARACTER_PREVIEW_POSE_LIVE
                  ? (session.result.transition_from_phase_milli == 0u &&
                     session.result.inspection_transition_switches == 0u &&
                     session.result.inspection_transition_blending_ticks ==
                         0u &&
                     session.result.inspection_transition_completions == 0u &&
                     session.result.transition_from_blend_milli == 0u &&
                     session.result.transition_to_blend_milli == 0u &&
                     session.result.transition_to_motion_source ==
                         MDKR_CHARACTER_PREVIEW_MOTION_NONE)
                  : (session.result.transition_from_pose >
                         MDKR_CHARACTER_PREVIEW_POSE_LIVE &&
                     session.result.transition_from_pose <
                         MDKR_CHARACTER_PREVIEW_POSE_COUNT &&
                     session.result.transition_from_pose !=
                         session.result.pose &&
                     session.result.transition_from_phase_milli <= 1000u &&
                     session.result.inspection_transition_switches != 0u &&
                     session.result.transition_to_motion_source >
                         MDKR_CHARACTER_PREVIEW_MOTION_NONE &&
                     session.result.transition_to_motion_source <
                         MDKR_CHARACTER_PREVIEW_MOTION_COUNT &&
                     !session.result.capture_requested)))) &&
           (session.result.capture_requested ==
                !session.capturePng.empty()) &&
           (session.result.capture_requested
                ? ((session.result.capture_armed
                        ? session.result.capture_stable_frames >=
                              MDKR_CHARACTER_PREVIEW_CAPTURE_STABLE_FRAMES
                        : session.result.capture_stable_frames <
                              MDKR_CHARACTER_PREVIEW_CAPTURE_STABLE_FRAMES) &&
                   (session.result.capture_written
                        ? session.result.capture_armed &&
                              session.result.capture_png_bytes != 0u
                        : session.result.capture_png_bytes == 0u))
                : (!session.result.capture_armed &&
                   session.result.capture_stable_frames == 0u &&
                   !session.result.capture_written &&
                   session.result.capture_png_bytes == 0u)) &&
           session.sourceSha256 ==
               characterDigestHex(entry->source_sha256) &&
           session.fitSha256 == characterTestTuningSignature(
               entry, tuning, static_cast<unsigned>(context - 1));
}

const CharacterTestEvidenceStore::Evidence *currentRenderedCharacterTestEvidence(
    const MdkrModernCharacterEntry *entry,
    const CharacterTuningEdit &tuning,
    MdkrCharacterPreviewContext context) {
    loadCharacterTestEvidence();
    const CharacterTestEvidenceStore::Evidence *newest = nullptr;
    for (uint32_t players = 1u; players <= 4u; ++players) {
        const CharacterTestEvidenceStore::Evidence *evidence =
            CharacterTestEvidenceStore::find(
                g_characterTestEvidence, entry->id,
                static_cast<uint32_t>(context), players,
                CharacterTestEvidenceStore::Kind::Latest);
        if (evidence != nullptr &&
            evidence->resultVersion ==
                MDKR_CHARACTER_PREVIEW_RESULT_VERSION &&
            evidence->started && evidence->warmupComplete &&
            evidence->replacementDraws != 0u &&
            evidence->fitDiagnosticsValid &&
            characterTestEvidenceMatchesTuning(entry, tuning, *evidence) &&
            (newest == nullptr ||
             evidence->capturedUnix > newest->capturedUnix)) {
            newest = evidence;
        }
    }
    return newest;
}

/* Keep renderer evidence value-owned while the editor is drawing. Tuning
 * persistence deliberately invalidates session evidence, and durable evidence
 * lookups point into a store that may be refreshed. No UI action should retain
 * either iterator/pointer across an edit. */
struct CharacterFitEvidenceSnapshot {
    bool current = false;
    bool fromDurableStore = false;
    uint32_t players = 0u;
    MdkrCharacterPreviewResult result{};
    std::string sourceSha256;
    std::string fitSha256;
};

CharacterFitEvidenceSnapshot currentCharacterFitEvidenceSnapshot(
    const MdkrModernCharacterEntry *entry,
    const CharacterTuningEdit &tuning,
    MdkrCharacterPreviewContext context) {
    CharacterFitEvidenceSnapshot snapshot;
    const auto session = g_characterPreviewResults.find(entry->id);
    if (session != g_characterPreviewResults.end() &&
        characterPreviewSessionMatchesTuning(
            entry, tuning, context, session->second)) {
        snapshot.current = true;
        snapshot.players = static_cast<uint32_t>(
            std::max(0, session->second.result.players));
        snapshot.result = session->second.result;
        snapshot.sourceSha256 = session->second.sourceSha256;
        snapshot.fitSha256 = session->second.fitSha256;
        return snapshot;
    }

    const CharacterMotionReviewSessionResult *motion =
        currentCharacterMotionReview(entry, tuning, context);
    if (motion != nullptr) {
        snapshot.current = true;
        snapshot.players = 1u;
        snapshot.result = motion->result.samples[
            MDKR_CHARACTER_MOTION_REVIEW_START];
        snapshot.sourceSha256 = motion->sourceSha256;
        snapshot.fitSha256 = motion->fitSha256;
        return snapshot;
    }

    const CharacterTestEvidenceStore::Evidence *durable =
        currentRenderedCharacterTestEvidence(entry, tuning, context);
    if (durable == nullptr) return snapshot;
    snapshot.current = true;
    snapshot.fromDurableStore = true;
    snapshot.players = durable->players;
    snapshot.result = characterPreviewResultFromEvidence(*durable);
    snapshot.sourceSha256 = durable->sourceSha256;
    snapshot.fitSha256 = durable->fitSha256;
    return snapshot;
}

enum class CharacterSpatialPlane : int {
    Front = 0,
    Side,
    Top,
};

struct CharacterSpatialAxes {
    unsigned horizontal;
    unsigned vertical;
    const char *horizontalName;
    const char *verticalName;
};

struct CharacterSpatialEditResult {
    bool changed = false;
    bool commit = false;
};

CharacterSpatialAxes characterSpatialAxes(CharacterSpatialPlane plane) {
    switch (plane) {
        case CharacterSpatialPlane::Side:
            return {2u, 1u, "Z", "Y"};
        case CharacterSpatialPlane::Top:
            return {0u, 2u, "X", "Z"};
        case CharacterSpatialPlane::Front:
        default:
            return {0u, 1u, "X", "Y"};
    }
}

void drawCharacterFitOverlay(const MdkrCharacterPreviewResult &result,
                             int selectedView, bool compact) {
    struct View {
        const char *name;
        unsigned horizontal;
        unsigned vertical;
    };
    static const View views[] = {
        {"Front · X/Y", 0u, 1u},
        {"Side · Z/Y", 2u, 1u},
        {"Top · X/Z", 0u, 2u},
    };
    if (!result.fit_diagnostics_valid) return;
    const int firstView = selectedView >= 0
        ? std::clamp(selectedView, 0, 2) : 0;
    const int viewCount = selectedView >= 0 ? 1 : 3;
    const std::string traceKey =
        std::to_string(static_cast<unsigned>(result.context)) + ":" +
        std::to_string(firstView) + ":" + std::to_string(viewCount);
    if (std::getenv("MDKR_APP_UI_TRACE") != nullptr &&
        g_characterFitOverlayTraceResults.insert(traceKey).second) {
        std::fprintf(
            stderr,
            "[app-ui] character-fit-overlay context=%u views=%d coordinate-space=donor-target bounds=calibrated anchor=ground-or-seat forward=measured accessible=focusable-plots-plus-numeric\n",
            static_cast<unsigned>(result.context), viewCount);
    }
    ui::TextSubtleWrapped(
        selectedView >= 0
            ? "Measured target-space fit in the same plane as the editor. The shaded rectangle is the calibrated volume; the diamond is the fitted ground or seat anchor after authored corrections; the blue arrow is the rendered forward direction."
            : "Exact target-space fit from the successful replacement draw. The shaded rectangle is the calibrated volume; the diamond is the fitted ground or seat anchor after authored corrections; the blue arrow is the rendered forward direction.");
    ui::TextSubtleWrapped(
        "Use the plot to inspect fit; use the adjacent numeric controls to make precise keyboard or controller changes.");
    const float available = ImGui::GetContentRegionAvail().x;
    const int columns = viewCount == 1 ? 1
        : available >= 780.0f ? 3 : available >= 500.0f ? 2 : 1;
    // Keep keyboard/navigation identity tied to the semantic plot, including
    // when durable evidence is materialized into a temporary result object.
    ImGui::PushID("character-fit-overlay");
    ImGui::PushID(static_cast<int>(result.context));
    ImGui::PushID(selectedView);
    if (ImGui::BeginTable("##fit-overlay-views", columns,
                          ImGuiTableFlags_SizingStretchSame)) {
        for (int offset = 0; offset < viewCount; ++offset) {
            const int viewIndex = firstView + offset;
            const View &view = views[viewIndex];
            const unsigned horizontal = view.horizontal;
            const unsigned vertical = view.vertical;
            ImGui::TableNextColumn();
            ImGui::PushID(viewIndex);
            ImGui::TextUnformatted(view.name);
            const float uiScale = AppTheme::uiScale();
            const float width = std::max(
                1.0f, ImGui::GetContentRegionAvail().x);
            const float requestedHeight =
                (compact ? 145.0f : 180.0f) * uiScale;
            const ImVec2 size(width, requestedHeight);
            const ImVec2 origin = ImGui::GetCursorScreenPos();
            ImGui::InvisibleButton("##target-space-fit", size);
            const char *smokeFocus = std::getenv(
                "MDKR_APP_SMOKE_CHARACTER_FIT_OVERLAY_FOCUS");
            if (offset == 0 && viewCount == 3 && smokeFocus != nullptr &&
                std::strcmp(
                    smokeFocus,
                    "mdkr64-character-fit-overlay-v1") == 0) {
                // Render-evidence seam only: keep the authoritative plot in the
                // capture viewport without synthesizing or changing its data.
                ImGui::SetScrollHereY(0.35f);
                if (!g_characterFitOverlaySmokeFocusTraced) {
                    g_characterFitOverlaySmokeFocusTraced = true;
                    std::fprintf(
                        stderr,
                        "[app-ui] character-fit-overlay-focus applied=1 context=%u views=3\n",
                        static_cast<unsigned>(result.context));
                }
            }
            const bool focused = ImGui::IsItemFocused();
            char spoken[640];
            std::snprintf(
                spoken, sizeof(spoken),
                "%s renderer fit. Bounds %s %+.3f to %+.3f metres and %s %+.3f to %+.3f metres. Anchor %s %+.3f and %s %+.3f metres. Forward X %+.3f, Y %+.3f, Z %+.3f.",
                view.name,
                characterSpatialAxes(static_cast<CharacterSpatialPlane>(
                    viewIndex)).horizontalName,
                result.fit_bounds_min_micrometres[horizontal] / 1000000.0,
                result.fit_bounds_max_micrometres[horizontal] / 1000000.0,
                characterSpatialAxes(static_cast<CharacterSpatialPlane>(
                    viewIndex)).verticalName,
                result.fit_bounds_min_micrometres[vertical] / 1000000.0,
                result.fit_bounds_max_micrometres[vertical] / 1000000.0,
                characterSpatialAxes(static_cast<CharacterSpatialPlane>(
                    viewIndex)).horizontalName,
                result.fit_anchor_micrometres[horizontal] / 1000000.0,
                characterSpatialAxes(static_cast<CharacterSpatialPlane>(
                    viewIndex)).verticalName,
                result.fit_anchor_micrometres[vertical] / 1000000.0,
                result.fit_forward_milli[0] / 1000.0,
                result.fit_forward_milli[1] / 1000.0,
                result.fit_forward_milli[2] / 1000.0);
            ui::SpeakFocusedItem(view.name, nullptr, spoken);

            const long long spans[3] = {
                result.fit_bounds_max_micrometres[0] -
                    result.fit_bounds_min_micrometres[0],
                result.fit_bounds_max_micrometres[1] -
                    result.fit_bounds_min_micrometres[1],
                result.fit_bounds_max_micrometres[2] -
                    result.fit_bounds_min_micrometres[2],
            };
            const double maximumSpan = static_cast<double>(std::max(
                {spans[0], spans[1], spans[2], 1LL}));
            const double arrowLength = std::clamp(
                maximumSpan * 0.35, 100000.0, 500000.0);
            long long forwardEnd[3];
            for (unsigned axis = 0u; axis < 3u; ++axis) {
                forwardEnd[axis] = result.fit_anchor_micrometres[axis] +
                    static_cast<long long>(std::llround(
                        result.fit_forward_milli[axis] *
                        arrowLength / 1000.0));
            }
            double lowH = static_cast<double>(std::min(
                {0LL, result.fit_bounds_min_micrometres[horizontal],
                 result.fit_anchor_micrometres[horizontal],
                 forwardEnd[horizontal]}));
            double highH = static_cast<double>(std::max(
                {0LL, result.fit_bounds_max_micrometres[horizontal],
                 result.fit_anchor_micrometres[horizontal],
                 forwardEnd[horizontal]}));
            double lowV = static_cast<double>(std::min(
                {0LL, result.fit_bounds_min_micrometres[vertical],
                 result.fit_anchor_micrometres[vertical],
                 forwardEnd[vertical]}));
            double highV = static_cast<double>(std::max(
                {0LL, result.fit_bounds_max_micrometres[vertical],
                 result.fit_anchor_micrometres[vertical],
                 forwardEnd[vertical]}));
            const double spanH = std::max(1000.0, highH - lowH);
            const double spanV = std::max(1000.0, highV - lowV);
            lowH -= spanH * 0.14;
            highH += spanH * 0.14;
            lowV -= spanV * 0.14;
            highV += spanV * 0.14;
            const float pad = std::min(12.0f * uiScale, size.x * 0.1f);
            const ImVec2 maximum(origin.x + size.x, origin.y + size.y);
            const auto project = [&](const long long point[3]) {
                return ImVec2(
                    origin.x + pad + static_cast<float>(
                        (point[horizontal] - lowH) / (highH - lowH)) *
                            (size.x - 2.0f * pad),
                    maximum.y - pad - static_cast<float>(
                        (point[vertical] - lowV) / (highV - lowV)) *
                            (size.y - 2.0f * pad));
            };
            ImDrawList *draw = ImGui::GetWindowDrawList();
            draw->AddRectFilled(origin, maximum, IM_COL32(12, 17, 24, 255),
                                6.0f * uiScale);
            draw->AddRect(
                origin, maximum,
                focused ? ImGui::GetColorU32(ImGuiCol_NavHighlight)
                        : IM_COL32(74, 86, 102, 255),
                6.0f * uiScale, 0, (focused ? 2.0f : 1.0f) * uiScale);
            long long zero[3] = {};
            const ImVec2 zeroPoint = project(zero);
            const ImU32 datumColour = IM_COL32(241, 196, 83, 220);
            draw->AddLine(
                ImVec2(origin.x + pad * 0.5f, zeroPoint.y),
                ImVec2(maximum.x - pad * 0.5f, zeroPoint.y),
                vertical == 1u ? datumColour : IM_COL32(75, 84, 96, 160),
                vertical == 1u ? 2.0f * uiScale : 1.0f * uiScale);
            draw->AddLine(
                ImVec2(zeroPoint.x, origin.y + pad * 0.5f),
                ImVec2(zeroPoint.x, maximum.y - pad * 0.5f),
                IM_COL32(75, 84, 96, 160), 1.0f * uiScale);
            long long boundsLow[3] = {};
            long long boundsHigh[3] = {};
            boundsLow[horizontal] =
                result.fit_bounds_min_micrometres[horizontal];
            boundsLow[vertical] =
                result.fit_bounds_min_micrometres[vertical];
            boundsHigh[horizontal] =
                result.fit_bounds_max_micrometres[horizontal];
            boundsHigh[vertical] =
                result.fit_bounds_max_micrometres[vertical];
            const ImVec2 boxLow = project(boundsLow);
            const ImVec2 boxHigh = project(boundsHigh);
            const ImVec2 boxMinimum(
                std::min(boxLow.x, boxHigh.x),
                std::min(boxLow.y, boxHigh.y));
            const ImVec2 boxMaximum(
                std::max(boxLow.x, boxHigh.x),
                std::max(boxLow.y, boxHigh.y));
            draw->AddRectFilled(boxMinimum, boxMaximum,
                                IM_COL32(119, 144, 172, 42));
            draw->AddRect(boxMinimum, boxMaximum,
                          IM_COL32(160, 181, 205, 230), 0.0f, 0,
                          1.5f * uiScale);
            const ImVec2 anchor = project(result.fit_anchor_micrometres);
            const float diamond = 5.5f * uiScale;
            draw->AddQuadFilled(
                ImVec2(anchor.x, anchor.y - diamond),
                ImVec2(anchor.x + diamond, anchor.y),
                ImVec2(anchor.x, anchor.y + diamond),
                ImVec2(anchor.x - diamond, anchor.y), datumColour);
            const ImVec2 forward = project(forwardEnd);
            const ImU32 forwardColour = IM_COL32(80, 190, 255, 255);
            draw->AddLine(anchor, forward, forwardColour, 3.0f * uiScale);
            const float arrowX = forward.x - anchor.x;
            const float arrowY = forward.y - anchor.y;
            const float arrowPixels = std::sqrt(
                arrowX * arrowX + arrowY * arrowY);
            char forwardLabel[64] = "Forward";
            if (arrowPixels > 1.0f) {
                const float unitX = arrowX / arrowPixels;
                const float unitY = arrowY / arrowPixels;
                const float head = 9.0f * uiScale;
                const float wing = 4.5f * uiScale;
                const ImVec2 base(
                    forward.x - unitX * head,
                    forward.y - unitY * head);
                draw->AddTriangleFilled(
                    forward,
                    ImVec2(base.x - unitY * wing,
                           base.y + unitX * wing),
                    ImVec2(base.x + unitY * wing,
                           base.y - unitX * wing),
                    forwardColour);
            } else {
                static const char *const axisNames[] = {"X", "Y", "Z"};
                const unsigned omittedAxis = 3u - horizontal - vertical;
                const bool positive =
                    result.fit_forward_milli[omittedAxis] >= 0;
                const float ring = 10.0f * uiScale;
                draw->AddCircle(anchor, ring, forwardColour, 0,
                                2.0f * uiScale);
                if (positive) {
                    draw->AddCircleFilled(
                        anchor, 3.0f * uiScale, forwardColour);
                } else {
                    const float cross = 4.0f * uiScale;
                    draw->AddLine(
                        ImVec2(anchor.x - cross, anchor.y - cross),
                        ImVec2(anchor.x + cross, anchor.y + cross),
                        forwardColour, 2.0f * uiScale);
                    draw->AddLine(
                        ImVec2(anchor.x - cross, anchor.y + cross),
                        ImVec2(anchor.x + cross, anchor.y - cross),
                        forwardColour, 2.0f * uiScale);
                }
                std::snprintf(
                    forwardLabel, sizeof(forwardLabel),
                    "Forward %c%s · %s",
                    positive ? '+' : '-', axisNames[omittedAxis],
                    positive ? "out" : "in");
            }
            draw->AddText(
                ImVec2(origin.x + 7.0f * uiScale,
                       origin.y + 6.0f * uiScale),
                IM_COL32(197, 211, 226, 255), "Bounds");
            draw->AddText(
                ImVec2(std::min(maximum.x - 68.0f * uiScale,
                                anchor.x + 7.0f * uiScale),
                       anchor.y + 3.0f * uiScale),
                datumColour, "Anchor");
            draw->AddText(
                ImVec2(std::min(maximum.x - 58.0f * uiScale,
                                forward.x + 5.0f * uiScale),
                       forward.y - 15.0f * uiScale),
                forwardColour, forwardLabel);
            if (vertical == 1u) {
                draw->AddText(
                    ImVec2(origin.x + 7.0f * uiScale,
                           zeroPoint.y + 3.0f * uiScale),
                    datumColour,
                    result.context == MDKR_CHARACTER_PREVIEW_SELECT
                        ? "Floor" : "Seat datum");
            }
            ImGui::PopID();
        }
        ImGui::EndTable();
    }
    ImGui::PopID();
    ImGui::PopID();
    ImGui::PopID();
    ui::TextSubtleWrapped(
        "Legend: shaded rectangle = calibrated bounds; gold diamond = fitted anchor after authored corrections; gold line = target floor or seat datum; blue arrow = measured target-space forward. A blue ring with a dot means forward points out of that view; a ring with a cross means it points inward. Exact coordinates and alignment warnings follow below.");
}

void drawCharacterContactDiagnostics(
    const MdkrCharacterPreviewResult &result) {
    if (result.context == MDKR_CHARACTER_PREVIEW_SELECT) return;
    if (result.contact_witness_mask == 0u) {
        ui::TextSubtleWrapped(
            "No post-solve contact witness was published. This is expected for an explicitly authored clip or a rig without the reviewed humanoid role map; automatic hand/foot placement remains unproven.");
        return;
    }
    static const char *const contactNames[] = {
        "Left hand", "Right hand", "Left foot", "Right foot",
    };
    static const char *const contactShort[] = {"LH", "RH", "LF", "RF"};
    static const ImU32 contactColours[] = {
        IM_COL32(83, 196, 255, 255), IM_COL32(255, 174, 66, 255),
        IM_COL32(133, 224, 125, 255), IM_COL32(232, 118, 188, 255),
    };
    struct View { const char *name; unsigned horizontal; unsigned vertical; };
    static const View views[] = {
        {"Front · X/Y", 0u, 1u}, {"Side · Z/Y", 2u, 1u},
        {"Top · X/Z", 0u, 2u},
    };
    if (std::getenv("MDKR_APP_UI_TRACE") != nullptr) {
        static std::set<std::string> traced;
        const std::string key = std::to_string(result.context) + ":" +
            std::to_string(result.contact_witness_mask) + ":" +
            std::to_string(result.contact_witness_error_micrometres[0]) +
            ":" +
            std::to_string(result.contact_witness_error_micrometres[3]);
        if (traced.insert(key).second) {
            std::fprintf(
                stderr,
                "[app-ui] character-contact-proof context=%u mask=%x views=3 coordinate-space=donor-target errorsUm=%llu,%llu,%llu,%llu accessible=numeric-table\n",
                static_cast<unsigned>(result.context),
                result.contact_witness_mask,
                result.contact_witness_error_micrometres[0],
                result.contact_witness_error_micrometres[1],
                result.contact_witness_error_micrometres[2],
                result.contact_witness_error_micrometres[3]);
        }
    }
    ImGui::SeparatorText("Hand & foot contact proof");
    ui::TextSubtleWrapped(
        "Exact latest post-solve chains from the successful replacement draw. The cross is the tuned target; the solid endpoint and connecting error line show where the hand or foot actually landed. All views use donor target space, not source-model axes.");
    const float available = ImGui::GetContentRegionAvail().x;
    const int columns = available >= 780.0f ? 3 : available >= 500.0f ? 2 : 1;
    if (ImGui::BeginTable("##contact-witness-views", columns,
                          ImGuiTableFlags_SizingStretchSame)) {
        for (unsigned viewIndex = 0u; viewIndex < std::size(views);
             ++viewIndex) {
            const View &view = views[viewIndex];
            ImGui::TableNextColumn();
            ImGui::PushID(static_cast<int>(viewIndex));
            ImGui::TextUnformatted(view.name);
            const float uiScale = AppTheme::uiScale();
            const float width = std::max(
                1.0f, ImGui::GetContentRegionAvail().x);
            const ImVec2 size(width, 190.0f * uiScale);
            const ImVec2 origin = ImGui::GetCursorScreenPos();
            (void)ImGui::Selectable(
                "Contact witness plot", false, ImGuiSelectableFlags_None,
                size);
            const bool focused = ImGui::IsItemFocused();
            ui::SpeakFocusedItem(
                view.name, nullptr,
                "Exact contact plot. Root to bend to endpoint is the solved chain; crosses are targets. The numeric table after the plots gives every error and coordinate.");
            ImDrawList *draw = ImGui::GetWindowDrawList();
            const ImVec2 maximum(origin.x + size.x, origin.y + size.y);
            const float padX = std::min(10.0f * uiScale, size.x * 0.1f);
            const float padY = std::min(10.0f * uiScale, size.y * 0.1f);
            draw->AddRectFilled(origin, maximum, IM_COL32(12, 17, 24, 255),
                                6.0f * uiScale);
            draw->AddRect(origin, maximum,
                          focused ? ImGui::GetColorU32(ImGuiCol_NavHighlight)
                                  : IM_COL32(74, 86, 102, 255),
                          6.0f * uiScale, 0,
                          (focused ? 2.0f : 1.0f) * uiScale);
            double lowH = std::min<long long>(
                0, result.fit_bounds_min_micrometres[view.horizontal]);
            double highH = std::max<long long>(
                0, result.fit_bounds_max_micrometres[view.horizontal]);
            double lowV = std::min<long long>(
                0, result.fit_bounds_min_micrometres[view.vertical]);
            double highV = std::max<long long>(
                0, result.fit_bounds_max_micrometres[view.vertical]);
            for (unsigned contact = 0u;
                 contact < MDKR_CHARACTER_PREVIEW_CONTACTS; ++contact) {
                const long long *points[] = {
                    result.contact_chain_root_micrometres[contact],
                    result.contact_bend_micrometres[contact],
                    result.contact_target_micrometres[contact],
                    result.contact_end_micrometres[contact],
                };
                for (const long long *point : points) {
                    lowH = std::min(lowH,
                        static_cast<double>(point[view.horizontal]));
                    highH = std::max(highH,
                        static_cast<double>(point[view.horizontal]));
                    lowV = std::min(lowV,
                        static_cast<double>(point[view.vertical]));
                    highV = std::max(highV,
                        static_cast<double>(point[view.vertical]));
                }
            }
            const double spanH = std::max(1000.0, highH - lowH);
            const double spanV = std::max(1000.0, highV - lowV);
            lowH -= spanH * 0.12; highH += spanH * 0.12;
            lowV -= spanV * 0.12; highV += spanV * 0.12;
            const auto project = [&](const long long point[3]) {
                const float x = origin.x + padX +
                    static_cast<float>((point[view.horizontal] - lowH) /
                        (highH - lowH)) * (size.x - 2.0f * padX);
                const float y = maximum.y - padY -
                    static_cast<float>((point[view.vertical] - lowV) /
                        (highV - lowV)) * (size.y - 2.0f * padY);
                return ImVec2(x, y);
            };
            long long zero[3] = {};
            const ImVec2 zeroPoint = project(zero);
            draw->AddLine(ImVec2(origin.x + 5.0f * uiScale, zeroPoint.y),
                          ImVec2(maximum.x - 5.0f * uiScale, zeroPoint.y),
                          IM_COL32(75, 84, 96, 150));
            draw->AddLine(ImVec2(zeroPoint.x, origin.y + 5.0f * uiScale),
                          ImVec2(zeroPoint.x, maximum.y - 5.0f * uiScale),
                          IM_COL32(75, 84, 96, 150));
            long long boundsLow[3] = {};
            long long boundsHigh[3] = {};
            boundsLow[view.horizontal] =
                result.fit_bounds_min_micrometres[view.horizontal];
            boundsLow[view.vertical] =
                result.fit_bounds_min_micrometres[view.vertical];
            boundsHigh[view.horizontal] =
                result.fit_bounds_max_micrometres[view.horizontal];
            boundsHigh[view.vertical] =
                result.fit_bounds_max_micrometres[view.vertical];
            ImVec2 boxA = project(boundsLow);
            ImVec2 boxB = project(boundsHigh);
            draw->AddRect(ImVec2(boxA.x, boxB.y), ImVec2(boxB.x, boxA.y),
                          IM_COL32(150, 160, 174, 150), 0.0f, 0, 1.0f);
            for (unsigned contact = 0u;
                 contact < MDKR_CHARACTER_PREVIEW_CONTACTS; ++contact) {
                const ImVec2 root = project(
                    result.contact_chain_root_micrometres[contact]);
                const ImVec2 bend = project(
                    result.contact_bend_micrometres[contact]);
                const ImVec2 target = project(
                    result.contact_target_micrometres[contact]);
                const ImVec2 end = project(
                    result.contact_end_micrometres[contact]);
                const ImU32 colour = contactColours[contact];
                draw->AddLine(root, bend, colour, 2.0f * uiScale);
                draw->AddLine(bend, end, colour, 2.0f * uiScale);
                draw->AddLine(end, target, IM_COL32(255, 235, 115, 255),
                              2.0f * uiScale);
                draw->AddCircle(root, 3.0f * uiScale, colour, 0,
                                1.5f * uiScale);
                draw->AddCircleFilled(bend, 3.0f * uiScale, colour);
                if (contact < 2u) {
                    draw->AddCircleFilled(end, 4.0f * uiScale, colour);
                } else {
                    draw->AddRectFilled(
                        ImVec2(end.x - 4.0f * uiScale,
                               end.y - 4.0f * uiScale),
                        ImVec2(end.x + 4.0f * uiScale,
                               end.y + 4.0f * uiScale), colour);
                }
                draw->AddLine(
                    ImVec2(target.x - 5.0f * uiScale, target.y),
                    ImVec2(target.x + 5.0f * uiScale, target.y),
                    IM_COL32(255, 255, 255, 255), 1.5f * uiScale);
                draw->AddLine(
                    ImVec2(target.x, target.y - 5.0f * uiScale),
                    ImVec2(target.x, target.y + 5.0f * uiScale),
                    IM_COL32(255, 255, 255, 255), 1.5f * uiScale);
                draw->AddText(ImVec2(target.x + 6.0f * uiScale,
                                     target.y - 8.0f * uiScale),
                              colour, contactShort[contact]);
            }
            ImGui::PopID();
        }
        ImGui::EndTable();
    }
    const auto contactSpeech = [&](unsigned contact, char *text,
                                   size_t size) {
        const long long *target =
            result.contact_target_micrometres[contact];
        const long long *end = result.contact_end_micrometres[contact];
        std::snprintf(
            text, size,
            "Endpoint error %.2f millimetres. Target X %+.3f, Y %+.3f, Z %+.3f metres. Endpoint X %+.3f, Y %+.3f, Z %+.3f metres.",
            result.contact_witness_error_micrometres[contact] / 1000.0,
            target[0] / 1000000.0, target[1] / 1000000.0,
            target[2] / 1000000.0, end[0] / 1000000.0,
            end[1] / 1000000.0, end[2] / 1000000.0);
    };
    if (columns < 3) {
        for (unsigned contact = 0u;
             contact < MDKR_CHARACTER_PREVIEW_CONTACTS; ++contact) {
            ImGui::PushID(100 + static_cast<int>(contact));
            char spoken[384];
            contactSpeech(contact, spoken, sizeof(spoken));
            ImGui::PushStyleColor(
                ImGuiCol_Text,
                ImGui::ColorConvertU32ToFloat4(contactColours[contact]));
            (void)ImGui::Selectable(contactNames[contact], false);
            ImGui::PopStyleColor();
            ui::SpeakFocusedItem(contactNames[contact], nullptr, spoken);
            ImGui::TextWrapped("%s", spoken);
            ImGui::PopID();
        }
    } else if (ImGui::BeginTable("##contact-witness-values", 3,
                                 ImGuiTableFlags_RowBg |
                                 ImGuiTableFlags_SizingStretchProp)) {
        ImGui::TableSetupColumn("Contact", ImGuiTableColumnFlags_WidthStretch, 1.0f);
        ImGui::TableSetupColumn("Endpoint error", ImGuiTableColumnFlags_WidthStretch, 1.0f);
        ImGui::TableSetupColumn("Target to endpoint (X, Y, Z m)", ImGuiTableColumnFlags_WidthStretch, 2.0f);
        ImGui::TableHeadersRow();
        for (unsigned contact = 0u;
             contact < MDKR_CHARACTER_PREVIEW_CONTACTS; ++contact) {
            ImGui::TableNextRow();
            ImGui::TableNextColumn();
            ImGui::PushID(100 + static_cast<int>(contact));
            char spoken[384];
            contactSpeech(contact, spoken, sizeof(spoken));
            ImGui::PushStyleColor(
                ImGuiCol_Text,
                ImGui::ColorConvertU32ToFloat4(contactColours[contact]));
            (void)ImGui::Selectable(contactNames[contact], false);
            ImGui::PopStyleColor();
            ui::SpeakFocusedItem(contactNames[contact], nullptr, spoken);
            ImGui::TableNextColumn();
            ImGui::Text("%.2f mm",
                result.contact_witness_error_micrometres[contact] / 1000.0);
            ImGui::TableNextColumn();
            const long long *target =
                result.contact_target_micrometres[contact];
            const long long *end = result.contact_end_micrometres[contact];
            ImGui::TextWrapped("%+.3f,%+.3f,%+.3f to %+.3f,%+.3f,%+.3f",
                target[0] / 1000000.0, target[1] / 1000000.0,
                target[2] / 1000000.0, end[0] / 1000000.0,
                end[1] / 1000000.0, end[2] / 1000000.0);
            ImGui::PopID();
        }
        ImGui::EndTable();
    }
    ui::TextSubtleWrapped(
        "Root and bend markers expose elbows/knees folding to the wrong side; target-to-endpoint lines expose unreachable or mistuned controls. Re-run this exact context after changing fit or contact offsets—the evidence is tied to that tested fit.");
}

CharacterSpatialPlane drawCharacterSpatialPlaneSelector(
    const char *id, int &stored) {
    stored = std::clamp(stored, 0, 2);
    static const char *names[] = {"Front X/Y", "Side Z/Y", "Top X/Z"};
    ImGui::PushID(id);
    const int columns = ImGui::GetContentRegionAvail().x >= 410.0f ? 3 : 1;
    if (ImGui::BeginTable(
            "##spatial-plane-options", columns,
            ImGuiTableFlags_SizingStretchSame)) {
        for (int candidate = 0; candidate < 3; ++candidate) {
            ImGui::TableNextColumn();
            if (ImGui::RadioButton(names[candidate], &stored, candidate)) {
                stored = candidate;
            }
            ui::SpeakFocusedItem(
                names[candidate],
                candidate == stored ? "selected" : "not selected",
                "Changes only the spatial control view; it never changes the saved fit.");
        }
        ImGui::EndTable();
    }
    ImGui::PopID();
    return static_cast<CharacterSpatialPlane>(stored);
}

float characterSpatialRange(const float (*markers)[3], unsigned markerCount,
                            const CharacterSpatialAxes &axes,
                            float minimumRange, float maximumValue) {
    float range = minimumRange;
    for (unsigned marker = 0u; marker < markerCount; ++marker) {
        range = std::max(range,
                         std::fabs(markers[marker][axes.horizontal]) * 1.25f);
        range = std::max(range,
                         std::fabs(markers[marker][axes.vertical]) * 1.25f);
    }
    return std::min(range, maximumValue);
}

CharacterSpatialEditResult drawCharacterSpatialPad(
    const char *id, const char *accessibleName, float (*markers)[3],
    unsigned markerCount, unsigned selectedMarker,
    CharacterSpatialPlane plane, float minimumRange, float maximumValue,
    float nudgeStep, const char *zeroLabel,
    const char *const *markerNames) {
    CharacterSpatialEditResult result;
    if (markers == nullptr || markerCount == 0u ||
        selectedMarker >= markerCount) return result;
    const CharacterSpatialAxes axes = characterSpatialAxes(plane);
    const float range = characterSpatialRange(
        markers, markerCount, axes, minimumRange, maximumValue);
    const float available = std::max(1.0f, ImGui::GetContentRegionAvail().x);
    const float side = std::min(available, 340.0f);
    const ImVec2 origin = ImGui::GetCursorScreenPos();
    ImGui::InvisibleButton(id, ImVec2(side, side));
    const ImGuiID itemId = ImGui::GetItemID();
    ImDrawList *draw = ImGui::GetWindowDrawList();
    const ImVec2 maximum(origin.x + side, origin.y + side);
    const ImVec2 center(origin.x + side * 0.5f, origin.y + side * 0.5f);
    const float half = side * 0.43f;
    draw->AddRectFilled(origin, maximum, IM_COL32(20, 24, 31, 255), 6.0f);
    draw->AddRect(origin, maximum, IM_COL32(255, 255, 255, 42), 6.0f);
    for (int grid = -2; grid <= 2; ++grid) {
        const float delta = half * static_cast<float>(grid) / 2.0f;
        const ImU32 color = grid == 0
            ? IM_COL32(255, 255, 255, 105)
            : IM_COL32(255, 255, 255, 28);
        draw->AddLine(ImVec2(center.x + delta, center.y - half),
                      ImVec2(center.x + delta, center.y + half), color,
                      grid == 0 ? 1.5f : 1.0f);
        draw->AddLine(ImVec2(center.x - half, center.y + delta),
                      ImVec2(center.x + half, center.y + delta), color,
                      grid == 0 ? 1.5f : 1.0f);
    }
    draw->AddText(ImVec2(origin.x + 8.0f, origin.y + 7.0f),
                  IM_COL32(180, 190, 205, 255), axes.verticalName);
    draw->AddText(ImVec2(maximum.x - 18.0f, center.y + 5.0f),
                  IM_COL32(180, 190, 205, 255), axes.horizontalName);
    if (zeroLabel != nullptr) {
        draw->AddText(ImVec2(origin.x + 8.0f, maximum.y - 22.0f),
                      IM_COL32(180, 190, 205, 255), zeroLabel);
    }
    const ImU32 markerColors[MDKR_MODERN_CHARACTER_CONTACTS] = {
        IM_COL32(74, 191, 255, 255), IM_COL32(255, 119, 196, 255),
        IM_COL32(106, 221, 138, 255), IM_COL32(255, 194, 92, 255),
    };
    for (unsigned marker = 0u; marker < markerCount; ++marker) {
        const float x = std::clamp(
            markers[marker][axes.horizontal] / range, -1.0f, 1.0f);
        const float y = std::clamp(
            markers[marker][axes.vertical] / range, -1.0f, 1.0f);
        const ImVec2 point(center.x + x * half, center.y - y * half);
        const ImU32 color = markerCount == 1u
            ? IM_COL32(91, 192, 255, 255)
            : markerColors[marker % MDKR_MODERN_CHARACTER_CONTACTS];
        draw->AddCircleFilled(point, marker == selectedMarker ? 7.0f : 4.5f,
                              color);
        if (marker == selectedMarker) {
            draw->AddCircle(point, 11.0f, IM_COL32(255, 255, 255, 210),
                            0, 1.5f);
        }
    }
    if (ImGui::IsItemActive()) {
        const ImVec2 delta = ImGui::GetIO().MouseDelta;
        if (delta.x != 0.0f || delta.y != 0.0f) {
            float *value = markers[selectedMarker];
            const float unitsPerPixel = range / half;
            value[axes.horizontal] = std::clamp(
                value[axes.horizontal] + delta.x * unitsPerPixel,
                -maximumValue, maximumValue);
            value[axes.vertical] = std::clamp(
                value[axes.vertical] - delta.y * unitsPerPixel,
                -maximumValue, maximumValue);
            g_characterSpatialGestureDirty[itemId] = true;
            result.changed = true;
        }
    }
    if (ImGui::IsItemHovered() &&
        ImGui::IsMouseDoubleClicked(ImGuiMouseButton_Left)) {
        markers[selectedMarker][axes.horizontal] = 0.0f;
        markers[selectedMarker][axes.vertical] = 0.0f;
        g_characterSpatialGestureDirty.erase(itemId);
        result.changed = result.commit = true;
    } else if (ImGui::IsItemDeactivated()) {
        const auto dirty = g_characterSpatialGestureDirty.find(itemId);
        if (dirty != g_characterSpatialGestureDirty.end() && dirty->second) {
            g_characterSpatialGestureDirty.erase(dirty);
            result.commit = true;
        }
    }
    char state[192];
    std::snprintf(
        state, sizeof(state), "%s %.3f metres, %s %.3f metres",
        axes.horizontalName,
        static_cast<double>(markers[selectedMarker][axes.horizontal]),
        axes.verticalName,
        static_cast<double>(markers[selectedMarker][axes.vertical]));
    ui::SpeakFocusedItem(
        accessibleName, state,
        "Drag to move on this plane. Double-click resets these two axes; the adjacent buttons and numeric fields provide keyboard and controller input.");

    const auto nudge = [&](const char *visible, unsigned axis, float amount) {
        const std::string label = std::string(visible) + "##" + id;
        if (ImGui::Button(label.c_str())) {
            markers[selectedMarker][axis] = std::clamp(
                markers[selectedMarker][axis] + amount,
                -maximumValue, maximumValue);
            result.changed = result.commit = true;
        }
        char consequence[128];
        std::snprintf(consequence, sizeof(consequence),
                      "Moves the selected marker by %.3f metres on %s.",
                      static_cast<double>(amount),
                      axis == axes.horizontal ? axes.horizontalName
                                              : axes.verticalName);
        ui::SpeakFocusedItem(visible, nullptr, consequence);
    };
    const std::string horizontalMinus =
        std::string(axes.horizontalName) + " -";
    const std::string horizontalPlus =
        std::string(axes.horizontalName) + " +";
    const std::string verticalMinus =
        std::string(axes.verticalName) + " -";
    const std::string verticalPlus =
        std::string(axes.verticalName) + " +";
    nudge(horizontalMinus.c_str(), axes.horizontal, -nudgeStep);
    ImGui::SameLine();
    nudge(horizontalPlus.c_str(), axes.horizontal, nudgeStep);
    nudge(verticalMinus.c_str(), axes.vertical, -nudgeStep);
    ImGui::SameLine();
    nudge(verticalPlus.c_str(), axes.vertical, nudgeStep);
    const std::string resetLabel = std::string("Reset plane##") + id;
    if (ImGui::Button(resetLabel.c_str())) {
        markers[selectedMarker][axes.horizontal] = 0.0f;
        markers[selectedMarker][axes.vertical] = 0.0f;
        result.changed = result.commit = true;
    }
    ui::SpeakFocusedItem(
        "Reset plane", nullptr,
        "Resets only the two visible axes for the selected marker.");
    if (markerNames != nullptr && markerCount > 1u) {
        for (unsigned marker = 0u; marker < markerCount; ++marker) {
            if ((marker & 1u) != 0u) ImGui::SameLine();
            ImGui::TextColored(
                ImGui::ColorConvertU32ToFloat4(
                    markerColors[marker % MDKR_MODERN_CHARACTER_CONTACTS]),
                "%s%s", marker == selectedMarker ? "* " : "",
                markerNames[marker]);
        }
    }
    ImGui::TextDisabled("Visible range: +/- %.2f m", range);
    return result;
}

CharacterSpatialEditResult drawCharacterYawDial(
    const char *id, const char *accessibleName, float &yawDegrees) {
    CharacterSpatialEditResult result;
    const float side = 126.0f;
    const ImVec2 origin = ImGui::GetCursorScreenPos();
    ImGui::InvisibleButton(id, ImVec2(side, side));
    const ImGuiID itemId = ImGui::GetItemID();
    const ImVec2 center(origin.x + side * 0.5f, origin.y + side * 0.5f);
    ImDrawList *draw = ImGui::GetWindowDrawList();
    draw->AddCircleFilled(center, side * 0.46f, IM_COL32(20, 24, 31, 255));
    draw->AddCircle(center, side * 0.46f, IM_COL32(255, 255, 255, 55),
                    0, 1.5f);
    draw->AddText(ImVec2(center.x - 8.0f, origin.y + 4.0f),
                  IM_COL32(180, 190, 205, 255), "+Z");
    const float radians = yawDegrees * 0.01745329251994329577f;
    const ImVec2 tip(center.x + std::sin(radians) * side * 0.35f,
                     center.y - std::cos(radians) * side * 0.35f);
    draw->AddLine(center, tip, IM_COL32(91, 192, 255, 255), 4.0f);
    draw->AddCircleFilled(tip, 6.0f, IM_COL32(255, 255, 255, 255));
    if (ImGui::IsItemActive()) {
        const ImVec2 pointer = ImGui::GetIO().MousePos;
        const float dx = pointer.x - center.x;
        const float dy = pointer.y - center.y;
        if (dx * dx + dy * dy > 16.0f) {
            yawDegrees = std::atan2(dx, -dy) * 57.295779513082320876f;
            yawDegrees = std::clamp(yawDegrees, -180.0f, 180.0f);
            g_characterSpatialGestureDirty[itemId] = true;
            result.changed = true;
        }
    }
    if (ImGui::IsItemHovered() &&
        ImGui::IsMouseDoubleClicked(ImGuiMouseButton_Left)) {
        yawDegrees = 0.0f;
        g_characterSpatialGestureDirty.erase(itemId);
        result.changed = result.commit = true;
    } else if (ImGui::IsItemDeactivated()) {
        const auto dirty = g_characterSpatialGestureDirty.find(itemId);
        if (dirty != g_characterSpatialGestureDirty.end() && dirty->second) {
            g_characterSpatialGestureDirty.erase(dirty);
            result.commit = true;
        }
    }
    char state[64];
    std::snprintf(state, sizeof(state), "yaw %.1f degrees",
                  static_cast<double>(yawDegrees));
    ui::SpeakFocusedItem(
        accessibleName, state,
        "Drag the arrow toward the intended forward direction. Double-click resets yaw; the adjacent buttons and numeric rotation field provide keyboard and controller input.");
    if (ImGui::Button("Turn 180 degrees##yaw")) {
        yawDegrees += yawDegrees > 0.0f ? -180.0f : 180.0f;
        result.changed = result.commit = true;
    }
    ui::SpeakFocusedItem(
        "Turn this context 180 degrees", nullptr,
        "Reverses only this context's facing direction and leaves every other fit unchanged.");
    if (ImGui::Button("Reset yaw##yaw")) {
        yawDegrees = 0.0f;
        result.changed = result.commit = true;
    }
    ui::SpeakFocusedItem(
        "Reset this context yaw", nullptr,
        "Resets only this context's Y-axis rotation.");
    return result;
}

CharacterWorkshopFitMeasurement characterWorkshopFitMeasurement(
    const MdkrCharacterPreviewResult &result, bool vehicleContext) {
    CharacterWorkshopFitMeasurement measurement;
    measurement.valid = characterPreviewFitDiagnosticsValid(result);
    measurement.vehicleContext = vehicleContext;
    for (unsigned axis = 0u; axis < 3u; ++axis) {
        measurement.boundsMinimumMicrometres[axis] =
            result.fit_bounds_min_micrometres[axis];
        measurement.boundsMaximumMicrometres[axis] =
            result.fit_bounds_max_micrometres[axis];
        measurement.forwardMilli[axis] = result.fit_forward_milli[axis];
    }
    return measurement;
}

float characterWorkshopWrappedDegrees(float degrees) {
    while (degrees > 180.0f) degrees -= 360.0f;
    while (degrees <= -180.0f) degrees += 360.0f;
    return degrees;
}

const char *characterWorkshopQualityLabel(
    CharacterWorkshopQualitySeverity severity) {
    switch (severity) {
        case CharacterWorkshopQualitySeverity::Nominal: return "Ready";
        case CharacterWorkshopQualitySeverity::Review: return "Review";
        case CharacterWorkshopQualitySeverity::Critical:
            return "Action needed";
        default: return "Unavailable";
    }
}

ImVec4 characterWorkshopQualityColour(
    CharacterWorkshopQualitySeverity severity) {
    switch (severity) {
        case CharacterWorkshopQualitySeverity::Nominal:
            return AppTheme::good();
        case CharacterWorkshopQualitySeverity::Review:
            return AppTheme::accent();
        case CharacterWorkshopQualitySeverity::Critical:
            return AppTheme::bad();
        default:
            return AppTheme::subtle();
    }
}

unsigned characterPreviewCameraReviewFlags(
    const MdkrCharacterPreviewResult &result) {
    unsigned flags = result.camera_bounds_clip_flags;
    if ((result.fit_landmark_mask &
         (1u << MDKR_CHARACTER_PREVIEW_LANDMARK_HEAD)) != 0u) {
        flags |= result.camera_landmark_clip_flags
            [MDKR_CHARACTER_PREVIEW_LANDMARK_HEAD];
    }
    return flags;
}

void drawCharacterFitQualityBands(
    const CharacterWorkshopFitAssessment &assessment,
    const MdkrCharacterPreviewResult &result) {
    if (!assessment.valid) return;
    ImGui::TextUnformatted("Measured quality bands");
    ImGui::TextColored(
        characterWorkshopQualityColour(assessment.datum),
        "%s datum · %s · %.1f mm from the starting target",
        assessment.vehicleContext ? "Seat" : "Floor",
        characterWorkshopQualityLabel(assessment.datum),
        static_cast<double>(assessment.datumErrorMetres * 1000.0f));
    ImGui::TextColored(
        characterWorkshopQualityColour(assessment.facing),
        "Facing · %s%s",
        characterWorkshopQualityLabel(assessment.facing),
        assessment.facingMeasured ? " · measured from target +Z" :
                                     " · horizontal direction unavailable");
    if (assessment.facingMeasured) {
        ImGui::SameLine();
        ImGui::TextDisabled(
            "(%.1f°)", static_cast<double>(assessment.facingDegrees));
    }
    ImGui::TextColored(
        characterWorkshopQualityColour(assessment.proportions),
        "Volume proportions · %s",
        characterWorkshopQualityLabel(assessment.proportions));
    ImGui::SameLine();
    ImGui::TextDisabled(
        "(width/height %.2f · depth/height %.2f)",
        static_cast<double>(assessment.widthToHeight),
        static_cast<double>(assessment.depthToHeight));
    const bool exactFraming =
        characterPreviewCameraProjectionValid(result) &&
        result.camera_projection_valid;
    const bool framingClipped = exactFraming &&
        characterPreviewCameraReviewFlags(result) != 0u;
    ImGui::TextColored(
        !exactFraming ? AppTheme::accent()
            : framingClipped ? AppTheme::bad() : AppTheme::good(),
        !exactFraming
            ? "Gameplay-camera framing · Exact evidence unavailable"
            : framingClipped
                ? "Gameplay-camera framing · Exact clipping measured"
                : "Gameplay-camera framing · Exact envelope contained");
    const bool exactVehicleSurface = assessment.vehicleContext &&
        characterPreviewVehicleSurfaceValid(result) &&
        result.vehicle_surface_valid;
    ImGui::TextColored(
        exactVehicleSurface
            ? (result.vehicle_surface_crossing_pairs == 0u
                   ? AppTheme::good() : AppTheme::accent())
            : AppTheme::accent(),
        exactVehicleSurface
            ? (result.vehicle_surface_crossing_pairs == 0u
                   ? "Vehicle-body contact / intersection · Exact sample clear"
                   : "Vehicle-body contact / intersection · Exact sample needs review")
            : assessment.vehicleContext
                ? "Vehicle-body contact / intersection · Exact evidence unavailable"
                : "Vehicle-body contact / intersection · Not applicable");
    const bool exactOpaqueVisibility =
        characterPreviewOpaqueVisibilityValid(result) &&
        result.opaque_visibility_valid;
    if (exactOpaqueVisibility && result.opaque_visibility_qualified &&
        result.opaque_visibility_isolated_tiles != 0u) {
        const double visiblePercent = 100.0 * static_cast<double>(
            result.opaque_visibility_scene_tiles) /
            result.opaque_visibility_isolated_tiles;
        ImGui::TextColored(
            visiblePercent < 25.0 ? AppTheme::bad()
                : visiblePercent < 60.0 ? AppTheme::accent()
                                        : AppTheme::good(),
            "Opaque-depth visibility · %.1f%% of occupied regions visible",
            visiblePercent);
    } else if (exactOpaqueVisibility &&
               result.opaque_visibility_qualified) {
        ImGui::TextColored(
            AppTheme::bad(),
            "Opaque-depth visibility · No character regions rendered");
    } else if (exactOpaqueVisibility) {
        ImGui::TextColored(
            AppTheme::accent(),
            "Opaque-depth visibility · Blended materials need visual review");
    } else {
        ImGui::TextColored(
            AppTheme::accent(),
            "Opaque-depth visibility · Exact evidence unavailable");
    }
    ImGui::TextColored(
        assessment.vehicleContext ? AppTheme::accent() : AppTheme::subtle(),
        assessment.vehicleContext
            ? "Attached parts and motion clearance · Representative visual review required"
            : "Motion silhouette clearance · Representative visual review required");
    ui::TextSubtleWrapped(
        "Green means the measured starting range is ordinary, amber asks for judgement, and red identifies a likely placement defect. These advisory bands never reject unusual anatomy. Camera framing, retained-body surface crossings, qualified closed-volume containment, and the final opaque-depth region witness are exact within their stated bounds. The composed scene and representative poses remain authoritative for transparent materials, costume silhouette, unsampled geometry, motion clearance, and deciding whether a wheel, skid, propeller, held object, or piece of scenery caused an observed occlusion.");
}

bool characterPreviewAttachmentVisibilityNeedsReview(
    const MdkrCharacterPreviewResult &sample) {
    if (sample.version < 21u ||
        sample.context == MDKR_CHARACTER_PREVIEW_SELECT) return false;
    /* Retained vehicle-body overlap is expected around a seated racer. The
     * independently drawn parts and held object are the actionable classes. */
    for (unsigned occluder = 1u;
         occluder < MDKR_CHARACTER_PREVIEW_OCCLUDERS; ++occluder) {
        const unsigned bit = 1u << occluder;
        if ((sample.opaque_visibility_occluder_present_mask & bit) == 0u) {
            continue;
        }
        if ((sample.opaque_visibility_occluder_qualified_mask & bit) == 0u ||
            sample.opaque_visibility_occluder_overlap_tiles[occluder] != 0u) {
            return true;
        }
    }
    return false;
}

double characterPreviewPeakJointExcursion(
    const MdkrCharacterPreviewResult &sample, unsigned &peakRole) {
    double peak = -1.0;
    peakRole = 0u;
    if (sample.joint_excursion_mask !=
        MDKR_CHARACTER_RIG_HUMANOID_MASK) return peak;
    for (unsigned role = 0u;
         role < MDKR_CHARACTER_PREVIEW_JOINTS; ++role) {
        const double degrees =
            sample.joint_excursion_millidegrees[role] / 1000.0;
        if (degrees > peak) {
            peak = degrees;
            peakRole = role;
        }
    }
    return peak;
}

void drawCharacterJointExcursionTable(
    const MdkrCharacterPreviewResult *samples, unsigned sampleCount,
    const CharacterMotionReviewDefinition *definitions,
    const char *tableId) {
    if (samples == nullptr || sampleCount == 0u || definitions == nullptr ||
        tableId == nullptr) return;
    double overallPeak = -1.0;
    unsigned overallRole = 0u;
    unsigned overallSample = 0u;
    for (unsigned sample = 0u; sample < sampleCount; ++sample) {
        unsigned role = 0u;
        const double peak = characterPreviewPeakJointExcursion(
            samples[sample], role);
        if (peak > overallPeak) {
            overallPeak = peak;
            overallRole = role;
            overallSample = sample;
        }
    }
    if (overallPeak < 0.0) {
        ImGui::TextDisabled(
            "Exact joint travel unavailable · use visual anatomy review");
        return;
    }
    std::array<unsigned, MDKR_CHARACTER_PREVIEW_JOINTS> peakSamples{};
    std::array<unsigned, MDKR_CHARACTER_PREVIEW_JOINTS> peakValues{};
    std::string spokenDetails =
        "Shortest bind-relative node-local travel after reference motion and contact solving. ";
    for (unsigned role = 0u;
         role < MDKR_CHARACTER_PREVIEW_JOINTS; ++role) {
        for (unsigned sample = 0u; sample < sampleCount; ++sample) {
            if (samples[sample].joint_excursion_millidegrees[role] >
                peakValues[role]) {
                peakValues[role] =
                    samples[sample].joint_excursion_millidegrees[role];
                peakSamples[role] = sample;
            }
        }
        char spokenValue[128];
        std::snprintf(
            spokenValue, sizeof(spokenValue), "%s %.1f degrees in %s. ",
            kHumanoidRigRoles[role].label,
            peakValues[role] / 1000.0,
            definitions[peakSamples[role]].label);
        spokenDetails += spokenValue;
    }
    spokenDetails +=
        "These values support authored visual review; they are not automatic anatomical limits or runtime clamps.";
    char visibleLabel[160];
    char nodeLabel[192];
    std::snprintf(
        visibleLabel, sizeof(visibleLabel),
        "Joint travel · %.1f° max at %s (%s)",
        overallPeak, kHumanoidRigRoles[overallRole].label,
        definitions[overallSample].label);
    std::snprintf(nodeLabel, sizeof(nodeLabel), "%s##%s",
                  visibleLabel, tableId);
    ImGui::PushID(samples);
    const bool open = ImGui::TreeNodeEx(
        nodeLabel, ImGuiTreeNodeFlags_DefaultOpen);
    ui::SpeakFocusedItem(
        "Exact joint travel details", visibleLabel,
        spokenDetails.c_str());
    if (std::getenv("MDKR_APP_UI_TRACE") != nullptr) {
        static std::set<std::string> tracedTables;
        if (tracedTables.insert(tableId).second) {
            std::fprintf(
                stderr,
                "[app-ui] character-joint-travel samples=%u roles=%u max-millidegrees=%u accessible=focusable-summary-plus-numeric-table\n",
                sampleCount, MDKR_CHARACTER_PREVIEW_JOINTS,
                static_cast<unsigned>(overallPeak * 1000.0 + 0.5));
        }
    }
    if (!open) {
        ImGui::PopID();
        return;
    }
    ui::TextSubtleWrapped(
        "Each value is the shortest node-local quaternion angle from the compiled bind rotation after reference motion and vehicle contact solving. Compare start, middle, end, and transitions visually: a large value can be correct for stylized anatomy, while a small value can still deform badly. No generic threshold approves or rejects a character.");
    if (ImGui::BeginTable(
            tableId, 3,
            ImGuiTableFlags_BordersInnerH | ImGuiTableFlags_RowBg |
                ImGuiTableFlags_SizingStretchProp)) {
        // Explicit weights avoid deriving 0/0 from unmeasured first-frame
        // contents when this table appears below the visible region.
        ImGui::TableSetupColumn("Joint role", ImGuiTableColumnFlags_WidthStretch, 1.3f);
        ImGui::TableSetupColumn("Largest travel", ImGuiTableColumnFlags_WidthStretch, 1.0f);
        ImGui::TableSetupColumn("State", ImGuiTableColumnFlags_WidthStretch, 1.2f);
        ImGui::TableHeadersRow();
        for (unsigned role = 0u;
             role < MDKR_CHARACTER_PREVIEW_JOINTS; ++role) {
            ImGui::TableNextRow();
            ImGui::TableSetColumnIndex(0);
            ImGui::TextUnformatted(kHumanoidRigRoles[role].label);
            ImGui::TableSetColumnIndex(1);
            ImGui::Text("%.1f°", peakValues[role] / 1000.0);
            ImGui::TableSetColumnIndex(2);
            ImGui::TextUnformatted(definitions[peakSamples[role]].label);
        }
        ImGui::EndTable();
    }
    ImGui::TreePop();
    ImGui::PopID();
}

void drawCharacterMotionRuntimeDiagnostics(
    const MdkrCharacterPreviewResult *samples, unsigned sampleCount) {
    if (samples == nullptr || sampleCount == 0u) return;
    unsigned clampMask = 0u;
    unsigned chainCount = 0u;
    unsigned jointCount = 0u;
    unsigned activeJoints = 0u;
    unsigned maxDeflection = 0u;
    unsigned long long resets = 0u;
    for (unsigned sample = 0u; sample < sampleCount; ++sample) {
        if (samples[sample].version < 23u) return;
        clampMask |= samples[sample].constraint_clamped_mask;
        chainCount = std::max(chainCount,
                              samples[sample].secondary_chain_count);
        jointCount = std::max(jointCount,
                              samples[sample].secondary_joint_count);
        activeJoints = std::max(
            activeJoints, samples[sample].secondary_active_joint_count);
        maxDeflection = std::max(
            maxDeflection,
            samples[sample].secondary_max_deflection_millidegrees);
        resets = std::max(
            resets, samples[sample].secondary_discontinuity_resets);
    }
    if (clampMask == 0u && chainCount == 0u) return;
    ImGui::SeparatorText("Authored motion safeguards");
    if (clampMask != 0u) {
        std::string roles;
        for (unsigned role = 0u;
             role < MDKR_CHARACTER_PREVIEW_JOINTS; ++role) {
            if ((clampMask & (1u << role)) == 0u) continue;
            if (!roles.empty()) roles += ", ";
            roles += kHumanoidRigRoles[role].label;
        }
        ImGui::TextColored(
            AppTheme::accent(), "Joint limits engaged: %s", roles.c_str());
        ui::TextSubtleWrapped(
            "An engaged limit is evidence that this exact pose reached its authored safety rail. Inspect the silhouette and contact error; it is not automatically a defect or an approval.");
    } else {
        ImGui::TextDisabled(
            "Joint limits: none engaged in the sampled state%s",
            sampleCount == 1u ? "" : "s");
    }
    if (chainCount != 0u) {
        ImGui::Text(
            "Follow-through: %u chain%s · %u dynamic joint%s · %u active · %.2f° peak",
            chainCount, chainCount == 1u ? "" : "s", jointCount,
            jointCount == 1u ? "" : "s", activeJoints,
            maxDeflection / 1000.0);
        ImGui::TextDisabled(
            "%llu presentation discontinuity reset%s observed",
            resets, resets == 1u ? "" : "s");
        ui::TextSubtleWrapped(
            "The fixed-step spring reports its largest current deflection and safe hitch resets. Review starts, stops, turns, and landings visually; these numbers prove bounded runtime behavior, not artistic quality.");
    }
    if (std::getenv("MDKR_APP_UI_TRACE") != nullptr) {
        static bool traced = false;
        if (!traced) {
            std::fprintf(
                stderr,
                "[app-ui] character-motion-runtime-diagnostics clamp-mask=%u chains=%u joints=%u active=%u max-millidegrees=%u discontinuity-resets=%llu exact=1 spoken=1\n",
                clampMask, chainCount, jointCount, activeJoints,
                maxDeflection, resets);
            traced = true;
        }
    }
}

void drawCharacterMotionReviewSummary(
    const CharacterMotionReviewSessionResult &session, bool compact) {
    constexpr unsigned long long kContactStabilityGuideMicrometres = 2000u;
    unsigned sampleCount = 0u;
    const CharacterMotionReviewDefinition *definitions =
        characterMotionReviewDefinitions(
            session.result.context, sampleCount);
    if (definitions == nullptr || sampleCount == 0u ||
        session.result.sample_count != sampleCount) return;
    const bool vehicle =
        session.result.context != MDKR_CHARACTER_PREVIEW_SELECT;
    unsigned worstCamera = 0u;
    unsigned worstSurface = 0u;
    unsigned worstVisibility = 0u;
    unsigned worstContact = 0u;
    unsigned worstCameraBits = 0u;
    unsigned worstCrossings = 0u;
    unsigned worstInside = 0u;
    unsigned long long worstContainment = 0u;
    unsigned long long worstContactError = 0u;
    unsigned long long worstContactStep = 0u;
    double worstVisibilityRatio = 2.0;
    bool haveQualifiedVisibility = false;
    bool haveUnqualifiedVisibility = false;
    bool haveUnqualifiedVolume = false;
    bool haveContactWitness = false;
    bool haveContactStability = false;
    unsigned worstContactStepSample = 0u;
    bool haveNamedAttachments = false;
    unsigned unqualifiedVisibility = 0u;
    unsigned unqualifiedVolume = 0u;
    unsigned attachmentReviewStates = 0u;
    unsigned firstAttachmentReview = 0u;
    double worstJointExcursion = -1.0;
    unsigned worstJointRole = 0u;
    unsigned worstJointSample = 0u;
    for (unsigned index = 0u; index < sampleCount; ++index) {
        const MdkrCharacterPreviewResult &sample =
            session.result.samples[index];
        unsigned samplePeakRole = 0u;
        const double samplePeakJoint = characterPreviewPeakJointExcursion(
            sample, samplePeakRole);
        if (samplePeakJoint > worstJointExcursion) {
            worstJointExcursion = samplePeakJoint;
            worstJointRole = samplePeakRole;
            worstJointSample = index;
        }
        unsigned cameraBits = 0u;
        for (unsigned flags = characterPreviewCameraReviewFlags(sample);
             flags != 0u; flags >>= 1u) {
            cameraBits += flags & 1u;
        }
        if (cameraBits > worstCameraBits) {
            worstCameraBits = cameraBits;
            worstCamera = index;
        }
        if (vehicle &&
            (sample.vehicle_surface_crossing_pairs > worstCrossings ||
            (sample.vehicle_surface_crossing_pairs == worstCrossings &&
             sample.vehicle_containment_inside_samples > worstInside) ||
            (sample.vehicle_surface_crossing_pairs == worstCrossings &&
             sample.vehicle_containment_inside_samples == worstInside &&
             sample.vehicle_containment_maximum_depth_micrometres >
                 worstContainment))) {
            worstCrossings = sample.vehicle_surface_crossing_pairs;
            worstInside = sample.vehicle_containment_inside_samples;
            worstContainment =
                sample.vehicle_containment_maximum_depth_micrometres;
            worstSurface = index;
        }
        if (vehicle && !sample.vehicle_volume_qualified &&
            !haveUnqualifiedVolume) {
            haveUnqualifiedVolume = true;
            unqualifiedVolume = index;
        }
        if (vehicle &&
            (sample.opaque_visibility_occluder_present_mask & 0x6u) != 0u) {
            haveNamedAttachments = true;
        }
        if (vehicle &&
            characterPreviewAttachmentVisibilityNeedsReview(sample)) {
            if (attachmentReviewStates == 0u) {
                firstAttachmentReview = index;
            }
            ++attachmentReviewStates;
        }
        if (!sample.opaque_visibility_qualified) {
            if (!haveUnqualifiedVisibility) unqualifiedVisibility = index;
            haveUnqualifiedVisibility = true;
        } else {
            const double visibilityRatio =
                sample.opaque_visibility_isolated_tiles != 0u
                    ? static_cast<double>(
                          sample.opaque_visibility_scene_tiles) /
                          sample.opaque_visibility_isolated_tiles
                    : 0.0;
            haveQualifiedVisibility = true;
            if (visibilityRatio < worstVisibilityRatio) {
                worstVisibilityRatio = visibilityRatio;
                worstVisibility = index;
            }
        }
        haveContactWitness |= vehicle && sample.contact_witness_mask != 0u;
        if (vehicle &&
            sample.contact_error_max_micrometres > worstContactError) {
            worstContactError = sample.contact_error_max_micrometres;
            worstContact = index;
        }
        for (unsigned contact = 0u;
             vehicle && contact < MDKR_CHARACTER_PREVIEW_CONTACTS;
             ++contact) {
            if ((session.result.contact_stability_mask[index] &
                 (1u << contact)) == 0u) continue;
            haveContactStability = true;
            const unsigned long long step =
                session.result.contact_stability_max_step_micrometres
                    [index][contact];
            if (step > worstContactStep) {
                worstContactStep = step;
                worstContactStepSample = index;
            }
        }
    }
    const bool reviewClean =
        worstCameraBits == 0u && worstCrossings == 0u && worstInside == 0u &&
        !haveUnqualifiedVolume && !haveUnqualifiedVisibility &&
        haveQualifiedVisibility && worstVisibilityRatio >= 0.6 &&
        attachmentReviewStates == 0u &&
        (!haveContactStability ||
         worstContactStep <= kContactStabilityGuideMicrometres);
    ImGui::TextColored(
        reviewClean ? AppTheme::good() : AppTheme::accent(),
        "%s · %u of %u exact states measured",
        vehicle ? "Complete race motion" : "Complete select motion",
        sampleCount, sampleCount);
    const bool collapsibleDetails = sampleCount > 5u;
    const bool showDetails = !collapsibleDetails || ImGui::TreeNodeEx(
        "All state measurements",
        reviewClean ? ImGuiTreeNodeFlags_None
                    : ImGuiTreeNodeFlags_DefaultOpen);
    if (showDetails && ImGui::BeginTable(
            "##motion-review-states",
            compact ? 3 : vehicle ? 7 : 4,
            ImGuiTableFlags_BordersInnerH | ImGuiTableFlags_RowBg |
                ImGuiTableFlags_SizingStretchProp)) {
        ImGui::TableSetupColumn("State", ImGuiTableColumnFlags_WidthStretch, 1.5f);
        ImGui::TableSetupColumn("Framing", ImGuiTableColumnFlags_WidthStretch, 1.0f);
        ImGui::TableSetupColumn("Visible", ImGuiTableColumnFlags_WidthStretch, 1.0f);
        if (!compact) ImGui::TableSetupColumn("Peak joint", ImGuiTableColumnFlags_WidthStretch, 1.0f);
        if (!compact && vehicle) {
            ImGui::TableSetupColumn("Vehicle body", ImGuiTableColumnFlags_WidthStretch, 1.0f);
            ImGui::TableSetupColumn("Parts / item", ImGuiTableColumnFlags_WidthStretch, 1.0f);
            ImGui::TableSetupColumn("Contacts", ImGuiTableColumnFlags_WidthStretch, 1.0f);
        }
        ImGui::TableHeadersRow();
        for (unsigned index = 0u; index < sampleCount; ++index) {
            const MdkrCharacterPreviewResult &sample =
                session.result.samples[index];
            ImGui::TableNextRow();
            ImGui::TableSetColumnIndex(0);
            ImGui::TextUnformatted(definitions[index].label);
            ImGui::TableSetColumnIndex(1);
            if (characterPreviewCameraReviewFlags(sample) == 0u) {
                ImGui::TextColored(AppTheme::good(), "Inside frame");
            } else {
                ImGui::TextColored(AppTheme::bad(), "Clipped");
            }
            ImGui::TableSetColumnIndex(2);
            if (!sample.opaque_visibility_qualified) {
                ImGui::TextColored(AppTheme::accent(), "Visual check");
            } else if (sample.opaque_visibility_isolated_tiles == 0u) {
                ImGui::TextColored(AppTheme::bad(), "Not visible");
            } else {
                ImGui::Text(
                    "%.0f%%",
                    100.0 * sample.opaque_visibility_scene_tiles /
                        sample.opaque_visibility_isolated_tiles);
            }
            unsigned nextColumn = 3u;
            if (!compact) {
                ImGui::TableSetColumnIndex(nextColumn++);
                unsigned peakRole = 0u;
                const double peak = characterPreviewPeakJointExcursion(
                    sample, peakRole);
                if (peak < 0.0) {
                    ImGui::TextDisabled("Unavailable");
                } else {
                    ImGui::Text("%.1f° · %s", peak,
                                kHumanoidRigRoles[peakRole].label);
                }
            }
            if (!compact && vehicle) {
                ImGui::TableSetColumnIndex(nextColumn++);
                if (sample.vehicle_surface_crossing_pairs == 0u &&
                    sample.vehicle_containment_inside_samples == 0u &&
                    sample.vehicle_volume_qualified) {
                    ImGui::TextColored(AppTheme::good(), "Clear");
                } else if (sample.vehicle_surface_crossing_pairs == 0u &&
                           !sample.vehicle_volume_qualified) {
                    ImGui::TextColored(
                        AppTheme::accent(), "No crossings · volume check");
                } else {
                    ImGui::TextColored(
                        AppTheme::accent(), "%u crossing%s · %u inside",
                        sample.vehicle_surface_crossing_pairs,
                        sample.vehicle_surface_crossing_pairs == 1u ? "" : "s",
                        sample.vehicle_containment_inside_samples);
                }
                ImGui::TableSetColumnIndex(nextColumn++);
                bool attachmentPresent = false;
                bool attachmentUnqualified = false;
                unsigned attachmentOverlap = 0u;
                for (unsigned occluder = 1u;
                     occluder < MDKR_CHARACTER_PREVIEW_OCCLUDERS;
                     ++occluder) {
                    const unsigned bit = 1u << occluder;
                    if ((sample.opaque_visibility_occluder_present_mask &
                         bit) == 0u) continue;
                    attachmentPresent = true;
                    attachmentUnqualified |=
                        (sample.opaque_visibility_occluder_qualified_mask &
                         bit) == 0u;
                    attachmentOverlap +=
                        sample.opaque_visibility_occluder_overlap_tiles
                            [occluder];
                }
                if (!attachmentPresent) {
                    ImGui::TextDisabled("Not drawn");
                } else if (attachmentUnqualified) {
                    ImGui::TextColored(AppTheme::accent(), "Visual check");
                } else if (attachmentOverlap != 0u) {
                    ImGui::TextColored(
                        AppTheme::accent(), "In front · %u region%s",
                        attachmentOverlap,
                        attachmentOverlap == 1u ? "" : "s");
                } else {
                    ImGui::TextColored(AppTheme::good(), "No overlap");
                }
                ImGui::TableSetColumnIndex(nextColumn);
                if (sample.contact_witness_mask == 0u) {
                    ImGui::TextDisabled("Not solved");
                } else {
                    ImGui::Text("%.1f mm max",
                                sample.contact_error_max_micrometres / 1000.0);
                    unsigned long long maximumStep = 0u;
                    for (unsigned contact = 0u;
                         contact < MDKR_CHARACTER_PREVIEW_CONTACTS;
                         ++contact) {
                        maximumStep = std::max(
                            maximumStep,
                            session.result
                                .contact_stability_max_step_micrometres
                                    [index][contact]);
                    }
                    ImGui::TextDisabled(
                        "%.2f mm drift", maximumStep / 1000.0);
                }
            }
        }
        ImGui::EndTable();
    }
    if (showDetails && collapsibleDetails) ImGui::TreePop();
    drawCharacterJointExcursionTable(
        session.result.samples, sampleCount, definitions,
        "motion-review-joint-travel");
    drawCharacterMotionRuntimeDiagnostics(
        session.result.samples, sampleCount);
    char framingSummary[96];
    char bodySummary[128];
    char visibilitySummary[128];
    char attachmentSummary[128];
    char contactSummary[192];
    char jointSummary[160];
    if (worstCameraBits == 0u) {
        std::snprintf(framingSummary, sizeof(framingSummary),
                      "framing clear in all states");
    } else {
        std::snprintf(framingSummary, sizeof(framingSummary),
                      "framing %s", definitions[worstCamera].label);
    }
    if (!vehicle) {
        std::snprintf(bodySummary, sizeof(bodySummary),
                      "vehicle body not applicable");
    } else if (worstCrossings != 0u || worstInside != 0u) {
        std::snprintf(bodySummary, sizeof(bodySummary),
                      "body %s", definitions[worstSurface].label);
    } else if (haveUnqualifiedVolume) {
        std::snprintf(bodySummary, sizeof(bodySummary),
                      "body has no crossings; volume check %s",
                      definitions[unqualifiedVolume].label);
    } else {
        std::snprintf(bodySummary, sizeof(bodySummary),
                      "body clear in all states");
    }
    if (haveQualifiedVisibility && worstVisibilityRatio < 0.6) {
        std::snprintf(visibilitySummary, sizeof(visibilitySummary),
                      "visibility %.0f%% (%s)",
                      worstVisibilityRatio * 100.0,
                      definitions[worstVisibility].label);
    } else if (haveUnqualifiedVisibility) {
        std::snprintf(visibilitySummary, sizeof(visibilitySummary),
                      "visibility visual check %s",
                      definitions[unqualifiedVisibility].label);
    } else if (haveQualifiedVisibility) {
        std::snprintf(visibilitySummary, sizeof(visibilitySummary),
                      "visibility %.0f%% minimum (%s)",
                      worstVisibilityRatio * 100.0,
                      definitions[worstVisibility].label);
    } else {
        std::snprintf(visibilitySummary, sizeof(visibilitySummary),
                      "visibility unavailable");
    }
    if (!vehicle) {
        std::snprintf(attachmentSummary, sizeof(attachmentSummary),
                      "parts/item not applicable");
    } else if (attachmentReviewStates != 0u) {
        std::snprintf(
            attachmentSummary, sizeof(attachmentSummary),
            "parts/item review in %u state%s (first: %s)",
            attachmentReviewStates,
            attachmentReviewStates == 1u ? "" : "s",
            definitions[firstAttachmentReview].label);
    } else if (haveNamedAttachments) {
        std::snprintf(attachmentSummary, sizeof(attachmentSummary),
                      "drawn parts/item have no in-front warning");
    } else {
        std::snprintf(attachmentSummary, sizeof(attachmentSummary),
                      "parts/item not drawn");
    }
    if (!vehicle) {
        std::snprintf(contactSummary, sizeof(contactSummary),
                      "contacts not applicable");
    } else if (haveContactWitness) {
        if (haveContactStability) {
            std::snprintf(
                contactSummary, sizeof(contactSummary),
                "contacts %.1f mm (%s), residual drift %.2f mm (%s)",
                worstContactError / 1000.0,
                definitions[worstContact].label,
                worstContactStep / 1000.0,
                definitions[worstContactStepSample].label);
        } else {
            std::snprintf(contactSummary, sizeof(contactSummary),
                          "contacts %.1f mm (%s), stability unavailable",
                          worstContactError / 1000.0,
                          definitions[worstContact].label);
        }
    } else {
        std::snprintf(contactSummary, sizeof(contactSummary),
                      "contacts not procedurally solved");
    }
    if (worstJointExcursion < 0.0) {
        std::snprintf(jointSummary, sizeof(jointSummary),
                      "joint travel unavailable");
    } else {
        std::snprintf(
            jointSummary, sizeof(jointSummary),
            "joint travel %.1f° %s (%s)", worstJointExcursion,
            kHumanoidRigRoles[worstJointRole].label,
            definitions[worstJointSample].label);
    }
    ImGui::TextDisabled(
        "Review summary: %s · %s · %s · %s · %s · %s", framingSummary,
        bodySummary, visibilitySummary, attachmentSummary, contactSummary,
        jointSummary);
    ui::TextSubtleWrapped(
        vehicle
            ? "Every race semantic is a fresh renderer witness after the authored pose settled and remained visible for at least 60 complete character draws. Contact residual drift is the largest consecutive change in endpoint-minus-target during that held window, not ordinary model movement; 2 mm or less is the starting guide. Run it again whenever you need another look. Warnings remain reviewable for unusual anatomy, transparent materials, and intentional costume overlap; an opaque state with no visible regions still blocks approval."
            : "Idle, hover, and confirm are fresh renderer witnesses after each authored pose settled and remained visible for at least 60 complete character draws. This catches a select-only bind pose, clipping, or disappearance before approval; an opaque state with no visible regions still blocks approval.");
}

/* Rendered app-lifecycle tests use this only behind their paired smoke token.
 * Build the same strict value contract the engine returns so the UI tests do
 * not regain the old one-favourable-frame approval shortcut. */
void clearCharacterPreviewOccluderEvidence(
    MdkrCharacterPreviewResult &result) {
    result.opaque_visibility_occluder_present_mask = 0u;
    result.opaque_visibility_occluder_qualified_mask = 0u;
    std::memset(result.opaque_visibility_occluder_draws, 0,
                sizeof(result.opaque_visibility_occluder_draws));
    std::memset(result.opaque_visibility_occluder_unqualified_draws, 0,
                sizeof(result.opaque_visibility_occluder_unqualified_draws));
    std::memset(result.opaque_visibility_occluder_overlap_tiles, 0,
                sizeof(result.opaque_visibility_occluder_overlap_tiles));
    std::memset(result.opaque_visibility_occluder_overlap_tile_mask, 0,
                sizeof(result.opaque_visibility_occluder_overlap_tile_mask));
}

void publishCharacterMotionReviewSmokeFixture(
    const MdkrModernCharacterEntry *entry,
    const CharacterTuningEdit &edit,
    MdkrCharacterPreviewContext context,
    const MdkrCharacterPreviewResult &base,
    MdkrCharacterPreviewScene scene =
        MDKR_CHARACTER_PREVIEW_SCENE_BASELINE) {
    unsigned sampleCount = 0u;
    const CharacterMotionReviewDefinition *definitions =
        characterMotionReviewDefinitions(context, sampleCount);
    if (definitions == nullptr || sampleCount == 0u) return;
    MdkrCharacterPreviewResult publicationBase = base;
    publicationBase.context = context;
    if (context == MDKR_CHARACTER_PREVIEW_SELECT) {
        clearCharacterPreviewOccluderEvidence(publicationBase);
    }
    MdkrCharacterMotionReviewResult review{};
    review.version = MDKR_CHARACTER_MOTION_REVIEW_RESULT_VERSION;
    review.started = review.completed = 1;
    review.context = context;
    review.scene = scene;
    review.sample_count = sampleCount;
    review.completed_mask =
        MDKR_CHARACTER_MOTION_REVIEW_SAMPLE_MASK(sampleCount);
    for (unsigned index = 0u; index < sampleCount; ++index) {
        MdkrCharacterPreviewResult &sample = review.samples[index];
        sample = publicationBase;
        sample.context = context;
        sample.players = 1;
        sample.pose = definitions[index].pose;
        sample.pose_phase_milli = definitions[index].phaseMilli;
        sample.transition_from_pose = MDKR_CHARACTER_PREVIEW_POSE_LIVE;
        sample.transition_from_phase_milli = 0u;
        sample.transition_from_motion_source =
            MDKR_CHARACTER_PREVIEW_MOTION_AUTHORED;
        sample.transition_to_motion_source =
            MDKR_CHARACTER_PREVIEW_MOTION_NONE;
        sample.inspection_pose_ticks = 60u;
        sample.inspection_pose_fallback_ticks = 0u;
        if (characterJointDiagnosticsExpected(entry)) {
            sample.joint_excursion_mask =
                MDKR_CHARACTER_RIG_HUMANOID_MASK;
            for (unsigned role = 0u;
                 role < MDKR_CHARACTER_PREVIEW_JOINTS; ++role) {
                sample.joint_excursion_millidegrees[role] =
                    5000u + role * 3500u + index * 750u;
            }
        }
        sample.view_yaw_degrees = sample.view_pitch_degrees = 0;
        sample.lighting = MDKR_WORKSHOP_PREVIEW_LIGHTING_NEUTRAL;
        sample.camera_override_ticks = 0u;
        sample.lighting_override_draws = 0u;
        sample.capture_requested = sample.capture_armed = 0;
        sample.capture_written = 0;
        sample.capture_stable_frames = 0u;
        sample.capture_png_bytes = 0u;
        sample.capture_kind = MDKR_CHARACTER_PREVIEW_CAPTURE_SCENE;
        if (context != MDKR_CHARACTER_PREVIEW_SELECT &&
            sample.contact_solves != 0u) {
            review.contact_stability_mask[index] =
                (1u << MDKR_CHARACTER_PREVIEW_CONTACTS) - 1u;
            for (unsigned contact = 0u;
                 contact < MDKR_CHARACTER_PREVIEW_CONTACTS; ++contact) {
                review.contact_stability_observations[index][contact] = 59u;
                review.contact_stability_max_step_micrometres[index][contact] =
                    250u * (contact + 1u);
            }
        }
        if (context == MDKR_CHARACTER_PREVIEW_SELECT) {
            sample.contact_solves = 0u;
            sample.contact_error_mean_micrometres = 0u;
            sample.contact_error_max_micrometres = 0u;
            sample.contact_witness_mask = 0u;
            std::memset(sample.contact_chain_root_micrometres, 0,
                        sizeof(sample.contact_chain_root_micrometres));
            std::memset(sample.contact_bend_micrometres, 0,
                        sizeof(sample.contact_bend_micrometres));
            std::memset(sample.contact_target_micrometres, 0,
                        sizeof(sample.contact_target_micrometres));
            std::memset(sample.contact_end_micrometres, 0,
                        sizeof(sample.contact_end_micrometres));
            std::memset(sample.contact_witness_error_micrometres, 0,
                        sizeof(sample.contact_witness_error_micrometres));
            sample.vehicle_surface_valid = 0;
            sample.vehicle_shell_triangles_submitted = 0u;
            sample.vehicle_shell_triangles_tested = 0u;
            sample.character_surface_triangles_submitted = 0u;
            sample.character_surface_triangles_tested = 0u;
            sample.vehicle_surface_crossing_triangles = 0u;
            sample.vehicle_surface_crossing_pairs = 0u;
            std::memset(sample.vehicle_surface_first_crossing_micrometres, 0,
                        sizeof(sample.vehicle_surface_first_crossing_micrometres));
            sample.vehicle_volume_qualified = 0;
            sample.vehicle_shell_boundary_edges = 0u;
            sample.vehicle_shell_nonmanifold_edges = 0u;
            sample.vehicle_shell_orientation_mismatch_edges = 0u;
            sample.vehicle_shell_self_intersection_pairs = 0u;
            sample.vehicle_containment_samples_tested = 0u;
            sample.vehicle_containment_inside_samples = 0u;
            sample.vehicle_containment_boundary_samples = 0u;
            sample.vehicle_containment_outside_samples = 0u;
            sample.vehicle_containment_maximum_depth_micrometres = 0u;
            std::memset(sample.vehicle_containment_deepest_micrometres, 0,
                        sizeof(sample.vehicle_containment_deepest_micrometres));
        }
    }
    SettingsCharacterPreviewDisposition disposition;
    disposition.representativeMotionReview = true;
    disposition.scene = scene;
    MdkrCharacterMotionReviewResult stopped = review;
    stopped.completed = 0;
    stopped.completed_mask = 0u;
    Settings_publishCharacterPreviewResult(
        entry->id, characterDigestHex(entry->source_sha256),
        characterTestTuningSignature(
            entry, edit, static_cast<unsigned>(context - 1)),
        characterTestPresentationSignature(), std::string(), disposition,
        publicationBase, &stopped);
    if (currentCharacterMotionReview(entry, edit, context, scene) != nullptr) {
        return;
    }
    MdkrCharacterMotionReviewResult malformed = review;
    malformed.samples[sampleCount - 1u].pose =
        definitions[0].pose;
    Settings_publishCharacterPreviewResult(
        entry->id, characterDigestHex(entry->source_sha256),
        characterTestTuningSignature(
            entry, edit, static_cast<unsigned>(context - 1)),
        characterTestPresentationSignature(), std::string(), disposition,
        publicationBase, &malformed);
    if (currentCharacterMotionReview(entry, edit, context, scene) != nullptr) return;
    malformed = review;
    malformed.sample_count--;
    Settings_publishCharacterPreviewResult(
        entry->id, characterDigestHex(entry->source_sha256),
        characterTestTuningSignature(
            entry, edit, static_cast<unsigned>(context - 1)),
        characterTestPresentationSignature(), std::string(), disposition,
        publicationBase, &malformed);
    if (currentCharacterMotionReview(entry, edit, context, scene) != nullptr) return;
    malformed = review;
    malformed.samples[sampleCount - 1u].replacement_draws = 59u;
    Settings_publishCharacterPreviewResult(
        entry->id, characterDigestHex(entry->source_sha256),
        characterTestTuningSignature(
            entry, edit, static_cast<unsigned>(context - 1)),
        characterTestPresentationSignature(), std::string(), disposition,
        publicationBase, &malformed);
    if (currentCharacterMotionReview(entry, edit, context, scene) != nullptr) return;
    malformed = review;
    malformed.samples[0].joint_excursion_mask = 1u;
    malformed.samples[0].joint_excursion_millidegrees[0] = 5000u;
    Settings_publishCharacterPreviewResult(
        entry->id, characterDigestHex(entry->source_sha256),
        characterTestTuningSignature(
            entry, edit, static_cast<unsigned>(context - 1)),
        characterTestPresentationSignature(), std::string(), disposition,
        publicationBase, &malformed);
    if (currentCharacterMotionReview(entry, edit, context, scene) != nullptr) return;
    malformed = review;
    malformed.samples[0].joint_excursion_mask = 0u;
    malformed.samples[0].joint_excursion_millidegrees[0] = 1u;
    Settings_publishCharacterPreviewResult(
        entry->id, characterDigestHex(entry->source_sha256),
        characterTestTuningSignature(
            entry, edit, static_cast<unsigned>(context - 1)),
        characterTestPresentationSignature(), std::string(), disposition,
        publicationBase, &malformed);
    if (currentCharacterMotionReview(entry, edit, context, scene) != nullptr) return;
    malformed = review;
    malformed.samples[0].constraint_clamped_mask = 1u;
    malformed.samples[0].joint_excursion_mask = 0u;
    Settings_publishCharacterPreviewResult(
        entry->id, characterDigestHex(entry->source_sha256),
        characterTestTuningSignature(
            entry, edit, static_cast<unsigned>(context - 1)),
        characterTestPresentationSignature(), std::string(), disposition,
        publicationBase, &malformed);
    if (currentCharacterMotionReview(entry, edit, context, scene) != nullptr) return;
    malformed = review;
    malformed.samples[0].secondary_chain_count = 1u;
    malformed.samples[0].secondary_joint_count = 0u;
    Settings_publishCharacterPreviewResult(
        entry->id, characterDigestHex(entry->source_sha256),
        characterTestTuningSignature(
            entry, edit, static_cast<unsigned>(context - 1)),
        characterTestPresentationSignature(), std::string(), disposition,
        publicationBase, &malformed);
    if (currentCharacterMotionReview(entry, edit, context, scene) != nullptr) return;
    if (characterJointDiagnosticsExpected(entry)) {
        malformed = review;
        malformed.samples[0].joint_excursion_millidegrees[0] = 180001u;
        Settings_publishCharacterPreviewResult(
            entry->id, characterDigestHex(entry->source_sha256),
            characterTestTuningSignature(
                entry, edit, static_cast<unsigned>(context - 1)),
            characterTestPresentationSignature(), std::string(), disposition,
            publicationBase, &malformed);
        if (currentCharacterMotionReview(entry, edit, context, scene) != nullptr) {
            return;
        }
    }
    if (sampleCount < MDKR_CHARACTER_MOTION_REVIEW_SAMPLE_COUNT) {
        malformed = review;
        malformed.samples[sampleCount].version =
            MDKR_CHARACTER_PREVIEW_RESULT_VERSION;
        Settings_publishCharacterPreviewResult(
            entry->id, characterDigestHex(entry->source_sha256),
            characterTestTuningSignature(
                entry, edit, static_cast<unsigned>(context - 1)),
            characterTestPresentationSignature(), std::string(), disposition,
            publicationBase, &malformed);
        if (currentCharacterMotionReview(entry, edit, context, scene) != nullptr) {
            return;
        }
        malformed = review;
        malformed.samples[sampleCount]
            .joint_excursion_millidegrees[0] = 1u;
        Settings_publishCharacterPreviewResult(
            entry->id, characterDigestHex(entry->source_sha256),
            characterTestTuningSignature(
                entry, edit, static_cast<unsigned>(context - 1)),
            characterTestPresentationSignature(), std::string(), disposition,
            publicationBase, &malformed);
        if (currentCharacterMotionReview(entry, edit, context, scene) != nullptr) {
            return;
        }
    }
    if (context == MDKR_CHARACTER_PREVIEW_SELECT) {
        malformed = review;
        malformed.samples[0].contact_solves = 1u;
        Settings_publishCharacterPreviewResult(
            entry->id, characterDigestHex(entry->source_sha256),
            characterTestTuningSignature(
                entry, edit, static_cast<unsigned>(context - 1)),
            characterTestPresentationSignature(), std::string(), disposition,
            publicationBase, &malformed);
        if (currentCharacterMotionReview(entry, edit, context, scene) != nullptr) {
            return;
        }
    } else {
        malformed = review;
        malformed.contact_stability_observations[0][0] =
            MDKR_CHARACTER_CONTACT_STABILITY_MINIMUM_OBSERVATIONS - 1u;
        Settings_publishCharacterPreviewResult(
            entry->id, characterDigestHex(entry->source_sha256),
            characterTestTuningSignature(
                entry, edit, static_cast<unsigned>(context - 1)),
            characterTestPresentationSignature(), std::string(), disposition,
            publicationBase, &malformed);
        if (currentCharacterMotionReview(entry, edit, context, scene) != nullptr) {
            return;
        }
    }
    Settings_publishCharacterPreviewResult(
        entry->id, characterDigestHex(entry->source_sha256),
        characterTestTuningSignature(
            entry, edit, static_cast<unsigned>(context - 1)),
        characterTestPresentationSignature(), std::string(), disposition,
        publicationBase, &review);
}

bool drawCharacterOffsetSuggestion(
    const MdkrModernCharacterEntry *entry, CharacterTuningEdit &edit,
    unsigned context, const MdkrCharacterPreviewResult &result) {
    CharacterTuningEdit::Context &placement = edit.context[context];
    const CharacterWorkshopFitMeasurement measurement =
        characterWorkshopFitMeasurement(
            result, context != MDKR_CHARACTER_CONTEXT_SELECT);
    const CharacterWorkshopFitSuggestion suggestion =
        CharacterWorkshop_suggestFit(measurement);
    if (!suggestion.available) {
        ImGui::TextColored(
            AppTheme::bad(),
            "The exact renderer did not return a usable fit measurement.");
        ui::TextSubtleWrapped(
            "Keep the current values, inspect the package validation report, and rerun this context. No correction was guessed.");
        return false;
    }
    drawCharacterFitQualityBands(
        CharacterWorkshop_assessFit(measurement), result);

    ImGui::Text(
        "Rendered height %.3f m · lowest point %.3f m · visibility target %.3f m",
        static_cast<double>(suggestion.measuredHeightMetres),
        static_cast<double>(suggestion.measuredMinimumYMetres),
        static_cast<double>(suggestion.targetMinimumYMetres));
    if (!suggestion.verticalAdjustment && !suggestion.facingAdjustment) {
        ImGui::TextColored(
            AppTheme::good(),
            suggestion.facingMeasured
                ? "Ground/seat visibility and forward direction are within the measured starting range."
                : "Ground/seat visibility is within the measured starting range; forward direction was not measurable.");
        ui::TextSubtleWrapped(
            "This checks bounds and facing, not silhouette quality or hand and foot contact. Review the actual scene before approving the context.");
        return false;
    }

    if (suggestion.verticalAdjustment) {
        ImGui::TextColored(
            AppTheme::accent(), "Suggested vertical change: %+.3f m",
            static_cast<double>(suggestion.verticalDeltaMetres));
    }
    if (suggestion.facingAdjustment) {
        ImGui::TextColored(
            AppTheme::accent(), "Suggested facing change: %+.1f degrees",
            static_cast<double>(suggestion.yawDeltaDegrees));
    }
    ui::TextSubtleWrapped(
        context == MDKR_CHARACTER_CONTEXT_SELECT
            ? suggestion.facingMeasured
                ? "The proposal places the measured lower bound on the exact selection-room floor and points the model along target-space +Z."
                : "The proposal places the measured lower bound on the exact selection-room floor. Facing remains unchanged because the renderer did not provide a usable horizontal forward vector."
            : "The proposal is a conservative visibility-first seat fit: approximately one quarter of the measured height remains below the donor seat. Because bounds cannot see the vehicle shell or costume silhouette, rerun the exact preview after applying it.");
    if (!ImGui::Button("Apply measured starting point")) return false;

    placement.offset[1] = std::clamp(
        placement.offset[1] + suggestion.verticalDeltaMetres,
        -10.0f, 10.0f);
    placement.rotation[1] = characterWorkshopWrappedDegrees(
        placement.rotation[1] + suggestion.yawDeltaDegrees);
    if (!persistCharacterTuning(entry->id, edit)) return false;
    setStatus(
        "Measured starting point saved. Rerun the exact context before approving it.",
        AppTheme::good());
    return true;
}

bool drawCharacterTuningEditor(int player,
                               const MdkrModernCharacterEntry *entry,
                               bool compact) {
    static const char *vehicleNames[] = {"Car", "Hovercraft", "Plane"};
    static const char *contextNames[MDKR_CHARACTER_CONTEXT_COUNT] = {
        "Character select", "Car", "Hovercraft", "Plane"
    };
    static const MdkrCharacterPreviewContext previewContexts[
        MDKR_CHARACTER_CONTEXT_COUNT] = {
            MDKR_CHARACTER_PREVIEW_SELECT,
            MDKR_CHARACTER_PREVIEW_CAR,
            MDKR_CHARACTER_PREVIEW_HOVERCRAFT,
            MDKR_CHARACTER_PREVIEW_PLANE,
        };
    static const char *forwardNames[] = {"+Z", "-Z", "+X", "-X"};
    bool changed = false;
    const bool contactReady = entry->rig_present != 0u &&
        entry->rig_mode == MDKR_MODERN_RIG_HUMANOID_RETARGET_V1 &&
        (entry->rig_flags & MDKR_MODERN_RIG_REVIEWED) != 0u &&
        entry->rig_role_mask == MDKR_CHARACTER_RIG_HUMANOID_MASK;
    CharacterTuningEdit &edit = loadCharacterTuning(player, entry->id);
    edit.vehicleMask &= entry->vehicle_mask;
    if (edit.vehicleMask == 0u) edit.vehicleMask = entry->vehicle_mask;
    CharacterHistoryFrame history = beginCharacterHistory(
        entry, CharacterHistoryTool::Fit);
    if (std::getenv("MDKR_APP_UI_TRACE") != nullptr &&
        g_characterSpatialControlTracePackages.insert(entry->id).second) {
        std::fprintf(
            stderr,
            "[app-ui] character-spatial-controls package=%s planes=front,side,top placement=ground-or-seat yaw=context contacts=4 copy=vehicle-only undo=fit-history\n",
            entry->id);
        std::fprintf(
            stderr,
            "[app-ui] character-offset-studio package=%s contexts=select,car,hovercraft,plane guided-fit=1 workflow=preview,measure,fine-tune,evidence,review exact-rom-preview=1 inline-exact-still=managed-cache,scene-held-midpoint-auto-return compact-preview=1 disabled-package-preview=1 measured-starting-point=vertical,facing,contacts-least-squares quality-bands=datum,facing,proportions camera-occlusion=exact-visual-only reset=package-anchor review=current-source-and-fit\n",
            entry->id);
    }

    const bool showFitInputs = ImGui::TreeNode(
        "Setup: source size, facing, and vehicle coverage");
    ui::SpeakFocusedItem(
        "Offset Studio setup", showFitInputs ? "expanded" : "collapsed",
        "Contains infrequent source normalization and vehicle coverage controls. Exact context preview and fitting follow immediately after it.");
    if (showFitInputs) {
        ImGui::TextUnformatted("Vehicles to fit and use");
        for (unsigned vehicle = 0u; vehicle < 3u; ++vehicle) {
            if (vehicle != 0u) ImGui::SameLine();
            const unsigned bit = 1u << vehicle;
            const bool qualified = (entry->vehicle_mask & bit) != 0u;
            bool enabled = (edit.vehicleMask & bit) != 0u;
            if (!qualified) ImGui::BeginDisabled();
            const std::string label = std::string(vehicleNames[vehicle]) +
                "##vehicle-" + std::to_string(vehicle);
            if (ImGui::Checkbox(label.c_str(), &enabled)) {
                const unsigned candidate = enabled
                    ? edit.vehicleMask | bit : edit.vehicleMask & ~bit;
                if ((candidate & entry->vehicle_mask) != 0u) {
                    edit.vehicleMask = candidate;
                    changed |= persistCharacterTuning(entry->id, edit);
                } else {
                    setStatus(
                        "Keep at least one qualified vehicle pairing enabled.",
                        AppTheme::bad());
                }
            }
            if (!qualified) ImGui::EndDisabled();
        }
        ui::TextSubtleWrapped(
            "Choose where this appearance can be used. The built-in vehicle still controls physics and handling.");
        ui::HelpMarker(
            "This local selection is limited to the package's authenticated compatibility mask. It changes presentation eligibility only; simulation and records remain owned by the built-in donor.");

        ImGui::SeparatorText("Source normalization");
        if ((entry->calibration_flags & 1u) != 0u) {
            ImGui::TextColored(
                AppTheme::good(), "Normalized v2 profile · source faces %s",
                entry->source_forward < std::size(forwardNames)
                    ? forwardNames[entry->source_forward] : "unknown");
        } else {
            ImGui::TextColored(
                AppTheme::accent(),
                "Legacy transform: confirm height and facing before use");
        }
        if (entry->source_height > 0.0f && entry->target_height > 0.0f) {
            ImGui::TextDisabled(
                "Measured source extent %.4g m · intended standing height %.3g m",
                static_cast<double>(entry->source_height),
                static_cast<double>(entry->target_height));
            float height = entry->target_height * edit.scale;
            (void)ImGui::SliderFloat(
                "Standing height", &height, 0.25f, 3.0f, "%.2f m",
                ImGuiSliderFlags_AlwaysClamp);
            if (ImGui::IsItemDeactivatedAfterEdit()) {
                edit.scale = height / entry->target_height;
                if (edit.scale < 0.1f) edit.scale = 0.1f;
                if (edit.scale > 5.0f) edit.scale = 5.0f;
            }
        } else {
            (void)ImGui::SliderFloat(
                "Character size", &edit.scale, 0.1f, 5.0f, "%.2fx",
                ImGuiSliderFlags_AlwaysClamp);
        }
        if (ImGui::IsItemDeactivatedAfterEdit()) {
            changed |= persistCharacterTuning(entry->id, edit);
        }
        if (ImGui::Button("Turn model around 180°")) {
            edit.rotation[1] += 180.0f;
            if (edit.rotation[1] > 180.0f) edit.rotation[1] -= 360.0f;
            changed |= persistCharacterTuning(entry->id, edit);
        }
        ImGui::SameLine();
        if (ImGui::Button("Reset source facing")) {
            edit.rotation[0] = edit.rotation[1] = edit.rotation[2] = 0.0f;
            changed |= persistCharacterTuning(entry->id, edit);
        }
        ui::TextSubtleWrapped(
            "Facing cannot be inferred safely from arbitrary geometry. Use the author-declared axis first, then this explicit correction if the preview is backward.");
        ImGui::TreePop();
    }

    changed |= drawCharacterFacingStudio(entry, edit, compact);

    ImGui::SeparatorText("Offset Studio");
    ui::TextSubtleWrapped(
        "Author against the same donor character, vehicles, animations, cameras, and scene transforms used in game. Select aligns a measured ground point; each vehicle owns an independent pelvis/seat correction so fixing one context cannot break another.");
    if (donorProfilesAvailable()) {
        ImGui::TextColored(
            AppTheme::good(),
            "Linked ROM ready · exact game assets and simulation profiles available");
    } else {
        ImGui::TextColored(
            AppTheme::accent(),
            "Link and verify a supported base ROM on Play for exact in-game previews");
        ui::TextSubtleWrapped(
            "Numeric editing remains available without a ROM. The studio will not pretend a generic viewport can validate kart occlusion, selection-room placement, or the game camera.");
    }
    const bool selectReviewed = characterFitReviewed(
        entry, edit, MDKR_CHARACTER_CONTEXT_SELECT);
    unsigned vehicleContexts = 0u;
    unsigned reviewedVehicles = 0u;
    for (unsigned context = MDKR_CHARACTER_CONTEXT_CAR;
         context < MDKR_CHARACTER_CONTEXT_COUNT; ++context) {
        if ((edit.vehicleMask & (1u << (context - 1u))) == 0u) continue;
        ++vehicleContexts;
        if (characterFitReviewed(entry, edit, context)) ++reviewedVehicles;
    }
    ImGui::PushStyleColor(
        ImGuiCol_Text,
        selectReviewed && reviewedVehicles == vehicleContexts
            ? AppTheme::good() : AppTheme::accent());
    ImGui::TextWrapped(
        "Fit check: Character Select %s · %u of %u vehicles reviewed since your last change",
        selectReviewed ? "reviewed" : "needs review",
        reviewedVehicles, vehicleContexts);
    ImGui::PopStyleColor();
    int nextFitContext = -1;
    for (unsigned context = 0u;
         context < MDKR_CHARACTER_CONTEXT_COUNT; ++context) {
        const bool enabled = context == MDKR_CHARACTER_CONTEXT_SELECT ||
            (edit.vehicleMask & (1u << (context - 1u))) != 0u;
        if (enabled && !characterFitReviewed(entry, edit, context)) {
            nextFitContext = static_cast<int>(context);
            break;
        }
    }
    ImGui::SeparatorText("Fit all enabled contexts");
    ui::TextSubtleWrapped(
        "Work through Character select, Car, Hovercraft, and Plane in order. Each step keeps its own transform, exact renderer measurement, contact evidence, and source/fit-bound approval; finishing one never marks another ready.");
    for (unsigned context = 0u;
         context < MDKR_CHARACTER_CONTEXT_COUNT; ++context) {
        const bool enabled = context == MDKR_CHARACTER_CONTEXT_SELECT ||
            (edit.vehicleMask & (1u << (context - 1u))) != 0u;
        if (!enabled) continue;
        const bool reviewed = characterFitReviewed(entry, edit, context);
        ImGui::TextColored(
            reviewed ? AppTheme::good() : AppTheme::accent(),
            "%s · %s", contextNames[context],
            reviewed ? "reviewed" : "needs review");
    }
    if (nextFitContext >= 0) {
        const std::string continueLabel = std::string("Continue fit: ") +
            contextNames[nextFitContext];
        if (ImGui::Button(continueLabel.c_str())) {
            g_characterGuidedFitContexts[entry->id] = nextFitContext;
        }
        ui::SpeakFocusedItem(
            continueLabel.c_str(), "Next incomplete context",
            "Selects the next incomplete Offset Studio context. Preview, measure, fine-tune, inspect evidence, and explicitly review it before continuing.");
    } else {
        ImGui::TextColored(
            AppTheme::good(),
            "All enabled contexts have current source-and-fit-bound review");
    }
    int &guidedContext = g_characterGuidedFitContexts.try_emplace(
        entry->id, -1).first->second;
    const char *contactReviewFocus = std::getenv(
        "MDKR_APP_SMOKE_CHARACTER_CONTACT_REVIEW_FOCUS");
    static std::set<std::string> focusedContactReviewPackages;
    if (contactReviewFocus != nullptr &&
        std::strcmp(contactReviewFocus,
                    "mdkr64-character-contact-review-v1") == 0 &&
        focusedContactReviewPackages.insert(entry->id).second) {
        guidedContext = MDKR_CHARACTER_CONTEXT_CAR;
        const CharacterFitEvidenceSnapshot smokeEvidence =
            currentCharacterFitEvidenceSnapshot(
                entry, edit, MDKR_CHARACTER_PREVIEW_CAR);
        if (smokeEvidence.current) {
            publishCharacterMotionReviewSmokeFixture(
                entry, edit, MDKR_CHARACTER_PREVIEW_SELECT,
                smokeEvidence.result);
            for (unsigned scene = 0u;
                 scene < MDKR_CHARACTER_PREVIEW_SCENE_COUNT; ++scene) {
                publishCharacterMotionReviewSmokeFixture(
                    entry, edit, MDKR_CHARACTER_PREVIEW_CAR,
                    smokeEvidence.result,
                    static_cast<MdkrCharacterPreviewScene>(scene));
            }
        }
        std::fprintf(
            stderr,
            "[app-ui] character-contact-review-focus package=%s context=%u applied=1\n",
            entry->id,
            static_cast<unsigned>(MDKR_CHARACTER_CONTEXT_CAR));
    }
    if (ImGui::BeginTabBar("##character-placement-contexts")) {
        for (unsigned context = 0u;
             context < MDKR_CHARACTER_CONTEXT_COUNT; ++context) {
            const bool packageContext = context == MDKR_CHARACTER_CONTEXT_SELECT ||
                (entry->vehicle_mask & (1u << (context - 1u))) != 0u;
            if (!packageContext) continue;
            const ImGuiTabItemFlags tabFlags =
                guidedContext == static_cast<int>(context)
                    ? ImGuiTabItemFlags_SetSelected : 0;
            if (!ImGui::BeginTabItem(
                    contextNames[context], nullptr, tabFlags)) continue;
            if (guidedContext == static_cast<int>(context)) {
                guidedContext = -1;
            }
            CharacterTuningEdit::Context &placement = edit.context[context];
            ImGui::TextDisabled(
                "%s anchor to qualified %s %s frame",
                context == MDKR_CHARACTER_CONTEXT_SELECT ? "Ground" : "Pelvis/seat",
                donorName(entry->donor),
                context == MDKR_CHARACTER_CONTEXT_SELECT ? "select" :
                    contextNames[context]);
            ImGui::PushID(static_cast<int>(context));
            ImGui::SeparatorText("1. Preview in game");
            int &testPlayers = g_characterTestPlayers[entry->id];
            if (testPlayers < 1 || testPlayers > 4) testPlayers = 1;
            static const char *cameraLayouts[] = {
                "1 player", "2 player split-screen",
                "3 player split-screen", "4 player split-screen",
            };
            int cameraLayout = testPlayers - 1;
            ImGui::SetNextItemWidth(
                compact ? -1.0f
                        : std::min(280.0f, ImGui::GetContentRegionAvail().x));
            if (ImGui::Combo(
                    "Camera layout", &cameraLayout, cameraLayouts,
                    static_cast<int>(std::size(cameraLayouts)))) {
                testPlayers = cameraLayout + 1;
            }
            ui::SpeakFocusedItem(
                "Exact preview camera layout",
                cameraLayouts[cameraLayout],
                "Chooses the real one-to-four-player game camera layout used by the next exact context preview.");
            const bool exactPreviewReady = donorProfilesAvailable();
            const char *studioSmoke = std::getenv(
                "MDKR_APP_SMOKE_CHARACTER_STUDIO_TOKEN");
            static std::set<std::string> studioSmokePackages;
            if (context == MDKR_CHARACTER_CONTEXT_SELECT &&
                exactPreviewReady && studioSmoke != nullptr &&
                std::strcmp(studioSmoke,
                            "mdkr64-character-studio-v1") == 0 &&
                studioSmokePackages.insert(entry->id).second &&
                persistCharacterTuning(entry->id, edit)) {
                requestCharacterPreview(
                    entry, previewContexts[context], testPlayers,
                    MDKR_CHARACTER_PREVIEW_POSE_LIVE, 0u, 0, 0,
                    MDKR_WORKSHOP_PREVIEW_LIGHTING_NEUTRAL, nullptr,
                    MDKR_CHARACTER_PREVIEW_CAPTURE_SCENE,
                    MDKR_CHARACTER_PREVIEW_POSE_LIVE, 0u,
                    interactiveCharacterStudioRoute());
                std::fprintf(
                    stderr,
                    "[app-ui] exact-character-studio smoke requested package=%s context=%u\n",
                    entry->id, context);
            }
            if (!exactPreviewReady) ImGui::BeginDisabled();
            const std::string previewLabel = std::string("Open exact ") +
                contextNames[context] + " preview";
            if (ImGui::Button(previewLabel.c_str()) && exactPreviewReady &&
                persistCharacterTuning(entry->id, edit)) {
                requestCharacterPreview(
                    entry, previewContexts[context], testPlayers,
                    MDKR_CHARACTER_PREVIEW_POSE_LIVE, 0u, 0, 0,
                    MDKR_WORKSHOP_PREVIEW_LIGHTING_NEUTRAL, nullptr,
                    MDKR_CHARACTER_PREVIEW_CAPTURE_SCENE,
                    MDKR_CHARACTER_PREVIEW_POSE_LIVE, 0u,
                    interactiveCharacterStudioRoute());
            }
            if (!exactPreviewReady) ImGui::EndDisabled();
            ui::SpeakFocusedItem(
                previewLabel.c_str(),
                exactPreviewReady
                    ? "Ready; current fit will be saved before launch."
                    : "Unavailable until a supported base ROM is linked and verified on Play.",
                "Opens the real game scene with the selected donor character and vehicle. It works while the custom character is still disabled for ordinary play.");
            if (!compact) ImGui::SameLine();
            ImGui::TextDisabled(
                "%d-player camera · returns here with measurements",
                testPlayers);
            const MdkrCharacterPreviewContext previewContext =
                previewContexts[context];
            {
                const char *inlineCaptureLabel = "Capture exact still";
                if (!exactPreviewReady) ImGui::BeginDisabled();
                if (ImGui::Button(inlineCaptureLabel,
                                  ui::kBtnSecondary()) && exactPreviewReady) {
                    std::string capturePath;
                    if (persistCharacterTuning(entry->id, edit) &&
                        prepareInlineCharacterCapture(
                            entry, previewContext, capturePath)) {
                        requestCharacterPreview(
                            entry, previewContext, testPlayers,
                            context == MDKR_CHARACTER_CONTEXT_SELECT
                                ? MDKR_CHARACTER_PREVIEW_POSE_SELECT_IDLE
                                : MDKR_CHARACTER_PREVIEW_POSE_RACE_STEER,
                            500u, 0, 0,
                            MDKR_WORKSHOP_PREVIEW_LIGHTING_NEUTRAL,
                            capturePath.c_str(),
                            MDKR_CHARACTER_PREVIEW_CAPTURE_SCENE,
                            MDKR_CHARACTER_PREVIEW_POSE_LIVE, 0u,
                            inlineCharacterStillRoute());
                    }
                }
                if (!exactPreviewReady) ImGui::EndDisabled();
                ui::SpeakFocusedItem(
                    inlineCaptureLabel,
                    exactPreviewReady
                        ? "Ready; saves the current fit before capture."
                        : "Unavailable until a supported base ROM is linked and verified on Play.",
                    "Renders one stabilized current-context frame with the exact game assets into a bounded launcher-owned cache, then returns automatically to this Offset Studio context. The digest-bound still appears with the exact evidence below; no filename is required.");
                if (!compact && ImGui::GetContentRegionAvail().x >= 360.0f) {
                    ImGui::SameLine();
                }
                ImGui::TextDisabled("held midpoint · neutral gameplay light");
            }
            {
                const auto comparisonRun =
                    g_characterComparisonRuns.find(entry->id);
                const bool comparisonRunActive =
                    comparisonRun != g_characterComparisonRuns.end() &&
                    comparisonRun->second.active;
                const bool comparisonLaunchPending =
                    comparisonRunActive && g_characterPreviewRequested;
                const char *referenceLabel = comparisonLaunchPending
                    ? "Comparison capture in progress…"
                    : g_characterPreviewRequested
                        ? "Another exact preview is queued…"
                    : comparisonRunActive
                        ? "Retry registered comparison pair"
                    : "Capture registered comparison pair";
                if (!exactPreviewReady || g_characterPreviewRequested) {
                    ImGui::BeginDisabled();
                }
                if (ImGui::Button(referenceLabel, ui::kBtnSecondary()) &&
                    exactPreviewReady && !g_characterPreviewRequested) {
                    std::string capturePath;
                    if (persistCharacterTuning(entry->id, edit) &&
                        prepareInlineCharacterCapture(
                            entry, previewContext, capturePath, true)) {
                        CharacterComparisonRun &run =
                            g_characterComparisonRuns[entry->id];
                        run.active = true;
                        run.awaitingDonor = true;
                        run.context = previewContext;
                        run.sourceSha256 =
                            characterDigestHex(entry->source_sha256);
                        run.fitSha256 = characterTestTuningSignature(
                            entry, edit, context);
                        run.presentationSha256 =
                            characterTestPresentationSignature();
                        const int comparisonYaw =
                            previewContext == MDKR_CHARACTER_PREVIEW_SELECT
                                ? 0 : 180;
                        requestCharacterPreview(
                            entry, previewContext, 1,
                            context == MDKR_CHARACTER_CONTEXT_SELECT
                                ? MDKR_CHARACTER_PREVIEW_POSE_SELECT_IDLE
                                : MDKR_CHARACTER_PREVIEW_POSE_RACE_STEER,
                            500u, comparisonYaw, 0,
                            MDKR_WORKSHOP_PREVIEW_LIGHTING_NEUTRAL,
                            capturePath.c_str(),
                            MDKR_CHARACTER_PREVIEW_CAPTURE_SCENE,
                            MDKR_CHARACTER_PREVIEW_POSE_LIVE, 0u,
                            donorReferenceStillRoute());
                        if (!g_characterPreviewRequested) {
                            run.active = false;
                        }
                    }
                }
                if (!exactPreviewReady || g_characterPreviewRequested) {
                    ImGui::EndDisabled();
                }
                ui::SpeakFocusedItem(
                    referenceLabel,
                    comparisonLaunchPending
                        ? "The guided donor and custom capture is already in progress."
                    : g_characterPreviewRequested
                        ? "Another exact preview is already queued."
                    : comparisonRunActive
                        ? "The previous launch did not return a complete pair; retry starts both captures again."
                    : exactPreviewReady
                        ? "Ready; captures the chosen donor, then the custom character, and returns automatically after each."
                        : "Unavailable until a supported base ROM is linked and verified on Play.",
                    "Runs a two-capture guided comparison. First it renders the chosen retail donor, kart, attachments, course, and gameplay camera while retaining an invisible exact custom pose/projection witness. It then captures the custom character with the same contract. An overlay appears only if both witnesses match exactly; neither image can satisfy fit or performance approval by itself.");
                if (!compact && ImGui::GetContentRegionAvail().x >= 360.0f) {
                    ImGui::SameLine();
                }
                ImGui::TextDisabled(
                    comparisonLaunchPending
                        ? "Please wait · returns here automatically"
                        : g_characterPreviewRequested
                            ? "Wait for the queued preview to launch"
                        : comparisonRunActive
                            ? "Interrupted · retry restarts the pair"
                        : "2 automatic captures · 1 player · verified registration");
                if (comparisonRunActive && !comparisonLaunchPending) {
                    if (!compact) ImGui::SameLine();
                    if (ImGui::Button("Stop comparison")) {
                        g_characterComparisonRuns[entry->id].active = false;
                        setStatus(
                            "Registered comparison stopped. Existing retained captures were preserved; no fit, package, or approval state changed.",
                            AppTheme::subtle());
                    }
                    ui::SpeakFocusedItem(
                        "Stop registered comparison", nullptr,
                        "Ends only the interrupted two-capture workflow. Any already retained digest-bound images remain in the visual report tray.");
                }
            }
            std::array<const CharacterMotionReviewSessionResult *,
                       MDKR_CHARACTER_PREVIEW_SCENE_COUNT> motionReviews{};
            const unsigned motionSceneCount =
                characterMotionReviewSceneCount(previewContext);
            unsigned completedMotionScenes = 0u;
            for (unsigned sceneIndex = 0u;
                 sceneIndex < motionSceneCount; ++sceneIndex) {
                motionReviews[sceneIndex] = currentCharacterMotionReview(
                    entry, edit, previewContext,
                    static_cast<MdkrCharacterPreviewScene>(sceneIndex));
                if (motionReviews[sceneIndex] != nullptr) {
                    ++completedMotionScenes;
                }
            }
            const bool completeSceneReview =
                completedMotionScenes == motionSceneCount;
            {
                const bool vehicleMotion =
                    context != MDKR_CHARACTER_CONTEXT_SELECT;
                ImGui::SeparatorText(
                    vehicleMotion
                        ? "Complete motion and scene check"
                        : "Complete semantic motion check");
                ui::TextSubtleWrapped(
                    vehicleMotion
                        ? "One guided workflow checks every race semantic against this vehicle on five qualified courses: open baseline, dense scenery, alternate climate, dark/enclosed visibility, and effects-heavy presentation. Each course visibly holds both steering extremes, reverse, boost, item, damage, spin, airborne, landing, and both finishes for at least 60 complete character draws. The launcher returns and advances automatically; completed courses remain resumable if a later launch stops."
                        : "One guided run checks select idle, hover, and confirm in the real selection room. The game settles and visibly holds all three states for at least 60 complete character draws, then returns automatically with fresh framing and visibility evidence.");
                CharacterSceneReviewRun &sceneRun =
                    g_characterSceneReviewRuns[entry->id];
                const bool runIdentityCurrent = !sceneRun.active ||
                    (sceneRun.context == previewContext &&
                     sceneRun.sourceSha256 ==
                         characterDigestHex(entry->source_sha256) &&
                     sceneRun.fitSha256 == characterTestTuningSignature(
                         entry, edit, context) &&
                     sceneRun.presentationSha256 ==
                         characterTestPresentationSignature());
                if (!runIdentityCurrent) {
                    sceneRun.active = false;
                    sceneRun.refreshAll = false;
                }
                const bool sceneLaunchPending =
                    sceneRun.active && g_characterPreviewRequested;
                const char *motionLabel = sceneLaunchPending
                    ? "Scene review in progress…"
                    : sceneRun.active
                        ? "Retry current course"
                        : completeSceneReview
                            ? "Run complete review again"
                            : completedMotionScenes != 0u
                                ? "Resume remaining scenes"
                                : vehicleMotion
                                    ? "Review all motion and scenes"
                                    : "Review all motion states";
                const bool motionButtonDisabled =
                    !exactPreviewReady || sceneLaunchPending;
                if (motionButtonDisabled) {
                    ImGui::BeginDisabled();
                }
                if (ImGui::Button(motionLabel, ui::kBtnSecondary()) &&
                    exactPreviewReady &&
                    persistCharacterTuning(entry->id, edit)) {
                    const bool resumingInterruptedRun = sceneRun.active;
                    MdkrCharacterPreviewScene startScene = sceneRun.active
                        ? sceneRun.nextScene
                        : MDKR_CHARACTER_PREVIEW_SCENE_BASELINE;
                    if (!sceneRun.active && !completeSceneReview) {
                        for (unsigned sceneIndex = 0u;
                             sceneIndex < motionSceneCount; ++sceneIndex) {
                            if (motionReviews[sceneIndex] == nullptr) {
                                startScene =
                                    static_cast<MdkrCharacterPreviewScene>(
                                        sceneIndex);
                                break;
                            }
                        }
                    }
                    sceneRun.active = true;
                    if (!resumingInterruptedRun) {
                        sceneRun.refreshAll = completeSceneReview;
                    }
                    sceneRun.context = previewContext;
                    sceneRun.nextScene = startScene;
                    sceneRun.sourceSha256 =
                        characterDigestHex(entry->source_sha256);
                    sceneRun.fitSha256 = characterTestTuningSignature(
                        entry, edit, context);
                    sceneRun.presentationSha256 =
                        characterTestPresentationSignature();
                    requestCharacterPreview(
                        entry, previewContext, 1,
                        vehicleMotion
                            ? MDKR_CHARACTER_PREVIEW_POSE_RACE_STEER
                            : MDKR_CHARACTER_PREVIEW_POSE_SELECT_IDLE,
                        vehicleMotion ? 0u : 500u,
                        0, 0, MDKR_WORKSHOP_PREVIEW_LIGHTING_NEUTRAL,
                        nullptr, MDKR_CHARACTER_PREVIEW_CAPTURE_SCENE,
                        MDKR_CHARACTER_PREVIEW_POSE_LIVE, 0u,
                        representativeMotionReviewRoute(startScene));
                    if (!g_characterPreviewRequested) {
                        sceneRun.active = false;
                        sceneRun.refreshAll = false;
                    }
                }
                if (motionButtonDisabled) {
                    ImGui::EndDisabled();
                }
                const bool sceneLaunchNowPending =
                    sceneRun.active && g_characterPreviewRequested;
                ui::SpeakFocusedItem(
                    motionLabel,
                    sceneLaunchNowPending
                        ? "In progress; the launcher advances after each exact course."
                        : sceneRun.active
                            ? "The last course did not return evidence. Retry it without losing completed courses."
                            : exactPreviewReady
                                ? vehicleMotion
                                    ? "Ready; five qualified courses, 11 race samples per course, automatic return and resume."
                                    : "Ready; fixed one-player exact camera, all three select states visibly held, automatic return."
                                : "Unavailable until a supported base ROM is linked and verified on Play.",
                    vehicleMotion
                        ? "Runs a bounded exact-game review across the complete race semantic library on open, dense, alternate-climate, dark/enclosed, and effects-heavy courses. It does not save performance evidence or require manual game navigation."
                        : "Runs a bounded exact-game review across idle, hover, and confirm. It does not save performance evidence or require manual game navigation.");
                if (sceneRun.active && !sceneLaunchNowPending) {
                    ImGui::SameLine();
                    if (ImGui::Button("Stop review")) {
                        sceneRun.active = false;
                        sceneRun.refreshAll = false;
                        setStatus(
                            "Guided scene review stopped. Completed courses remain current and can be resumed later.",
                            AppTheme::subtle());
                    }
                    ui::SpeakFocusedItem(
                        "Stop review", nullptr,
                        "Stops automatic course progression without deleting any completed evidence.");
                }
                const auto packageMotion =
                    g_characterMotionReviewResults.find(entry->id);
                const bool staleMotionReview =
                    completedMotionScenes == 0u &&
                    packageMotion != g_characterMotionReviewResults.end() &&
                    std::any_of(
                        packageMotion->second.begin(),
                        packageMotion->second.end(),
                        [previewContext](const auto &stored) {
                            return stored.second.result.context ==
                                previewContext;
                        });
                ImGui::TextColored(
                    completeSceneReview ? AppTheme::good()
                                        : AppTheme::accent(),
                    vehicleMotion ? "Qualified courses: %u of %u current"
                                  : "Selection room: %u of %u current",
                    completedMotionScenes, motionSceneCount);
                for (unsigned sceneIndex = 0u;
                     sceneIndex < motionSceneCount; ++sceneIndex) {
                    const CharacterReviewSceneDefinition &sceneDefinition =
                        kCharacterReviewScenes[sceneIndex];
                    const char *course = vehicleMotion
                        ? sceneDefinition.course[context -
                              MDKR_CHARACTER_CONTEXT_CAR]
                        : "Character Select";
                    ImGui::PushID(static_cast<int>(sceneIndex));
                    if (motionReviews[sceneIndex] != nullptr) {
                        ImGui::SeparatorText(course);
                        ImGui::TextDisabled(
                            "%s · current source, fit, LOD, and presentation",
                            vehicleMotion ? sceneDefinition.pressure
                                          : "Authored selection room");
                        drawCharacterMotionReviewSummary(
                            *motionReviews[sceneIndex],
                            compact || motionSceneCount > 1u);
                    } else {
                        ImGui::BulletText(
                            "%s · %s · not current",
                            course,
                            vehicleMotion ? sceneDefinition.pressure
                                          : "Authored selection room");
                    }
                    ImGui::PopID();
                }
                if (completeSceneReview) {
                    ImGui::TextColored(
                        AppTheme::good(),
                        vehicleMotion
                            ? "All 55 exact race-and-scene samples are current."
                            : "All three exact select states are current.");
                } else if (staleMotionReview) {
                    ImGui::TextColored(
                        AppTheme::accent(),
                        "Previous review evidence is out of date for the current source, fit, LOD, or presentation settings.");
                } else if (characterFitReviewed(entry, edit, context)) {
                    ImGui::TextColored(
                        AppTheme::good(),
                        vehicleMotion
                            ? "The current approval records all five course batteries; rerun to refresh session measurements."
                            : "Complete three-state select review is recorded in the current approval; rerun to refresh detailed measurements.");
                } else {
                    ImGui::TextDisabled(
                        "Not run for the current source and fit");
                }
            }
            CharacterFitEvidenceSnapshot fitEvidence =
                currentCharacterFitEvidenceSnapshot(
                    entry, edit, previewContext);
            ImGui::SeparatorText("2. Apply measured starting point");
            if (!fitEvidence.current) {
                ImGui::TextDisabled(
                    "No measurement matches this source and fit yet. Open the exact preview, inspect the scene, then return here.");
            } else {
                const bool appliedSuggestion = drawCharacterOffsetSuggestion(
                    entry, edit, context, fitEvidence.result);
                changed |= appliedSuggestion;
                if (appliedSuggestion) {
                    fitEvidence = currentCharacterFitEvidenceSnapshot(
                        entry, edit, previewContext);
                }
            }
            ImGui::SeparatorText("3. Fine-tune this context");
            (void)ImGui::SliderFloat("Context size", &placement.scale,
                                     0.5f, 2.0f, "%.2fx",
                                     ImGuiSliderFlags_AlwaysClamp);
            if (ImGui::IsItemDeactivatedAfterEdit()) {
                changed |= persistCharacterTuning(entry->id, edit);
            }
            (void)ImGui::DragFloat3("Position", placement.offset, 0.01f,
                                    -10.0f, 10.0f, "%.3f m",
                                    ImGuiSliderFlags_AlwaysClamp);
            if (ImGui::IsItemDeactivatedAfterEdit()) {
                changed |= persistCharacterTuning(entry->id, edit);
            }
            (void)ImGui::DragFloat3("Rotation", placement.rotation, 0.5f,
                                    -180.0f, 180.0f, "%.1f deg",
                                    ImGuiSliderFlags_AlwaysClamp);
            if (ImGui::IsItemDeactivatedAfterEdit()) {
                changed |= persistCharacterTuning(entry->id, edit);
            }
            if (ImGui::TreeNodeEx(
                    "Spatial controls",
                    ImGuiTreeNodeFlags_DefaultOpen)) {
                ui::TextSubtleWrapped(
                    "Move the fitted character around its automatic ground or seat anchor in front, side, or top view. The blue forward arrow is the saved context yaw, not the camera. These controls and the exact numeric fields above edit the same values.");
                const std::string spatialKey = std::string(entry->id) + "#" +
                    std::to_string(context);
                int &spatialView = g_characterFitSpatialViews[spatialKey];
                const CharacterSpatialPlane plane =
                    drawCharacterSpatialPlaneSelector(
                        "fit-plane", spatialView);
                const bool wideSpatial =
                    ImGui::GetContentRegionAvail().x >= 500.0f;
                ImGui::BeginGroup();
                CharacterSpatialEditResult positionResult =
                    drawCharacterSpatialPad(
                        "##fit-position-pad",
                        context == MDKR_CHARACTER_CONTEXT_SELECT
                            ? "Ground-fit correction control"
                            : "Seat-fit correction control",
                        &placement.offset, 1u, 0u, plane,
                        std::max(0.5f, entry->target_height * edit.scale *
                                          placement.scale),
                        10.0f, 0.01f, "zero = automatic anchor", nullptr);
                ImGui::EndGroup();
                if (wideSpatial) ImGui::SameLine();
                ImGui::BeginGroup();
                ImGui::TextUnformatted("Facing in target space");
                CharacterSpatialEditResult yawResult =
                    drawCharacterYawDial(
                        "##fit-yaw-dial", "Context-facing control",
                        placement.rotation[1]);
                ImGui::EndGroup();
                if (positionResult.commit || yawResult.commit) {
                    changed |= persistCharacterTuning(entry->id, edit);
                }
                ImGui::TreePop();
            }
            if (ImGui::Button("Reset to package anchor")) {
                placement.scale = 1.0f;
                placement.offset[0] = placement.offset[1] =
                    placement.offset[2] = 0.0f;
                placement.rotation[0] = placement.rotation[1] =
                    placement.rotation[2] = 0.0f;
                changed |= persistCharacterTuning(entry->id, edit);
            }
            ImGui::SameLine();
            ImGui::TextDisabled(
                context == MDKR_CHARACTER_CONTEXT_SELECT
                    ? "ground-anchor baseline"
                    : "seat-anchor baseline; not an automatic fit");
            ui::SpeakFocusedItem(
                "Reset to package anchor", nullptr,
                "Clears this context's size, position, and rotation corrections. It does not claim the package anchor is already fitted to the scene.");
            if (context != MDKR_CHARACTER_CONTEXT_SELECT) {
                if (!contactReady) ImGui::BeginDisabled();
                if (ImGui::TreeNodeEx(
                        "Hand and foot contacts",
                        ImGuiTreeNodeFlags_DefaultOpen)) {
                    static const char *contactLabels[
                        MDKR_MODERN_CHARACTER_CONTACTS] = {
                            "Left hand", "Right hand", "Left foot", "Right foot"
                        };
                    ui::TextSubtleWrapped(
                        "Fine-tune the engine-owned contact targets in metres relative to the mapped hips at the seat frame. These affect missing-semantic reference motion only; explicit authored clips remain untouched.");
                    std::array<std::array<float, 3>, 4> currentContacts{};
                    for (unsigned contact = 0u;
                         contact < MDKR_MODERN_CHARACTER_CONTACTS;
                         ++contact) {
                        for (unsigned axis = 0u; axis < 3u; ++axis) {
                            currentContacts[contact][axis] =
                                placement.contacts[contact][axis];
                        }
                    }
                    constexpr size_t kMaximumContactMeasurements =
                        MDKR_CHARACTER_PREVIEW_SCENE_COUNT *
                        MDKR_CHARACTER_MOTION_REVIEW_VEHICLE_SAMPLE_COUNT;
                    std::array<CharacterWorkshopContactMeasurement,
                               kMaximumContactMeasurements>
                        contactMeasurements{};
                    size_t contactMeasurementCount = 0u;
                    const auto appendContactMeasurement = [&](const
                        MdkrCharacterPreviewResult &sample) {
                        if (sample.contact_witness_mask == 0u ||
                            contactMeasurementCount >=
                                contactMeasurements.size()) return;
                        CharacterWorkshopContactMeasurement &measurement =
                            contactMeasurements[contactMeasurementCount++];
                        measurement.witnessMask = sample.contact_witness_mask;
                        for (unsigned contact = 0u;
                             contact < MDKR_CHARACTER_PREVIEW_CONTACTS;
                             ++contact) {
                            for (unsigned axis = 0u; axis < 3u; ++axis) {
                                measurement.targetMicrometres[contact][axis] =
                                    sample.contact_target_micrometres
                                        [contact][axis];
                                measurement.endpointMicrometres[contact][axis] =
                                    sample.contact_end_micrometres
                                        [contact][axis];
                            }
                        }
                    };
                    if (completeSceneReview) {
                        for (unsigned sceneIndex = 0u;
                             sceneIndex < motionSceneCount; ++sceneIndex) {
                            const CharacterMotionReviewSessionResult *review =
                                motionReviews[sceneIndex];
                            for (unsigned sampleIndex = 0u;
                                 sampleIndex < review->result.sample_count;
                                 ++sampleIndex) {
                                appendContactMeasurement(
                                    review->result.samples[sampleIndex]);
                            }
                        }
                    } else if (fitEvidence.current) {
                        appendContactMeasurement(fitEvidence.result);
                    }
                    const CharacterWorkshopContactSuggestion
                        contactSuggestion = CharacterWorkshop_suggestContacts(
                            currentContacts, contactMeasurements.data(),
                            contactMeasurementCount);
                    if (std::getenv("MDKR_APP_UI_TRACE") != nullptr &&
                        contactSuggestion.available) {
                        const std::string traceKey =
                            std::string(entry->id) + ":" +
                            std::to_string(context) + ":" +
                            fitEvidence.fitSha256;
                        static std::set<std::string>
                            tracedContactSuggestions;
                        if (tracedContactSuggestions.insert(traceKey).second) {
                            std::fprintf(
                                stderr,
                                "[app-ui] character-contact-suggestion package=%s context=%u witness-samples=%u mask=%x adjustment=%d within-limits=%d\n",
                                entry->id, context,
                                contactSuggestion.witnessSamples,
                                contactSuggestion.contactMask,
                                contactSuggestion.adjustment ? 1 : 0,
                                contactSuggestion.withinLimits ? 1 : 0);
                        }
                    }
                    ImGui::SeparatorText("Measured starting point");
                    if (!contactSuggestion.valid) {
                        ImGui::TextColored(
                            AppTheme::bad(),
                            "The exact contact witnesses are inconsistent; rerun this context.");
                    } else if (!contactSuggestion.available) {
                        ImGui::TextDisabled(
                            "No procedural contact witness is available in the current exact evidence.");
                        ui::TextSubtleWrapped(
                            "Authored clips and locked solvers do not expose a target correction. You can still tune the controls below by visual review.");
                    } else {
                        ImGui::TextUnformatted(
                            completeSceneReview
                                ? "Complete scene review"
                                : "Current exact pose");
                        ImGui::SameLine();
                        ImGui::TextDisabled(
                            "· %u witnessed state%s",
                            contactSuggestion.witnessSamples,
                            contactSuggestion.witnessSamples == 1u
                                ? "" : "s");
                        ui::TextSubtleWrapped(
                            "This source-and-fit-bound proposal averages endpoint minus target across the exact sampled states. It is the smallest constant least-squares correction for those witnesses. Positive values move the named target along the target-space axis; inspect wheel, control, and foot placement after applying it.");
                        for (unsigned contact = 0u;
                             contact < MDKR_MODERN_CHARACTER_CONTACTS;
                             ++contact) {
                            if ((contactSuggestion.contactMask &
                                 (1u << contact)) == 0u) continue;
                            ImGui::Text(
                                "%s · %u state%s",
                                contactLabels[contact],
                                contactSuggestion.sampleCounts[contact],
                                contactSuggestion.sampleCounts[contact] == 1u
                                    ? "" : "s");
                            ImGui::TextDisabled(
                                "X %+.1f mm · Y %+.1f mm · Z %+.1f mm",
                                contactSuggestion.deltaMetres[contact][0] *
                                    1000.0f,
                                contactSuggestion.deltaMetres[contact][1] *
                                    1000.0f,
                                contactSuggestion.deltaMetres[contact][2] *
                                    1000.0f);
                        }
                        if (!contactSuggestion.withinLimits) {
                            ImGui::TextColored(
                                AppTheme::accent(),
                                "One or more proposed targets exceed the +/-1 m safety range. Adjust root scale or placement and retest first.");
                        } else if (!contactSuggestion.adjustment) {
                            ImGui::TextColored(
                                AppTheme::good(),
                                "The measured endpoints are already centred on their targets.");
                        } else {
                            std::string spokenProposal =
                                std::to_string(
                                    contactSuggestion.witnessSamples) +
                                (contactSuggestion.witnessSamples == 1u
                                     ? " exact state. "
                                     : " exact states. ");
                            for (unsigned contact = 0u;
                                 contact < MDKR_MODERN_CHARACTER_CONTACTS;
                                 ++contact) {
                                if ((contactSuggestion.contactMask &
                                     (1u << contact)) == 0u) continue;
                                char delta[160];
                                std::snprintf(
                                    delta, sizeof(delta),
                                    "%s delta X %+.1f, Y %+.1f, Z %+.1f millimetres from %u states. ",
                                    contactLabels[contact],
                                    contactSuggestion.deltaMetres[contact][0] *
                                        1000.0f,
                                    contactSuggestion.deltaMetres[contact][1] *
                                        1000.0f,
                                    contactSuggestion.deltaMetres[contact][2] *
                                        1000.0f,
                                    contactSuggestion.sampleCounts[contact]);
                                spokenProposal += delta;
                            }
                            if (ImGui::Button("Apply measured offsets")) {
                                for (unsigned contact = 0u;
                                     contact <
                                         MDKR_MODERN_CHARACTER_CONTACTS;
                                     ++contact) {
                                    if ((contactSuggestion.contactMask &
                                         (1u << contact)) == 0u) continue;
                                    for (unsigned axis = 0u; axis < 3u;
                                         ++axis) {
                                        placement.contacts[contact][axis] =
                                            std::clamp(
                                                placement.contacts[contact]
                                                    [axis] +
                                                contactSuggestion.deltaMetres
                                                    [contact][axis],
                                                -1.0f, 1.0f);
                                    }
                                }
                                const bool persisted =
                                    persistCharacterTuning(entry->id, edit);
                                changed |= persisted;
                                if (persisted) {
                                    setStatus(
                                        "Applied the measured contact starting point. Rerun the exact context to verify every pose.",
                                        AppTheme::good());
                                }
                            }
                            ui::SpeakFocusedItem(
                                "Apply measured offsets",
                                spokenProposal.c_str(),
                                "Adds the displayed average target corrections to this vehicle only, records one reversible Fit edit, and invalidates prior exact evidence until retested. It does not change authored animation clips.");
                        }
                    }
                    const std::string contactKey =
                        std::string(entry->id) + "#" +
                        std::to_string(context);
                    int &selectedContact =
                        g_characterSelectedContacts[contactKey];
                    selectedContact = std::clamp(
                        selectedContact, 0,
                        static_cast<int>(MDKR_MODERN_CHARACTER_CONTACTS) - 1);
                    const float contactWidth =
                        ImGui::GetContentRegionAvail().x;
                    const int contactColumns = contactWidth >= 620.0f
                        ? 4 : contactWidth >= 300.0f ? 2 : 1;
                    if (ImGui::BeginTable(
                            "##contact-target-selection", contactColumns,
                            ImGuiTableFlags_SizingStretchSame)) {
                        for (unsigned contact = 0u;
                             contact < MDKR_MODERN_CHARACTER_CONTACTS;
                             ++contact) {
                            ImGui::TableNextColumn();
                            const std::string selectLabel =
                                std::string(contactLabels[contact]) +
                                "##contact-select";
                            if (ImGui::RadioButton(
                                    selectLabel.c_str(), &selectedContact,
                                    static_cast<int>(contact))) {
                                selectedContact = static_cast<int>(contact);
                            }
                            ui::SpeakFocusedItem(
                                contactLabels[contact],
                                selectedContact == static_cast<int>(contact)
                                    ? "selected" : "not selected",
                                "Chooses the contact target edited by the spatial control and numeric fields.");
                        }
                        ImGui::EndTable();
                    }
                    int &contactView =
                        g_characterContactSpatialViews[contactKey];
                    const CharacterSpatialPlane contactPlane =
                        drawCharacterSpatialPlaneSelector(
                            "contact-plane", contactView);
                    CharacterSpatialEditResult contactSpatial =
                        drawCharacterSpatialPad(
                            "##contact-target-pad",
                            "Hand and foot target adjustment control",
                            placement.contacts,
                            MDKR_MODERN_CHARACTER_CONTACTS,
                            static_cast<unsigned>(selectedContact),
                            contactPlane, 0.15f, 1.0f, 0.005f,
                            "zero = engine target",
                            contactLabels);
                    if (contactSpatial.commit) {
                        changed |= persistCharacterTuning(entry->id, edit);
                    }
                    for (unsigned contact = 0u;
                         contact < MDKR_MODERN_CHARACTER_CONTACTS; ++contact) {
                        ImGui::PushID(static_cast<int>(contact));
                        (void)ImGui::DragFloat3(
                            contactLabels[contact],
                            placement.contacts[contact], 0.005f,
                            -1.0f, 1.0f, "%.3f m",
                            ImGuiSliderFlags_AlwaysClamp);
                        if (ImGui::IsItemDeactivatedAfterEdit()) {
                            changed |= persistCharacterTuning(entry->id, edit);
                        }
                        ImGui::PopID();
                    }
                    if (ImGui::Button("Reset contact targets")) {
                        std::memset(placement.contacts, 0,
                                    sizeof(placement.contacts));
                        changed |= persistCharacterTuning(entry->id, edit);
                    }
                    ImGui::TreePop();
                }
                if (!contactReady) {
                    ImGui::EndDisabled();
                    ui::TextSubtleWrapped(
                        "Contact controls require a complete, reviewed source-v4/v5 humanoid map.");
                }
            }
            if (context != MDKR_CHARACTER_CONTEXT_SELECT &&
                ImGui::TreeNode("Copy this vehicle fit")) {
                ui::TextSubtleWrapped(
                    "Copies size, position, rotation, and all four contact adjustments to one other qualified vehicle. The destination's prior fit remains available through Undo Fit; select placement is never included.");
                for (unsigned destination = MDKR_CHARACTER_CONTEXT_CAR;
                     destination < MDKR_CHARACTER_CONTEXT_COUNT;
                     ++destination) {
                    if (destination == context ||
                        (entry->vehicle_mask &
                         (1u << (destination - 1u))) == 0u) continue;
                    const std::string copyLabel = std::string("Copy to ") +
                        contextNames[destination];
                    if (ImGui::Button(copyLabel.c_str())) {
                        edit.context[destination] = placement;
                        changed |= persistCharacterTuning(entry->id, edit);
                    }
                    ui::SpeakFocusedItem(
                        copyLabel.c_str(), nullptr,
                        "Replaces only the named vehicle's fit and contact adjustments; select placement and other vehicles stay unchanged.");
                }
                ImGui::TreePop();
            }
            /* Re-resolve after every fine-tuning control. Any accepted edit
             * invalidates the evidence by signature, including edits made in
             * this same frame. */
            fitEvidence = currentCharacterFitEvidenceSnapshot(
                entry, edit, previewContext);
            ImGui::SeparatorText("4. Inspect exact evidence");
            if (!fitEvidence.current) {
                ImGui::TextDisabled(
                    "No exact evidence matches the current source and fit. Rerun this context before approval.");
            } else if (characterPreviewFitDiagnosticsValid(
                           fitEvidence.result)) {
                drawCharacterFitDiagnostics(fitEvidence.result, true);
                const std::string overlayKey = std::string(entry->id) +
                    "#" + std::to_string(context);
                drawCharacterFitOverlay(
                    fitEvidence.result,
                    g_characterFitSpatialViews[overlayKey],
                    true);
                drawCharacterFitReference(
                    entry, fitEvidence.sourceSha256,
                    fitEvidence.fitSha256, previewContext,
                    g_characterFitSpatialViews[overlayKey], true);
                if (fitEvidence.fromDurableStore &&
                    std::getenv("MDKR_APP_UI_TRACE") != nullptr) {
                    const std::string traceKey = std::string(entry->id) + ":" +
                        std::to_string(static_cast<unsigned>(previewContext));
                    if (g_characterFitEvidenceTraceContexts.insert(
                            traceKey).second) {
                        std::fprintf(
                            stderr,
                            "[app-ui] character-fit-evidence durable=1 package=%s context=%u players=%u fit=%d fitAnchorUm=%lld,%lld,%lld fitBoundsYUm=%lld,%lld fitForwardMilli=%d,%d,%d\n",
                            entry->id,
                            static_cast<unsigned>(previewContext),
                            fitEvidence.players,
                            fitEvidence.result.fit_diagnostics_valid ? 1 : 0,
                            static_cast<long long>(
                                fitEvidence.result.fit_anchor_micrometres[0]),
                            static_cast<long long>(
                                fitEvidence.result.fit_anchor_micrometres[1]),
                            static_cast<long long>(
                                fitEvidence.result.fit_anchor_micrometres[2]),
                            static_cast<long long>(
                                fitEvidence.result.fit_bounds_min_micrometres[1]),
                            static_cast<long long>(
                                fitEvidence.result.fit_bounds_max_micrometres[1]),
                            fitEvidence.result.fit_forward_milli[0],
                            fitEvidence.result.fit_forward_milli[1],
                            fitEvidence.result.fit_forward_milli[2]);
                    }
                }
            } else {
                ImGui::TextColored(
                    AppTheme::bad(),
                    "Last exact test returned invalid fit measurements.");
            }
            bool contactQualityMeasured = false;
            bool contactsWithinGuide = true;
            bool contactStabilityMeasured = false;
            bool contactsStable = true;
            unsigned long long contactStabilityMaximum = 0u;
            unsigned long long contactStabilityObservations = 0u;
            constexpr unsigned long long
                kContactStabilityGuideMicrometres = 2000u;
            if (fitEvidence.current &&
                context != MDKR_CHARACTER_CONTEXT_SELECT) {
                unsigned long long contactSolves = 0u;
                unsigned long long contactMaximum = 0u;
                if (completeSceneReview) {
                    for (unsigned sceneIndex = 0u;
                         sceneIndex < motionSceneCount; ++sceneIndex) {
                        const CharacterMotionReviewSessionResult *sceneReview =
                            motionReviews[sceneIndex];
                        for (unsigned sampleIndex = 0u;
                             sampleIndex < sceneReview->result.sample_count;
                             ++sampleIndex) {
                            const MdkrCharacterPreviewResult &sample =
                                sceneReview->result.samples[sampleIndex];
                            contactSolves += sample.contact_solves;
                            contactMaximum = std::max(
                                contactMaximum,
                                sample.contact_error_max_micrometres);
                            if (sample.contact_witness_mask != 0u) {
                                contactQualityMeasured = true;
                                for (unsigned contact = 0u;
                                     contact < MDKR_CHARACTER_PREVIEW_CONTACTS;
                                     ++contact) {
                                    const uint64_t guide =
                                        contact < 2u ? 25000u : 40000u;
                                    if (sample
                                            .contact_witness_error_micrometres
                                                [contact] > guide) {
                                        contactsWithinGuide = false;
                                    }
                                }
                            }
                            for (unsigned contact = 0u;
                                 contact < MDKR_CHARACTER_PREVIEW_CONTACTS;
                                 ++contact) {
                                if ((sceneReview->result
                                         .contact_stability_mask[sampleIndex] &
                                     (1u << contact)) == 0u) continue;
                                contactStabilityMeasured = true;
                                const unsigned long long observations =
                                    sceneReview->result
                                        .contact_stability_observations
                                            [sampleIndex][contact];
                                contactStabilityObservations =
                                    observations >
                                            UINT64_MAX -
                                                contactStabilityObservations
                                        ? UINT64_MAX
                                        : contactStabilityObservations +
                                              observations;
                                contactStabilityMaximum = std::max(
                                    contactStabilityMaximum,
                                    sceneReview->result
                                        .contact_stability_max_step_micrometres
                                            [sampleIndex][contact]);
                            }
                        }
                    }
                    contactsStable = !contactStabilityMeasured ||
                        contactStabilityMaximum <=
                            kContactStabilityGuideMicrometres;
                } else {
                    contactSolves = fitEvidence.result.contact_solves;
                    contactMaximum =
                        fitEvidence.result.contact_error_max_micrometres;
                }
                if (!completeSceneReview && contactSolves != 0u) {
                    contactQualityMeasured = true;
                    for (unsigned contact = 0u;
                         contact < MDKR_CHARACTER_PREVIEW_CONTACTS; ++contact) {
                        const uint64_t guide = contact < 2u ? 25000u : 40000u;
                        const uint64_t error = fitEvidence.result
                            .contact_witness_error_micrometres[contact];
                        if (error > guide) contactsWithinGuide = false;
                    }
                }
                if (contactQualityMeasured) {
                    ImGui::Text(
                        completeSceneReview
                            ? "Complete motion review: %.2f mm worst contact across %llu solves"
                            : "Last exact test: %.2f mm maximum across %llu solves",
                        contactMaximum / 1000.0,
                        static_cast<unsigned long long>(contactSolves));
                    ImGui::TextColored(
                        contactsWithinGuide ? AppTheme::good()
                                            : AppTheme::accent(),
                        contactsWithinGuide
                            ? "Contact guide met: hands <= 25 mm and feet <= 40 mm"
                            : "Contact tuning required: a hand exceeds 25 mm or a foot exceeds 40 mm");
                } else {
                    ImGui::TextDisabled(
                        completeSceneReview
                            ? "Complete motion review: no procedural contacts (authored clip or solver locked)"
                            : "Last exact test: no procedural contacts (authored clip or solver locked)");
                }
                if (contactStabilityMeasured) {
                    ImGui::Text(
                        "Residual stability: %.2f mm maximum frame-to-frame change across %llu comparisons",
                        contactStabilityMaximum / 1000.0,
                        static_cast<unsigned long long>(
                            contactStabilityObservations));
                    ImGui::TextColored(
                        contactsStable ? AppTheme::good()
                                       : AppTheme::accent(),
                        contactsStable
                            ? "Contact stability guide met: residual drift <= 2 mm"
                            : "Contact stability needs review: residual drift exceeds 2 mm");
                    ui::TextSubtleWrapped(
                        "Residual drift measures consecutive changes in endpoint-minus-target while each reviewed pose is held. It does not count ordinary character or vehicle movement.");
                } else if (contactQualityMeasured) {
                    ImGui::TextDisabled(
                        "Run the complete motion review to measure contact stability across settled frames.");
                }
            }
            const bool representativeMotionReady =
                completeSceneReview;
            const bool exactReviewContract = fitEvidence.current &&
                representativeMotionReady &&
                fitEvidence.result.version ==
                    MDKR_CHARACTER_PREVIEW_RESULT_VERSION &&
                fitEvidence.result.started &&
                fitEvidence.result.warmup_complete &&
                fitEvidence.result.replacement_draws != 0u &&
                fitEvidence.result.fit_diagnostics_valid != 0 &&
                fitEvidence.result.camera_projection_valid != 0 &&
                fitEvidence.result.opaque_visibility_valid != 0 &&
                (context == MDKR_CHARACTER_CONTEXT_SELECT ||
                 fitEvidence.result.vehicle_surface_valid != 0) &&
                characterPreviewFitDiagnosticsValid(fitEvidence.result) &&
                characterPreviewCameraProjectionValid(fitEvidence.result) &&
                characterPreviewVehicleSurfaceValid(fitEvidence.result) &&
                characterPreviewOpaqueVisibilityValid(fitEvidence.result) &&
                characterPreviewContactDiagnosticsValid(fitEvidence.result);
            CharacterWorkshopFitAssessment reviewAssessment;
            if (exactReviewContract) {
                reviewAssessment = CharacterWorkshop_assessFit(
                    characterWorkshopFitMeasurement(
                        fitEvidence.result,
                        context != MDKR_CHARACTER_CONTEXT_SELECT));
            }
            const bool advisoryFitWarning = exactReviewContract &&
                (reviewAssessment.datum !=
                     CharacterWorkshopQualitySeverity::Nominal ||
                 reviewAssessment.facing !=
                     CharacterWorkshopQualitySeverity::Nominal ||
                 reviewAssessment.proportions !=
                     CharacterWorkshopQualitySeverity::Nominal);
            bool cameraWarning = exactReviewContract &&
                characterPreviewCameraReviewFlags(fitEvidence.result) != 0u;
            bool surfaceWarning = exactReviewContract &&
                context != MDKR_CHARACTER_CONTEXT_SELECT &&
                (fitEvidence.result.vehicle_surface_crossing_pairs != 0u ||
                 fitEvidence.result.vehicle_volume_qualified == 0 ||
                 fitEvidence.result
                         .vehicle_containment_inside_samples != 0u);
            bool attachmentVisibilityWarning = exactReviewContract &&
                characterPreviewAttachmentVisibilityNeedsReview(
                    fitEvidence.result);
            CharacterWorkshopFitReviewFacts reviewFacts;
            reviewFacts.exactContract = exactReviewContract;
            reviewFacts.opaqueVisibilityQualified =
                fitEvidence.result.opaque_visibility_qualified != 0;
            reviewFacts.isolatedVisibleTiles =
                fitEvidence.result.opaque_visibility_isolated_tiles;
            reviewFacts.sceneVisibleTiles =
                fitEvidence.result.opaque_visibility_scene_tiles;
            if (exactReviewContract && completeSceneReview) {
                bool unqualifiedVisibility = false;
                bool invisibleOpaqueState = false;
                uint64_t minimumRatioNumerator = 0u;
                uint64_t minimumRatioDenominator = 0u;
                for (unsigned sceneIndex = 0u;
                     sceneIndex < motionSceneCount; ++sceneIndex) {
                    const CharacterMotionReviewSessionResult *sceneReview =
                        motionReviews[sceneIndex];
                    for (unsigned sampleIndex = 0u;
                         sampleIndex < sceneReview->result.sample_count;
                         ++sampleIndex) {
                        const MdkrCharacterPreviewResult &sample =
                            sceneReview->result.samples[sampleIndex];
                        cameraWarning |=
                            characterPreviewCameraReviewFlags(sample) != 0u;
                        if (context != MDKR_CHARACTER_CONTEXT_SELECT) {
                            surfaceWarning |=
                                sample.vehicle_surface_crossing_pairs != 0u ||
                                sample.vehicle_volume_qualified == 0 ||
                                sample.vehicle_containment_inside_samples != 0u;
                            attachmentVisibilityWarning |=
                                characterPreviewAttachmentVisibilityNeedsReview(
                                    sample);
                        }
                        if (!sample.opaque_visibility_qualified) {
                            unqualifiedVisibility = true;
                        } else if (
                            sample.opaque_visibility_isolated_tiles == 0u) {
                            invisibleOpaqueState = true;
                        } else if (
                            minimumRatioDenominator == 0u ||
                            static_cast<uint64_t>(
                                sample.opaque_visibility_scene_tiles) *
                                    minimumRatioDenominator <
                                minimumRatioNumerator *
                                    sample.opaque_visibility_isolated_tiles) {
                            minimumRatioNumerator =
                                sample.opaque_visibility_scene_tiles;
                            minimumRatioDenominator =
                                sample.opaque_visibility_isolated_tiles;
                        }
                    }
                }
                if (invisibleOpaqueState) {
                    reviewFacts.opaqueVisibilityQualified = true;
                    reviewFacts.isolatedVisibleTiles = 0u;
                    reviewFacts.sceneVisibleTiles = 0u;
                } else if (unqualifiedVisibility) {
                    reviewFacts.opaqueVisibilityQualified = false;
                    reviewFacts.isolatedVisibleTiles = 0u;
                    reviewFacts.sceneVisibleTiles = 0u;
                } else if (minimumRatioDenominator != 0u) {
                    reviewFacts.opaqueVisibilityQualified = true;
                    reviewFacts.isolatedVisibleTiles =
                        static_cast<unsigned>(minimumRatioDenominator);
                    reviewFacts.sceneVisibleTiles =
                        static_cast<unsigned>(minimumRatioNumerator);
                }
            }
            reviewFacts.advisoryFitWarning = advisoryFitWarning;
            reviewFacts.cameraWarning = cameraWarning;
            reviewFacts.surfaceWarning = surfaceWarning;
            reviewFacts.attachmentVisibilityWarning =
                attachmentVisibilityWarning;
            CharacterWorkshopFitReviewDecision reviewDecision =
                CharacterWorkshop_reviewFit(reviewFacts);
            const bool visibilityBlocksReview =
                reviewDecision.visibilityBlocksReview;
            const bool reviewWarnings = reviewDecision.warnings;
            ImGui::SeparatorText("5. Review this context");
            const bool fitReviewed = characterFitReviewed(
                entry, edit, context);
            const bool recordedContactException =
                characterFitContactException(entry, edit, context);
            ImGui::TextColored(
                fitReviewed ? AppTheme::good() : AppTheme::accent(),
                fitReviewed
                    ? recordedContactException
                        ? reviewWarnings
                            ? "Fit reviewed with explicit contact and exact-scene warning acknowledgements"
                            : "Fit reviewed with an explicit contact exception for this exact source and tuning"
                        : reviewWarnings
                            ? "Fit reviewed after explicit exact-scene warning acknowledgement"
                            : "Fit reviewed for this exact source and tuning"
                    : "Fit review required for current source or tuning");
            if (!fitReviewed) {
                uint32_t &pendingExceptions =
                    g_characterPendingContactExceptions[entry->id];
                const bool contactExceptionRequired =
                    (contactQualityMeasured && !contactsWithinGuide) ||
                    (contactStabilityMeasured && !contactsStable);
                if (!exactReviewContract || !contactExceptionRequired) {
                    pendingExceptions &= ~(1u << context);
                }
                bool approveException =
                    (pendingExceptions & (1u << context)) != 0u;
                const bool exceptionRequired = fitEvidence.current &&
                    contactExceptionRequired;
                if (exceptionRequired) {
                    ImGui::TextColored(
                        AppTheme::accent(),
                        "The measured contact residual or stability guide is not met. Tune and rerun, or explicitly approve this unusual-anatomy/contact exception.");
                    if (ImGui::Checkbox(
                            "I inspected the exact scenes and approve this contact-quality exception",
                            &approveException)) {
                        if (approveException) {
                            pendingExceptions |= 1u << context;
                        } else {
                            pendingExceptions &= ~(1u << context);
                        }
                    }
                    ui::SpeakFocusedItem(
                        "Approve contact exception",
                        approveException ? "Checked" : "Not checked",
                        "Records an explicit source-and-fit-bound exception when this context is marked reviewed. It does not change contact targets or claim the numeric guide was met.");
                }
                uint32_t &pendingSceneReviews =
                    g_characterPendingSceneReviews[entry->id];
                if (!exactReviewContract || visibilityBlocksReview) {
                    pendingSceneReviews &= ~(1u << context);
                }
                bool sceneReviewed =
                    (pendingSceneReviews & (1u << context)) != 0u;
                if (!exactReviewContract) {
                    ImGui::TextColored(
                        AppTheme::bad(),
                        "A complete warmed renderer fit and visibility witness is required before review.");
                    ui::TextSubtleWrapped(
                        !representativeMotionReady
                            ? context == MDKR_CHARACTER_CONTEXT_SELECT
                                ? "Run Complete semantic motion check above. Select approval requires fresh source-and-fit-bound evidence from idle, hover, and confirm—not one favourable static frame."
                                : "Run Complete motion and scene check above. Vehicle approval requires fresh source-and-fit-bound evidence from every race semantic on all five qualified courses—not one favourable parked frame."
                            : "Run this exact context again. Approval stays unavailable when fit, camera, vehicle-surface, contact, or opaque-depth evidence is incomplete or invalid.");
                } else if (visibilityBlocksReview) {
                    ImGui::TextColored(
                        AppTheme::bad(),
                        "The isolated replay rendered no opaque or alpha-tested character regions.");
                    ui::TextSubtleWrapped(
                        "This is a concrete invisible-character failure, so fit approval is blocked. Correct camera placement, facing, culling, or alpha masking and rerun the context. Transparency-only characters remain reviewable through the visual acknowledgement path.");
                } else {
                    if (reviewWarnings) {
                        ImGui::TextColored(
                            AppTheme::accent(),
                            "One or more measured bands need judgement; the highlighted diagnostics above remain advisory for unusual anatomy and intentional styling.");
                    }
                    const char *sceneReviewLabel = reviewWarnings
                        ? context == MDKR_CHARACTER_CONTEXT_SELECT
                            ? "I inspected the exact composed scene and accept the highlighted fit, clipping, or visibility warnings"
                            : "I inspected all 55 exact race-and-scene samples and accept the highlighted fit, clipping, or visibility warnings"
                        : context == MDKR_CHARACTER_CONTEXT_SELECT
                            ? "I inspected idle, hover, and confirm for placement, silhouette, and visibility"
                            : "I inspected all 55 exact race-and-scene samples for placement, silhouette, vehicle occlusion, and attachments";
                    if (ImGui::Checkbox(sceneReviewLabel, &sceneReviewed)) {
                        if (sceneReviewed) {
                            pendingSceneReviews |= 1u << context;
                        } else {
                            pendingSceneReviews &= ~(1u << context);
                        }
                    }
                    ui::SpeakFocusedItem(
                        "Exact composed-scene review",
                        sceneReviewed ? "Checked" : "Not checked",
                        reviewWarnings
                            ? "Confirms visual inspection of the current exact review evidence and explicit acceptance of its highlighted advisory warnings. It does not waive a fully invisible opaque character."
                            : "Confirms visual inspection of the current exact review evidence, including silhouette, attachments, and occlusion that numeric fit bounds cannot prove.");
                }
                reviewFacts.sceneReviewed = sceneReviewed;
                reviewFacts.contactExceptionRequired = exceptionRequired;
                reviewFacts.contactExceptionApproved = approveException;
                reviewDecision = CharacterWorkshop_reviewFit(reviewFacts);
                const bool reviewReady = reviewDecision.ready;
                if (std::getenv("MDKR_APP_UI_TRACE") != nullptr) {
                    const std::string traceKey = std::string(entry->id) + ":" +
                        std::to_string(context) + ":" +
                        (exceptionRequired ? "exception" : "guide") + ":" +
                        (approveException ? "approved" : "open");
                    static std::set<std::string> tracedContactReviewStates;
                    if (tracedContactReviewStates.insert(traceKey).second) {
                        std::fprintf(
                            stderr,
                            "[app-ui] character-contact-review package=%s context=%u measured=%d guide-met=%d stability-measured=%d stability-guide-met=%d stability-max-um=%llu exception-required=%d exception-approved=%d review-ready=%d exact-contract=%d visibility-block=%d scene-reviewed=%d warnings=%d\n",
                            entry->id, context,
                            contactQualityMeasured ? 1 : 0,
                            contactsWithinGuide ? 1 : 0,
                            contactStabilityMeasured ? 1 : 0,
                            contactsStable ? 1 : 0,
                            static_cast<unsigned long long>(
                                contactStabilityMaximum),
                            exceptionRequired ? 1 : 0,
                            approveException ? 1 : 0,
                            reviewReady ? 1 : 0,
                            exactReviewContract ? 1 : 0,
                            visibilityBlocksReview ? 1 : 0,
                            sceneReviewed ? 1 : 0,
                            reviewWarnings ? 1 : 0);
                    }
                }
                if (!reviewReady) ImGui::BeginDisabled();
                const std::string reviewLabel = std::string("Mark ") +
                    contextNames[context] + " fit reviewed";
                if (ImGui::Button(reviewLabel.c_str()) &&
                    reviewReady) {
                    const bool persisted = persistCharacterFitReview(
                        entry, edit, context, exceptionRequired);
                    changed |= persisted;
                    if (persisted) {
                        pendingExceptions &= ~(1u << context);
                        pendingSceneReviews &= ~(1u << context);
                    }
                }
                if (!reviewReady) ImGui::EndDisabled();
                ui::SpeakFocusedItem(
                    reviewLabel.c_str(),
                    !exactReviewContract
                        ? "Run and complete the matching exact renderer fit and visibility test first."
                        : visibilityBlocksReview
                            ? "Correct the invisible-character failure and rerun this exact context first."
                        : !sceneReviewed
                            ? "Inspect and acknowledge the exact composed scene first."
                        : exceptionRequired && !approveException
                            ? "Inspect and explicitly approve the over-limit contact-quality exception first."
                            : nullptr,
                    "Saves review only for the current package source and fit values after exact composed-scene inspection, including whether an over-limit contact residual or stability exception was explicitly approved.");
            } else {
                const std::string reopenLabel = std::string("Reopen ") +
                    contextNames[context] + " fit review";
                if (ImGui::Button(reopenLabel.c_str())) {
                    changed |= clearCharacterFitReview(entry, context);
                }
                ui::SpeakFocusedItem(
                    reopenLabel.c_str(), nullptr,
                    "Clears this context's approval without changing its fit values.");
            }
            ImGui::PopID();
            ImGui::EndTabItem();
        }
        ImGui::EndTabBar();
    }

    if (ImGui::TreeNode("Advanced whole-character correction")) {
        (void)ImGui::DragFloat3("Overall position", edit.offset, 0.01f,
                                -500.0f, 500.0f, "%.3f",
                                ImGuiSliderFlags_AlwaysClamp);
        if (ImGui::IsItemDeactivatedAfterEdit()) {
            changed |= persistCharacterTuning(entry->id, edit);
        }
        (void)ImGui::DragFloat3("Overall rotation", edit.rotation, 0.5f,
                                -180.0f, 180.0f, "%.1f deg",
                                ImGuiSliderFlags_AlwaysClamp);
        if (ImGui::IsItemDeactivatedAfterEdit()) {
            changed |= persistCharacterTuning(entry->id, edit);
        }
        ImGui::TreePop();
    }

    ImGui::SeparatorText("Motion");
    (void)ImGui::SliderFloat("Animation speed", &edit.animationSpeed,
                             0.05f, 4.0f, "%.2fx",
                             ImGuiSliderFlags_AlwaysClamp);
    if (ImGui::IsItemDeactivatedAfterEdit()) {
        changed |= persistCharacterTuning(entry->id, edit);
    }
    if (ImGui::Button("Reset fit and motion")) {
        const float retainedLodBias = edit.lodBias;
        edit = CharacterTuningEdit{};
        edit.loaded = true;
        edit.lodBias = retainedLodBias;
        edit.vehicleMask = entry->vehicle_mask;
        changed |= persistCharacterTuning(entry->id, edit);
    }
    finishCharacterHistory(entry, history);
    return changed;
}

const char *characterPerformanceTier(
    const MdkrModernCharacterEntry *entry) {
    const MdkrModernCharacterStats &stats = entry->stats;
    const uint32_t triangles = entry->lod_triangles[0] != 0u
        ? entry->lod_triangles[0] : stats.triangles;
    const uint32_t vertices = entry->lod_vertices[0] != 0u
        ? entry->lod_vertices[0] : stats.vertices;
    const uint32_t primitives = entry->lod_primitives[0] != 0u
        ? entry->lod_primitives[0] : stats.primitives;
    if (stats.textures != 0u && stats.decoded_texture_bytes == 0u) {
        return "Recompile to measure";
    }
    if (triangles <= 15000u && vertices <= 20000u &&
        primitives <= 4u && stats.materials <= 4u &&
        stats.joints <= 64u && stats.textures <= 8u &&
        stats.decoded_texture_bytes <= 64u * 1024u * 1024u) return "Excellent";
    if (triangles <= 30000u && vertices <= 40000u &&
        primitives <= 8u && stats.materials <= 8u &&
        stats.joints <= 96u && stats.textures <= 12u &&
        stats.decoded_texture_bytes <= 128u * 1024u * 1024u) return "Good";
    if (triangles <= 60000u && vertices <= 70000u &&
        primitives <= 12u && stats.materials <= 12u &&
        stats.joints <= 128u && stats.textures <= 16u &&
        stats.decoded_texture_bytes <= 256u * 1024u * 1024u) return "Heavy";
    return "Very heavy";
}

void drawCharacterPerformanceSourceHandoff(
    const MdkrModernCharacterEntry *entry) {
    const bool sourceInventoryReadable = g_characterRawDraftsWritable;
    const std::vector<const CharacterRawDraftStore::Draft *> sourceDrafts =
        sourceInventoryReadable
            ? CharacterRawDraftStore::findAllByPackageId(
                  g_characterRawDrafts, entry->id)
            : std::vector<const CharacterRawDraftStore::Draft *>{};
    const CharacterRawDraftStore::Draft *chosenDraft = nullptr;
    if (sourceDrafts.size() == 1u) {
        chosenDraft = sourceDrafts.front();
        ui::TextSubtleWrapped(
            "Only same-ID source draft: %s · %s",
            chosenDraft->displayName.empty()
                ? "Unnamed raw draft"
                : chosenDraft->displayName.c_str(),
            chosenDraft->modelPath.c_str());
    } else if (sourceDrafts.size() > 1u) {
        std::string &selectedId =
            g_characterPerformanceRawDraftSelections[entry->id];
        const auto selected = std::find_if(
            sourceDrafts.begin(), sourceDrafts.end(),
            [&selectedId](const CharacterRawDraftStore::Draft *draft) {
                return draft != nullptr && draft->id == selectedId;
            });
        if (selected == sourceDrafts.end()) selectedId.clear();
        const auto chosen = std::find_if(
            sourceDrafts.begin(), sourceDrafts.end(),
            [&selectedId](const CharacterRawDraftStore::Draft *draft) {
                return draft != nullptr && draft->id == selectedId;
            });
        chosenDraft = chosen != sourceDrafts.end() ? *chosen : nullptr;
        const std::string preview = chosenDraft != nullptr
            ? (chosenDraft->displayName.empty()
                   ? chosenDraft->modelPath
                   : chosenDraft->displayName + " — " +
                         chosenDraft->modelPath)
            : "Choose the exact source draft";
        ImGui::SetNextItemWidth(-1.0f);
        const bool sourceListOpen = beginCharacterLiteralCombo(
            "Source draft for LOD copy", preview.c_str());
        ui::SpeakFocusedItem(
            "Source draft for LOD copy",
            chosenDraft != nullptr ? preview.c_str() : "Not chosen",
            "More than one retained raw draft uses this package ID. Choose the exact model source; the Workshop never guesses by recency.");
        if (sourceListOpen) {
            for (const CharacterRawDraftStore::Draft *draft : sourceDrafts) {
                if (draft == nullptr) continue;
                const std::string visible =
                    (draft->displayName.empty() ? "Unnamed raw draft"
                                                : draft->displayName) +
                    " — " + draft->modelPath + " [" + draft->id + "]";
                if (drawCharacterLiteralChoice(
                        visible.c_str(), visible.c_str(), draft->id == selectedId)) {
                    selectedId = draft->id;
                    chosenDraft = draft;
                }
                ui::SpeakFocusedItem(
                    draft->displayName.empty()
                        ? draft->modelPath.c_str()
                        : draft->displayName.c_str(),
                    draft->id == selectedId ? "selected" : "available",
                    draft->modelPath.c_str());
            }
            ImGui::EndCombo();
        }
        ui::TextSubtleWrapped(
            "%zu retained drafts share this package ID. An explicit source choice is required because their package fingerprints cannot safely identify the original model draft.",
            sourceDrafts.size());
    }

    const char *smokeAction = std::getenv(
        "MDKR_APP_SMOKE_PERFORMANCE_SOURCE_ACTION");
    const char *smokeToken = std::getenv(
        "MDKR_APP_SMOKE_PERFORMANCE_SOURCE_ACTION_TOKEN");
    const bool smokeOpen =
        !g_characterPerformanceRawDraftSmokeActionApplied &&
        smokeAction != nullptr && smokeToken != nullptr &&
        std::strcmp(smokeAction, "open-unique") == 0 &&
        std::strcmp(
            smokeToken, "mdkr64-app-performance-source-v1") == 0;
    if (smokeOpen) g_characterPerformanceRawDraftSmokeActionApplied = true;
    const bool canOpen = chosenDraft != nullptr &&
        (sourceDrafts.size() == 1u ||
         !g_characterPerformanceRawDraftSelections[entry->id].empty());
    if (!canOpen) ImGui::BeginDisabled();
    const bool requestedOpen = ImGui::Button(
        "Open chosen source draft and create LOD copy",
        ui::kBtnFullWidth()) || smokeOpen;
    if (requestedOpen && canOpen) {
        const std::string chosenId = chosenDraft->id;
        const bool opened = activateCharacterRawDraft(chosenId);
        setStatus(
            opened
                ? "Same-ID raw source opened. Verify its model fingerprint, then create a separate LOD copy in Performance geometry."
                : "The chosen raw source could not be opened; no draft or installed character changed.",
            opened ? AppTheme::good() : AppTheme::bad());
        if (smokeOpen || std::getenv("MDKR_APP_UI_TRACE") != nullptr) {
            std::fprintf(
                stderr,
                "[app-ui] character-performance-source-handoff package=%s matches=%zu selected=%s applied=%d ambiguity=%s\n",
                entry->id, sourceDrafts.size(), chosenId.c_str(),
                opened ? 1 : 0,
                sourceDrafts.size() > 1u ? "explicit" : "unique");
        }
    } else if (smokeOpen) {
        std::fprintf(
            stderr,
            "[app-ui] character-performance-source-handoff package=%s matches=%zu selected=- applied=0 ambiguity=%s\n",
            entry->id, sourceDrafts.size(),
            !sourceInventoryReadable ? "unavailable"
            : sourceDrafts.size() > 1u ? "unresolved" : "missing");
    }
    ui::SpeakFocusedItem(
        "Open chosen source draft and create LOD copy",
        canOpen ? "ready" : !sourceInventoryReadable
            ? "Raw draft inventory is unavailable"
            : sourceDrafts.empty()
            ? "No matching retained source draft"
            : "Choose the exact source draft first",
        "Opens only the chosen resumable raw source. The installed character and original GLB remain unchanged; LOD generation requires a new exclusive destination and a complete review.");
    if (!canOpen) ImGui::EndDisabled();
    if (sourceInventoryReadable && !sourceDrafts.empty()) {
        ui::TextSubtleWrapped(
            "Package ID is a safe routing hint, not proof that a raw GLB built the installed revision. Verify the model path and fingerprint after opening; no geometry is generated or installed by this handoff.");
    }
    if (!sourceInventoryReadable) {
        ImGui::TextColored(
            AppTheme::bad(),
            "Raw source handoff is unavailable because the local draft inventory failed validation. Repair or preserve that inventory before authoring another source; no draft was guessed or overwritten.");
    } else if (sourceDrafts.empty()) {
        ui::TextSubtleWrapped(
            "No retained raw source draft has this exact package ID. Reopen the original GLB to start a separate resumable draft; the installed package cannot be reverse-converted into an authoring source.");
        if (filedialog::isAvailable()) {
            if (ImGui::Button(
                    "Choose original source GLB...",
                    ui::kBtnFullWidth())) {
                (void)Settings_chooseCharacterSource();
            }
            ui::SpeakFocusedItem(
                "Choose original source GLB",
                nullptr,
                "Chooses a self-contained GLB without changing the installed character or overwriting any source file.");
        }
    }
}

void drawCharacterPerformanceAssembly(
    const MdkrModernCharacterEntry *entry) {
    int &players = g_characterAssemblyPlayers[entry->id];
    if (players < 1 || players > 4) players = 4;
    CharacterTuningEdit &tuning = loadCharacterTuning(0, entry->id);
    CharacterHistoryFrame history = beginCharacterHistory(
        entry, CharacterHistoryTool::Performance);
    const auto restoreTuning = [&](const CharacterTuningEdit &previous) {
        tuning = previous;
        if (g_characterActiveDrafts.find(entry->id) ==
            g_characterActiveDrafts.end()) {
            stageCharacterTuningConfig(entry->id, previous);
        }
    };
    ui::TextSubtleWrapped(
        "Choose a named starting point or tune the two independent facts directly: authored LOD preference and local-player layout. These settings affect presentation cost only; physics, handling, donor authority, and import limits never change.");
    const bool fidelityLimitsOpen = ImGui::TreeNode(
        "Renderer fidelity and current limits");
    ui::SpeakFocusedItem(
        "Renderer fidelity and current limits",
        fidelityLimitsOpen ? "expanded" : "collapsed",
        "Explains which high-fidelity model features are executable and which still require source authoring or future renderer work.");
    if (fidelityLimitsOpen) {
        ui::TextSubtleWrapped(
            "Available now: WebGPU GPU skinning, 32-bit indexed high-detail geometry, PBR-style embedded PNG or KTX2/BasisU materials, authored mip chains, authored animation, up to four authored LODs, and deterministic per-view primitive ordering. KTX2 automatically negotiates BC7, ASTC 4×4, ETC2, or the portable RGBA8 fallback per device. OPAQUE and MASK parts draw first; BLEND parts sort back-to-front from their live posed centroids. Import limits are safety ceilings, not performance recommendations.");
        ui::TextSubtleWrapped(
            "World shadows follow the exact fitted pose in Remastered mode: OPAQUE and MASK parts cast into the mapped cascades, including MASK texture cutouts, and every visible material can receive them. BLEND parts intentionally do not cast a solid shadow. Still review transparent triangles that overlap or intersect inside one primitive, plus transparency ordering against independently rendered vehicle or world surfaces. Camera-aware LOD uses authored levels or the Workshop's recorded offline LOD-copy workflow. Prefer MASK for hair/fur cutouts, separate large transparent layers into primitives, and prove the result in every exact context.");
        ImGui::TreePop();
    }
    const bool hasMultipleLods = entry->stats.lod_levels > 1u;
    CharacterWorkshopPerformanceTarget currentTarget =
        CharacterWorkshop_performanceTarget(players, tuning.lodBias);
    const float targetWidth = ImGui::GetContentRegionAvail().x;
    const int targetColumns = targetWidth >= ui::kPairMinWidth() * 2.0f
        ? 2 : 1;
    if (!hasMultipleLods) ImGui::BeginDisabled();
    if (ImGui::BeginTable(
            "##character-performance-targets", targetColumns,
            ImGuiTableFlags_SizingStretchSame)) {
        for (size_t index = 0u;
             index < static_cast<size_t>(
                         CharacterWorkshopPerformanceTarget::Count);
             ++index) {
            const auto target = static_cast<
                CharacterWorkshopPerformanceTarget>(index);
            const CharacterWorkshopPerformancePreset *preset =
                CharacterWorkshop_performancePreset(target);
            if (preset == nullptr) continue;
            ImGui::TableNextColumn();
            ImGui::PushID(static_cast<int>(index));
            if (ui::CardBegin(
                    "##character-performance-target", AppTheme::surface(),
                    0.0f)) {
                int selected = static_cast<int>(currentTarget);
                if (ImGui::RadioButton(
                        preset->label, &selected,
                        static_cast<int>(target))) {
                    const int oldPlayers = players;
                    const float oldLodBias = tuning.lodBias;
                    players = preset->players;
                    tuning.lodBias = preset->lodBias;
                    if (persistCharacterTuning(entry->id, tuning)) {
                        currentTarget = target;
                        setStatus(
                            "Performance target saved; exact-context evidence must be rerun for this LOD policy.",
                            AppTheme::good());
                    } else {
                        players = oldPlayers;
                        CharacterTuningEdit previous = tuning;
                        previous.lodBias = oldLodBias;
                        restoreTuning(previous);
                    }
                }
                ui::SpeakFocusedItem(
                    preset->label,
                    currentTarget == target ? "selected" : "not selected",
                    preset->description);
                ui::TextSubtleWrapped(preset->description);
                ImGui::TextDisabled(
                    "%dP assembly · local LOD bias %+.0f",
                    preset->players,
                    static_cast<double>(preset->lodBias));
            }
            ui::CardEnd();
            ImGui::PopID();
        }
        ImGui::EndTable();
    }
    if (!hasMultipleLods) ImGui::EndDisabled();
    if (!hasMultipleLods) {
        ui::TextSubtleWrapped(
            "Target profiles are unavailable because this package has one LOD. Create a separate recorded LOD copy from one of its retained source drafts, then rebuild and review it; no slider silently manufactures or replaces installed geometry.");
        drawCharacterPerformanceSourceHandoff(entry);
    }
    if (!hasMultipleLods) ImGui::BeginDisabled();
    const float lodBiasBeforeFrame = tuning.lodBias;
    (void)ImGui::SliderFloat(
        "Authored LOD preference", &tuning.lodBias, -3.0f, 3.0f,
        "%+.0f bands", ImGuiSliderFlags_AlwaysClamp);
    if (ImGui::IsItemActivated()) {
        g_characterPerformanceLodGestureStarts[entry->id] =
            lodBiasBeforeFrame;
    }
    ui::SpeakFocusedItem(
        "Authored LOD preference", nullptr,
        "Shifts the package's authored screen-coverage bands without changing geometry, textures, physics, or import limits.");
    if (ImGui::IsItemDeactivatedAfterEdit()) {
        const auto start = g_characterPerformanceLodGestureStarts.find(
            entry->id);
        CharacterTuningEdit previous = tuning;
        previous.lodBias = start !=
                g_characterPerformanceLodGestureStarts.end()
            ? start->second : lodBiasBeforeFrame;
        if (persistCharacterTuning(entry->id, tuning)) {
            setStatus(
                "Custom LOD preference saved; rerun exact-context performance evidence.",
                AppTheme::good());
        } else {
            restoreTuning(previous);
        }
        g_characterPerformanceLodGestureStarts.erase(entry->id);
    } else if (ImGui::IsItemDeactivated()) {
        g_characterPerformanceLodGestureStarts.erase(entry->id);
    }
    if (!hasMultipleLods) ImGui::EndDisabled();
    ImGui::TextDisabled(
        "Package bias %+.1f + local bias %+.1f = %+.1f authored bands",
        static_cast<double>(entry->source_lod_bias),
        static_cast<double>(tuning.lodBias),
        static_cast<double>(entry->source_lod_bias + tuning.lodBias));
    ImGui::TextUnformatted("Local-player assembly");
    for (int option : {1, 2, 3, 4}) {
        if (option != 1) ImGui::SameLine();
        const std::string label = std::to_string(option) +
            (option == 1 ? " player" : " players");
        (void)ImGui::RadioButton(label.c_str(), &players, option);
    }
    uint32_t authoredLodMask = 0u;
    for (uint32_t lod = 0u;
         lod < MDKR_MODERN_CHARACTER_LOD_LEVELS; ++lod) {
        if (entry->lod_primitives[lod] != 0u) authoredLodMask |= 1u << lod;
    }
    CharacterWorkshopLodBand lodBands[MDKR_MODERN_CHARACTER_LOD_LEVELS] = {};
    const size_t lodBandCount = CharacterWorkshop_lodBands(
        entry->source_lod_bias, tuning.lodBias, authoredLodMask, lodBands);
    auto inspectionInsert =
        g_characterLodInspectionHeights.try_emplace(entry->id, 12.0f);
    float &inspectionHeight = inspectionInsert.first->second;
    if (!std::isfinite(inspectionHeight) || inspectionHeight < 0.0f ||
        inspectionHeight > 24.0f) inspectionHeight = 12.0f;
    const uint32_t inspectionLod = CharacterWorkshop_selectLod(
        inspectionHeight, entry->source_lod_bias, tuning.lodBias,
        authoredLodMask);
    const uint32_t safeInspectionLod =
        inspectionLod < MDKR_MODERN_CHARACTER_LOD_LEVELS
            ? inspectionLod : 0u;
    ImGui::SeparatorText("LOD transition inspector");
    ui::TextSubtleWrapped(
        "Scrub the renderer's camera-aware screen coverage policy. The primary runtime path uses the character's calibrated bounds, exact donor-object MVP, and current logical viewport without a vertex walk; unavailable projection evidence falls back visibly to legacy distance selection. This explanation does not move the game camera or alter the saved character.");
    (void)ImGui::SliderFloat(
        "Projected character height", &inspectionHeight, 0.0f, 24.0f,
        "%.1f logical px", ImGuiSliderFlags_AlwaysClamp);
    char inspectionSpeech[192];
    std::snprintf(
        inspectionSpeech, sizeof(inspectionSpeech),
        "At %.1f logical pixels of projected height the exact current policy selects authored LOD %u. This session-only scrubber does not change saved settings",
        static_cast<double>(inspectionHeight), safeInspectionLod);
    ui::SpeakFocusedItem(
        "Projected character height", inspectionSpeech,
        "Direct entry and arrow keys are supported. Coverage bands include package and local bias, clamping, sparse authored-level fallback, and an eight-percent live-camera guard band.");
    ImGui::TextColored(
        AppTheme::good(), "At %.1f logical px: LOD%u · %u triangles · %u vertices",
        static_cast<double>(inspectionHeight), safeInspectionLod,
        entry->lod_triangles[safeInspectionLod],
        entry->lod_vertices[safeInspectionLod]);
    const ImVec2 plotOrigin = ImGui::GetCursorScreenPos();
    const ImVec2 plotSize(
        std::max(1.0f, ImGui::GetContentRegionAvail().x),
        44.0f * AppTheme::uiScale());
    (void)ImGui::Selectable(
        "Exact projected-height LOD bands", false, ImGuiSelectableFlags_None,
        plotSize);
    const bool plotFocused = ImGui::IsItemFocused();
    ui::SpeakFocusedItem(
        "Exact projected-height LOD bands", inspectionSpeech,
        "The exact interval list following this plot is authoritative and keyboard-readable.");
    ImDrawList *lodDraw = ImGui::GetWindowDrawList();
    static const ImU32 lodColours[] = {
        IM_COL32(78, 163, 255, 255), IM_COL32(87, 201, 145, 255),
        IM_COL32(238, 180, 72, 255), IM_COL32(213, 112, 162, 255),
    };
    const ImVec2 plotMaximum(
        plotOrigin.x + plotSize.x, plotOrigin.y + plotSize.y);
    lodDraw->AddRectFilled(
        plotOrigin, plotMaximum, IM_COL32(12, 17, 24, 255), 5.0f);
    for (size_t band = 0u; band < lodBandCount; ++band) {
        const float minimum = std::clamp(
            lodBands[band].minimumProjectedHeight, 0.0f, 24.0f);
        const float maximum =
            std::isinf(lodBands[band].maximumProjectedHeight)
                ? 24.0f
                : std::clamp(
                    lodBands[band].maximumProjectedHeight, 0.0f, 24.0f);
        const float left = plotOrigin.x + plotSize.x * minimum / 24.0f;
        const float right = plotOrigin.x + plotSize.x * maximum / 24.0f;
        lodDraw->AddRectFilled(
            ImVec2(left, plotOrigin.y), ImVec2(right, plotMaximum.y),
            lodColours[lodBands[band].lod]);
        char label[16];
        std::snprintf(label, sizeof(label), "LOD%u", lodBands[band].lod);
        const ImVec2 textSize = ImGui::CalcTextSize(label);
        if (right - left >= textSize.x + 8.0f * AppTheme::uiScale()) {
            lodDraw->AddText(
                ImVec2((left + right - textSize.x) * 0.5f,
                       plotOrigin.y + (plotSize.y - textSize.y) * 0.5f),
                IM_COL32(10, 18, 26, 255), label);
        }
    }
    const float marker = plotOrigin.x +
        plotSize.x * inspectionHeight / 24.0f;
    lodDraw->AddLine(
        ImVec2(marker, plotOrigin.y), ImVec2(marker, plotMaximum.y),
        IM_COL32(255, 255, 255, 255), 3.0f * AppTheme::uiScale());
    lodDraw->AddRect(
        plotOrigin, plotMaximum,
        plotFocused ? ImGui::GetColorU32(ImGuiCol_NavHighlight)
                    : IM_COL32(75, 84, 96, 255),
        5.0f, 0, (plotFocused ? 2.0f : 1.0f) * AppTheme::uiScale());
    const bool compactLodTable = ImGui::GetContentRegionAvail().x < 620.0f;
    bool nonMonotonic = false;
    bool dramaticStep = false;
    uint32_t priorTriangles = 0u;
    for (size_t band = 0u; band < lodBandCount; ++band) {
        const uint32_t triangles = entry->lod_triangles[lodBands[band].lod];
        if (band != 0u) {
            nonMonotonic |= triangles < priorTriangles;
            dramaticStep |= priorTriangles != 0u &&
                static_cast<uint64_t>(priorTriangles) * 4u < triangles;
        }
        priorTriangles = triangles;
    }
    if (compactLodTable) {
        for (size_t band = 0u; band < lodBandCount; ++band) {
            const CharacterWorkshopLodBand &range = lodBands[band];
            if (std::isinf(range.maximumProjectedHeight)) {
                ImGui::BulletText(
                    "%.1f+ px uses LOD%u · %u triangles · %u vertices",
                    static_cast<double>(range.minimumProjectedHeight), range.lod,
                    entry->lod_triangles[range.lod],
                    entry->lod_vertices[range.lod]);
            } else {
                ImGui::BulletText(
                    "%.1f–%.1f px uses LOD%u · %u triangles · %u vertices",
                    static_cast<double>(range.minimumProjectedHeight),
                    static_cast<double>(range.maximumProjectedHeight), range.lod,
                    entry->lod_triangles[range.lod],
                    entry->lod_vertices[range.lod]);
            }
        }
    } else if (ImGui::BeginTable(
                   "##lod-transition-bands", 4,
                   ImGuiTableFlags_RowBg |
                       ImGuiTableFlags_SizingStretchProp)) {
        ImGui::TableSetupColumn("Projected-height interval", ImGuiTableColumnFlags_WidthStretch, 1.6f);
        ImGui::TableSetupColumn("Selected authored level", ImGuiTableColumnFlags_WidthStretch, 1.5f);
        ImGui::TableSetupColumn("Triangles", ImGuiTableColumnFlags_WidthStretch, 1.0f);
        ImGui::TableSetupColumn("Vertices", ImGuiTableColumnFlags_WidthStretch, 1.0f);
        ImGui::TableHeadersRow();
        for (size_t band = 0u; band < lodBandCount; ++band) {
            const CharacterWorkshopLodBand &range = lodBands[band];
            ImGui::TableNextRow();
            ImGui::TableNextColumn();
            if (std::isinf(range.maximumProjectedHeight)) {
                ImGui::Text("%.1f+ px", static_cast<double>(range.minimumProjectedHeight));
            } else {
                ImGui::Text("%.1f–%.1f px",
                            static_cast<double>(range.minimumProjectedHeight),
                            static_cast<double>(range.maximumProjectedHeight));
            }
            ImGui::TableNextColumn(); ImGui::Text("LOD%u", range.lod);
            ImGui::TableNextColumn();
            ImGui::Text("%u", entry->lod_triangles[range.lod]);
            ImGui::TableNextColumn();
            ImGui::Text("%u", entry->lod_vertices[range.lod]);
        }
        ImGui::EndTable();
    }
    if (nonMonotonic) {
        ImGui::TextColored(
            AppTheme::bad(),
            "Larger on-screen size selects fewer triangles at least once — review authored LOD ordering.");
    } else if (dramaticStep) {
        ImGui::TextColored(
            AppTheme::accent(),
            "At least one transition adds more than 4× the triangles — inspect silhouette and material popping in the exact game.");
    } else {
        ImGui::TextColored(
            AppTheme::good(),
            "Triangle counts increase monotonically with screen size without an extreme greater-than-4× step.");
    }
    const uint32_t selectedLod = CharacterWorkshop_selectLod(
        24.0f, entry->source_lod_bias, tuning.lodBias, authoredLodMask);
    const uint32_t assemblyLod = selectedLod <
            MDKR_MODERN_CHARACTER_LOD_LEVELS
        ? selectedLod : 0u;
    const uint64_t visibleInstances =
        static_cast<uint64_t>(players) * static_cast<uint64_t>(players);
    const uint64_t triangles =
        static_cast<uint64_t>(entry->lod_triangles[assemblyLod]) *
        visibleInstances;
    const uint64_t vertices =
        static_cast<uint64_t>(entry->lod_vertices[assemblyLod]) *
        visibleInstances;
    const uint64_t draws =
        static_cast<uint64_t>(entry->lod_primitives[assemblyLod]) *
        visibleInstances;
    const uint64_t paletteMatrices =
        static_cast<uint64_t>(entry->lod_palette_matrices[assemblyLod]) *
        visibleInstances * 2u;
    const uint64_t geometryBytes =
        static_cast<uint64_t>(entry->stats.vertices) *
            sizeof(MdkrModernVertex) +
        static_cast<uint64_t>(entry->stats.triangles) * 3u * sizeof(uint32_t);
    if (ImGui::BeginTable(
            "##character-performance-assembly", 2,
            ImGuiTableFlags_BordersInnerH | ImGuiTableFlags_SizingStretchProp)) {
        /* SizingStretchProp derives unspecified weights from the previous
         * frame's measured content.  Both measurements are zero while this
         * table is first appearing, so explicit weights avoid a transient
         * 0 / 0 in ImGui's table layout and keep the child content extent
         * finite under UBSan. */
        ImGui::TableSetupColumn(
            "Metric", ImGuiTableColumnFlags_WidthStretch, 2.0f);
        ImGui::TableSetupColumn(
            "Assembly value", ImGuiTableColumnFlags_WidthStretch, 1.0f);
        auto countRow = [](const char *label, uint64_t value) {
            ImGui::TableNextRow();
            ImGui::TableSetColumnIndex(0);
            ImGui::TextUnformatted(label);
            ImGui::TableSetColumnIndex(1);
            ImGui::Text("%llu", static_cast<unsigned long long>(value));
        };
        auto memoryRow = [](const char *label, uint64_t bytes) {
            ImGui::TableNextRow();
            ImGui::TableSetColumnIndex(0);
            ImGui::TextUnformatted(label);
            ImGui::TableSetColumnIndex(1);
            ImGui::Text("%.2f MiB", static_cast<double>(bytes) /
                (1024.0 * 1024.0));
        };
        countRow("Worst-visible character instances", visibleInstances);
        const std::string triangleLabel = "Near-view LOD" +
            std::to_string(assemblyLod) + " triangles submitted";
        const std::string vertexLabel = "Near-view LOD" +
            std::to_string(assemblyLod) + " vertices referenced";
        countRow(triangleLabel.c_str(), triangles);
        countRow(vertexLabel.c_str(), vertices);
        countRow("Character draw submissions", draws);
        countRow("Current + previous bone matrices prepared", paletteMatrices);
        memoryRow("Shared geometry upload", geometryBytes);
        memoryRow("RGBA-equivalent texture budget",
                  entry->stats.decoded_texture_bytes);
        ImGui::EndTable();
    }
    ImGui::TextDisabled(
        "LOD0 authoring guide: %s · near-view policy selects LOD%u · timing still requires the exact-context stress test",
        characterPerformanceTier(entry), assemblyLod);
    for (uint32_t lod = 0u;
         lod < entry->stats.lod_levels &&
         lod < MDKR_MODERN_CHARACTER_LOD_LEVELS; ++lod) {
        ImGui::BulletText(
            "LOD%u%s: %u triangles · %u vertices · %u draw part(s)",
            lod, lod == assemblyLod ? " · near-view selected" : "",
            entry->lod_triangles[lod], entry->lod_vertices[lod],
            entry->lod_primitives[lod]);
    }
    ui::TextSubtleWrapped(
        "Near-view selection uses the same projected-height thresholds, package bias, local bias, clamping, and sparse-LOD fallback as the runtime. Live cameras add an 8%% guard band to prevent transition chatter. Valid camera evidence also orders BLEND primitives by posed centroid; if it is unavailable, LOD falls back to distance and the complete BLEND subset keeps authored order, so rerun the exact context. These are exact structural counts, not a frame-time prediction: materials, transparency, overdraw, skinning, visibility, GPU, resolution, and other racers still require an exact-context test.");
    if (std::getenv("MDKR_APP_UI_TRACE") != nullptr &&
        g_characterPerformanceTracePackages.insert(entry->id).second) {
        std::fprintf(
            stderr,
            "[app-ui] character-performance-targets package=%s targets=quality,balanced,performance,four-player custom=1 sourceBias=%.1f localBias=%.1f players=%d selectedLod=%u exactAssembly=1 lodBands=%zu inspectionHeight=%.1f inspectionLod=%u monotonic=%d dramatic=%d importCeiling=unchanged history=performance projectedPolicy=1 hysteresis=8%% fallback=distance blendOrder=posed-centroid-per-view transparentSelfSort=visual-review transparentSceneQueue=visual-review\n",
            entry->id, static_cast<double>(entry->source_lod_bias),
            static_cast<double>(tuning.lodBias), players, assemblyLod,
            lodBandCount, static_cast<double>(inspectionHeight),
            safeInspectionLod, nonMonotonic ? 0 : 1,
            dramaticStep ? 1 : 0);
    }
    finishCharacterHistory(entry, history);
}

void requestCharacterPreview(const MdkrModernCharacterEntry *entry,
                             MdkrCharacterPreviewContext context,
                             int players,
                             MdkrCharacterPreviewPose pose,
                             unsigned posePhaseMilli,
                             int viewYawDegrees,
                             int viewPitchDegrees,
                             MdkrWorkshopPreviewLighting lighting,
                             const char *capturePng,
                             MdkrCharacterPreviewCaptureKind captureKind,
                             MdkrCharacterPreviewPose transitionFromPose,
                             unsigned transitionFromPhaseMilli,
                             const CharacterPreviewRouteOptions &options) {
    const bool autoReturnAfterCapture = options.autoReturnAfterCapture;
    const bool launcherOwnedCapture =
        options.disposition.launcherOwnedCapture;
    const bool interactiveStudio = options.disposition.interactiveStudio;
    const bool portraitSourceHandoff =
        options.disposition.portraitSourceHandoff;
    const bool representativeMotionReview =
        options.disposition.representativeMotionReview;
    const bool donorReference = options.disposition.donorReference;
    const MdkrCharacterPreviewScene scene = options.scene;
    const CharacterTuningEdit &tuning = loadCharacterTuning(0, entry->id);
    const std::string testTuningSignature = characterTestTuningSignature(
        entry, tuning, static_cast<unsigned>(context - 1));
    const std::string presentationSignature =
        characterTestPresentationSignature();
    if (testTuningSignature.empty() || presentationSignature.empty()) {
        setStatus(
            "The exact test could not bind its source, fit, LOD policy, and presentation settings; no test was started.",
            AppTheme::bad());
        return;
    }
    const bool inspection = pose != MDKR_CHARACTER_PREVIEW_POSE_LIVE;
    const bool transition =
        transitionFromPose != MDKR_CHARACTER_PREVIEW_POSE_LIVE;
    const bool capture = capturePng != nullptr && capturePng[0] != '\0';
    const bool donorPoseValid =
        (pose == MDKR_CHARACTER_PREVIEW_POSE_LIVE &&
         posePhaseMilli == 0u) ||
        (posePhaseMilli == 500u &&
         (context == MDKR_CHARACTER_PREVIEW_SELECT
              ? pose == MDKR_CHARACTER_PREVIEW_POSE_SELECT_IDLE
              : context >= MDKR_CHARACTER_PREVIEW_CAR &&
                    context <= MDKR_CHARACTER_PREVIEW_PLANE &&
                    pose == MDKR_CHARACTER_PREVIEW_POSE_RACE_STEER));
    const bool donorViewValid =
        pose == MDKR_CHARACTER_PREVIEW_POSE_LIVE ||
                context == MDKR_CHARACTER_PREVIEW_SELECT
            ? viewYawDegrees == 0 && viewPitchDegrees == 0
            : true;
    int captureExists = 0;
    const size_t captureLength = capture ? std::strlen(capturePng) : 0u;
    if (capture) {
        (void)mdkr_path_query_utf8(
            capturePng, &captureExists, nullptr, nullptr);
    }
    if (viewYawDegrees < -180 || viewYawDegrees > 180 ||
        scene < MDKR_CHARACTER_PREVIEW_SCENE_BASELINE ||
        scene >= MDKR_CHARACTER_PREVIEW_SCENE_COUNT ||
        (context == MDKR_CHARACTER_PREVIEW_SELECT &&
         scene != MDKR_CHARACTER_PREVIEW_SCENE_BASELINE) ||
        viewPitchDegrees < MDKR_WORKSHOP_PREVIEW_PITCH_MIN_DEGREES ||
        viewPitchDegrees > MDKR_WORKSHOP_PREVIEW_PITCH_MAX_DEGREES ||
        lighting < MDKR_WORKSHOP_PREVIEW_LIGHTING_NEUTRAL ||
        lighting >= MDKR_WORKSHOP_PREVIEW_LIGHTING_COUNT ||
        captureKind < MDKR_CHARACTER_PREVIEW_CAPTURE_SCENE ||
        captureKind >= MDKR_CHARACTER_PREVIEW_CAPTURE_COUNT ||
        (!capture && captureKind !=
             MDKR_CHARACTER_PREVIEW_CAPTURE_SCENE) ||
        (autoReturnAfterCapture && !capture) ||
        (launcherOwnedCapture && (!autoReturnAfterCapture || !capture)) ||
        (donorReference &&
         (!launcherOwnedCapture || portraitSourceHandoff ||
          interactiveStudio || representativeMotionReview || players != 1 ||
          !capture || captureKind != MDKR_CHARACTER_PREVIEW_CAPTURE_SCENE ||
          !donorPoseValid ||
          transition || !donorViewValid ||
          lighting != MDKR_WORKSHOP_PREVIEW_LIGHTING_NEUTRAL)) ||
        (portraitSourceHandoff &&
         (!launcherOwnedCapture || interactiveStudio || players != 1 ||
          context == MDKR_CHARACTER_PREVIEW_SELECT ||
          pose != MDKR_CHARACTER_PREVIEW_POSE_SELECT_IDLE ||
          posePhaseMilli != 500u || transition || viewYawDegrees != 180 ||
          viewPitchDegrees != 0 ||
          lighting != MDKR_WORKSHOP_PREVIEW_LIGHTING_BRIGHT ||
          captureKind != MDKR_CHARACTER_PREVIEW_CAPTURE_MODEL_ALPHA)) ||
        (representativeMotionReview &&
         (interactiveStudio || launcherOwnedCapture ||
          portraitSourceHandoff || autoReturnAfterCapture || players != 1 ||
          context < MDKR_CHARACTER_PREVIEW_SELECT ||
          context > MDKR_CHARACTER_PREVIEW_PLANE ||
          (context == MDKR_CHARACTER_PREVIEW_SELECT
               ? pose != MDKR_CHARACTER_PREVIEW_POSE_SELECT_IDLE ||
                     posePhaseMilli != 500u
               : pose != MDKR_CHARACTER_PREVIEW_POSE_RACE_STEER ||
                     posePhaseMilli != 0u) ||
          transition || viewYawDegrees != 0 ||
          viewPitchDegrees != 0 ||
          lighting != MDKR_WORKSHOP_PREVIEW_LIGHTING_NEUTRAL || capture)) ||
        (interactiveStudio &&
         (inspection || capture || autoReturnAfterCapture)) ||
        (transition && capture) ||
        (!inspection && !donorReference &&
         (viewYawDegrees != 0 || viewPitchDegrees != 0 ||
                         lighting !=
                             MDKR_WORKSHOP_PREVIEW_LIGHTING_NEUTRAL ||
                         capture)) ||
        (context == MDKR_CHARACTER_PREVIEW_SELECT &&
         (viewYawDegrees != 0 || viewPitchDegrees != 0)) ||
        (capture &&
         (captureLength < 4u || captureLength >= 1024u ||
          std::strcmp(capturePng + captureLength - 4u, ".png") != 0 ||
          captureExists))) {
        setStatus(
            transition && capture
                ? "Switch to Held sample before capturing a deterministic PNG; the transition review was not started."
            : capture
                ? "Choose a new writable .png filename; captures never overwrite an existing file."
                : "The inspection view or lighting request was invalid; no preview was started.",
            AppTheme::bad());
        return;
    }
    if (pose < MDKR_CHARACTER_PREVIEW_POSE_LIVE ||
        pose >= MDKR_CHARACTER_PREVIEW_POSE_COUNT ||
        posePhaseMilli > 1000u ||
        transitionFromPose < MDKR_CHARACTER_PREVIEW_POSE_LIVE ||
        transitionFromPose >= MDKR_CHARACTER_PREVIEW_POSE_COUNT ||
        transitionFromPhaseMilli > 1000u ||
        (transition
             ? (!inspection || transitionFromPose == pose)
             : transitionFromPhaseMilli != 0u)) {
        setStatus("The pose inspection request was invalid; no preview was started.",
                  AppTheme::bad());
        return;
    }
    g_characterPreviewRequest = SettingsCharacterPreviewRequest{};
    g_characterPreviewRequest.packageId = entry->id;
    g_characterPreviewRequest.sourceSha256 =
        characterDigestHex(entry->source_sha256);
    g_characterPreviewRequest.fitSha256 = testTuningSignature;
    g_characterPreviewRequest.presentationSha256 = presentationSignature;
    g_characterPreviewRequest.context = context;
    g_characterPreviewRequest.scene = scene;
    g_characterPreviewRequest.players = players;
    g_characterPreviewRequest.pose = pose;
    g_characterPreviewRequest.posePhaseMilli =
        inspection ? posePhaseMilli : 0u;
    g_characterPreviewRequest.transitionFromPose = transition
        ? transitionFromPose : MDKR_CHARACTER_PREVIEW_POSE_LIVE;
    g_characterPreviewRequest.transitionFromPhaseMilli = transition
        ? transitionFromPhaseMilli : 0u;
    g_characterPreviewRequest.viewYawDegrees =
        inspection ? viewYawDegrees : 0;
    g_characterPreviewRequest.viewPitchDegrees =
        inspection ? viewPitchDegrees : 0;
    g_characterPreviewRequest.lighting = inspection
        ? lighting : MDKR_WORKSHOP_PREVIEW_LIGHTING_NEUTRAL;
    if (capture) g_characterPreviewRequest.capturePng = capturePng;
    g_characterPreviewRequest.captureKind = capture
        ? captureKind : MDKR_CHARACTER_PREVIEW_CAPTURE_SCENE;
    g_characterPreviewRequest.autoReturnAfterCapture =
        autoReturnAfterCapture;
    g_characterPreviewRequest.launcherOwnedCapture =
        launcherOwnedCapture;
    g_characterPreviewRequest.portraitSourceHandoff =
        portraitSourceHandoff;
    g_characterPreviewRequest.interactiveStudio = interactiveStudio;
    g_characterPreviewRequest.representativeMotionReview =
        representativeMotionReview;
    g_characterPreviewRequest.donorReference = donorReference;
    g_characterPreviewRequested = true;
    setStatus(
        donorReference
            ? "Checking the selected ROM, then capturing the chosen retail donor in the same game context."
        : representativeMotionReview
            ? "Checking the selected ROM, then reviewing start, steer, airborne, landing, and finish motion in one exact game session."
        : interactiveStudio
            ? "Checking the selected ROM, then opening the live exact Offset Studio."
        : pose == MDKR_CHARACTER_PREVIEW_POSE_LIVE
            ? "Checking the selected ROM, then opening the exact game context."
            : transition
                ? "Checking the selected ROM, then opening the exact game context with a repeating A-to-B semantic transition."
            : capture
                ? autoReturnAfterCapture
                    ? "Checking the selected ROM, then capturing one stabilized exact-renderer frame and returning automatically."
                    : "Checking the selected ROM, then opening the held inspection pose and saving one stabilized PNG."
                : "Checking the selected ROM, then opening the exact game context with the inspection pose held.",
        AppTheme::good());
}

std::string boundedCharacterPreviewText(const char *text, size_t capacity) {
    if (text == nullptr) return {};
    size_t length = 0u;
    while (length < capacity && text[length] != '\0') ++length;
    return std::string(text, length);
}

CharacterTestEvidenceStore::Evidence characterTestEvidenceFromResult(
    const std::string &packageId, const std::string &sourceSha256,
    const std::string &fitSha256,
    const std::string &presentationSha256,
    const MdkrCharacterPreviewResult &result) {
    CharacterTestEvidenceStore::Evidence evidence;
    evidence.packageId = packageId;
    const std::time_t now = std::time(nullptr);
    evidence.capturedUnix = now >= 0 ? static_cast<uint64_t>(now) : 0u;
    evidence.sourceSha256 = sourceSha256;
    evidence.fitSha256 = fitSha256;
    evidence.presentationSha256 = presentationSha256;
    evidence.buildVersion = AppVersion();
    evidence.context = static_cast<uint32_t>(result.context);
    evidence.players = static_cast<uint32_t>(result.players);
    evidence.resultVersion = result.version;
    evidence.started = result.started != 0;
    evidence.warmupComplete = result.warmup_complete != 0;
    evidence.realtime = result.realtime != 0;
    evidence.warmupTicks = result.warmup_ticks;
    evidence.intervalSamples = result.interval_samples;
    evidence.displayedFrames = result.displayed_frames;
    evidence.intervalP50Us = result.interval_p50_us;
    evidence.intervalP95Us = result.interval_p95_us;
    evidence.intervalP99Us = result.interval_p99_us;
    evidence.intervalMeanUs = result.interval_mean_us;
    evidence.intervalMaxUs = result.interval_max_us;
    evidence.tickwallSamples = result.tickwall_samples;
    evidence.tickwallMeanNs = result.tickwall_mean_ns;
    evidence.gpuTiming = result.gpu_timing;
    evidence.replacementDraws = result.replacement_draws;
    evidence.replacementPrimitives = result.replacement_primitives;
    evidence.hiddenDonorBatches = result.hidden_donor_batches;
    evidence.contactSolves = result.contact_solves;
    evidence.contactErrorMeanMicrometres =
        result.contact_error_mean_micrometres;
    evidence.contactErrorMaxMicrometres =
        result.contact_error_max_micrometres;
    evidence.contactWitnessMask = result.contact_witness_mask;
    for (unsigned contact = 0u;
         contact < MDKR_CHARACTER_PREVIEW_CONTACTS; ++contact) {
        for (unsigned axis = 0u; axis < 3u; ++axis) {
            evidence.contactChainRootMicrometres[contact][axis] =
                result.contact_chain_root_micrometres[contact][axis];
            evidence.contactBendMicrometres[contact][axis] =
                result.contact_bend_micrometres[contact][axis];
            evidence.contactTargetMicrometres[contact][axis] =
                result.contact_target_micrometres[contact][axis];
            evidence.contactEndMicrometres[contact][axis] =
                result.contact_end_micrometres[contact][axis];
        }
        evidence.contactWitnessErrorMicrometres[contact] =
            result.contact_witness_error_micrometres[contact];
    }
    evidence.fitDiagnosticsValid = result.fit_diagnostics_valid != 0;
    for (unsigned axis = 0u; axis < 3u; ++axis) {
        evidence.fitBoundsMinMicrometres[axis] =
            result.fit_bounds_min_micrometres[axis];
        evidence.fitBoundsMaxMicrometres[axis] =
            result.fit_bounds_max_micrometres[axis];
        evidence.fitAnchorMicrometres[axis] =
            result.fit_anchor_micrometres[axis];
        evidence.fitForwardMilli[axis] = result.fit_forward_milli[axis];
    }
    evidence.fitLandmarkMask = result.fit_landmark_mask;
    for (unsigned landmark = 0u;
         landmark < MDKR_CHARACTER_PREVIEW_LANDMARKS; ++landmark) {
        for (unsigned axis = 0u; axis < 3u; ++axis) {
            evidence.fitLandmarkMicrometres[landmark][axis] =
                result.fit_landmark_micrometres[landmark][axis];
        }
    }
    evidence.cameraProjectionValid = result.camera_projection_valid != 0;
    evidence.cameraProjectionWidth = result.camera_projection_width;
    evidence.cameraProjectionHeight = result.camera_projection_height;
    evidence.cameraProjectionPrimitiveDraws =
        result.camera_projection_primitive_draws;
    for (unsigned component = 0u; component < 4u; ++component) {
        evidence.cameraProjectionViewport[component] =
            result.camera_projection_viewport[component];
        evidence.cameraProjectionScissor[component] =
            result.camera_projection_scissor[component];
        evidence.cameraBoundsPixelMilli[component] =
            result.camera_bounds_pixel_milli[component];
    }
    evidence.cameraBoundsClipFlags = result.camera_bounds_clip_flags;
    for (unsigned landmark = 0u;
         landmark < MDKR_CHARACTER_PREVIEW_LANDMARKS; ++landmark) {
        evidence.cameraLandmarkPixelMilli[landmark][0] =
            result.camera_landmark_pixel_milli[landmark][0];
        evidence.cameraLandmarkPixelMilli[landmark][1] =
            result.camera_landmark_pixel_milli[landmark][1];
        evidence.cameraLandmarkDepthMillionths[landmark] =
            result.camera_landmark_depth_millionths[landmark];
        evidence.cameraLandmarkClipFlags[landmark] =
            result.camera_landmark_clip_flags[landmark];
    }
    evidence.vehicleSurfaceValid = result.vehicle_surface_valid != 0;
    evidence.vehicleShellTrianglesSubmitted =
        result.vehicle_shell_triangles_submitted;
    evidence.vehicleShellTrianglesTested =
        result.vehicle_shell_triangles_tested;
    evidence.characterSurfaceTrianglesSubmitted =
        result.character_surface_triangles_submitted;
    evidence.characterSurfaceTrianglesTested =
        result.character_surface_triangles_tested;
    evidence.vehicleSurfaceCrossingTriangles =
        result.vehicle_surface_crossing_triangles;
    evidence.vehicleSurfaceCrossingPairs =
        result.vehicle_surface_crossing_pairs;
    for (unsigned axis = 0u; axis < 3u; ++axis) {
        evidence.vehicleSurfaceFirstCrossingMicrometres[axis] =
            result.vehicle_surface_first_crossing_micrometres[axis];
    }
    evidence.vehicleVolumeQualified =
        result.vehicle_volume_qualified != 0;
    evidence.vehicleShellBoundaryEdges =
        result.vehicle_shell_boundary_edges;
    evidence.vehicleShellNonmanifoldEdges =
        result.vehicle_shell_nonmanifold_edges;
    evidence.vehicleShellOrientationMismatchEdges =
        result.vehicle_shell_orientation_mismatch_edges;
    evidence.vehicleShellSelfIntersectionPairs =
        result.vehicle_shell_self_intersection_pairs;
    evidence.vehicleContainmentSamplesTested =
        result.vehicle_containment_samples_tested;
    evidence.vehicleContainmentInsideSamples =
        result.vehicle_containment_inside_samples;
    evidence.vehicleContainmentBoundarySamples =
        result.vehicle_containment_boundary_samples;
    evidence.vehicleContainmentOutsideSamples =
        result.vehicle_containment_outside_samples;
    evidence.vehicleContainmentMaximumDepthMicrometres =
        result.vehicle_containment_maximum_depth_micrometres;
    for (unsigned axis = 0u; axis < 3u; ++axis) {
        evidence.vehicleContainmentDeepestMicrometres[axis] =
            result.vehicle_containment_deepest_micrometres[axis];
    }
    evidence.opaqueVisibilityValid = result.opaque_visibility_valid != 0;
    evidence.opaqueVisibilityQualified =
        result.opaque_visibility_qualified != 0;
    evidence.opaqueVisibilityWidth = result.opaque_visibility_width;
    evidence.opaqueVisibilityHeight = result.opaque_visibility_height;
    for (unsigned component = 0u; component < 4u; ++component) {
        evidence.opaqueVisibilityViewport[component] =
            result.opaque_visibility_viewport[component];
        evidence.opaqueVisibilityScissor[component] =
            result.opaque_visibility_scissor[component];
    }
    evidence.opaqueVisibilityPrimitiveDraws =
        result.opaque_visibility_primitive_draws;
    evidence.opaqueVisibilityOpaqueDraws =
        result.opaque_visibility_opaque_draws;
    evidence.opaqueVisibilityMaskedDraws =
        result.opaque_visibility_masked_draws;
    evidence.opaqueVisibilityTransparentDraws =
        result.opaque_visibility_transparent_draws;
    evidence.opaqueVisibilityGridColumns =
        result.opaque_visibility_grid_columns;
    evidence.opaqueVisibilityGridRows = result.opaque_visibility_grid_rows;
    evidence.opaqueVisibilityIsolatedTiles =
        result.opaque_visibility_isolated_tiles;
    evidence.opaqueVisibilitySceneTiles =
        result.opaque_visibility_scene_tiles;
    evidence.opaqueVisibilityIsolatedTileMask =
        result.opaque_visibility_isolated_tile_mask;
    evidence.opaqueVisibilitySceneTileMask =
        result.opaque_visibility_scene_tile_mask;
    evidence.opaqueVisibilityOccluderPresentMask =
        result.opaque_visibility_occluder_present_mask;
    evidence.opaqueVisibilityOccluderQualifiedMask =
        result.opaque_visibility_occluder_qualified_mask;
    for (unsigned occluder = 0u;
         occluder < MDKR_CHARACTER_PREVIEW_OCCLUDERS; ++occluder) {
        evidence.opaqueVisibilityOccluderDraws[occluder] =
            result.opaque_visibility_occluder_draws[occluder];
        evidence.opaqueVisibilityOccluderUnqualifiedDraws[occluder] =
            result.opaque_visibility_occluder_unqualified_draws[occluder];
        evidence.opaqueVisibilityOccluderOverlapTiles[occluder] =
            result.opaque_visibility_occluder_overlap_tiles[occluder];
        evidence.opaqueVisibilityOccluderOverlapTileMask[occluder] =
            result.opaque_visibility_occluder_overlap_tile_mask[occluder];
    }
    evidence.backend = boundedCharacterPreviewText(
        result.renderer_backend, sizeof(result.renderer_backend));
    evidence.adapter = boundedCharacterPreviewText(
        result.adapter, sizeof(result.adapter));
    evidence.driver = boundedCharacterPreviewText(
        result.driver, sizeof(result.driver));
    evidence.vendorId = result.vendor_id;
    evidence.deviceId = result.device_id;
    evidence.outputWidth = result.output_width;
    evidence.outputHeight = result.output_height;
    evidence.renderWidth = result.render_width;
    evidence.renderHeight = result.render_height;
    return evidence;
}

