namespace {

const MdkrModernCharacterEntry *characterStudioEntry(const char *packageId) {
    if (packageId == nullptr || packageId[0] == '\0') return nullptr;
    if (!g_characterRegistryLoaded) refreshCharacterRegistry();
    const int index = mdkr_modern_character_registry_find(
        &g_characterRegistry, packageId);
    return mdkr_modern_character_registry_entry(&g_characterRegistry, index);
}

MdkrModernCharacterTuning characterRuntimeTuning(
    const CharacterTuningEdit &edit) {
    MdkrModernCharacterTuning tuning{};
    mdkr_modern_character_tuning_defaults(&tuning);
    tuning.scale = edit.scale;
    std::copy(std::begin(edit.offset), std::end(edit.offset),
              tuning.translation);
    std::copy(std::begin(edit.rotation), std::end(edit.rotation),
              tuning.rotation_degrees);
    tuning.animation_speed = edit.animationSpeed;
    tuning.lod_bias = edit.lodBias;
    tuning.vehicle_mask = edit.vehicleMask;
    for (unsigned context = 0u;
         context < MDKR_CHARACTER_CONTEXT_COUNT; ++context) {
        tuning.context[context].scale = edit.context[context].scale;
        std::copy(std::begin(edit.context[context].offset),
                  std::end(edit.context[context].offset),
                  tuning.context[context].translation);
        std::copy(std::begin(edit.context[context].rotation),
                  std::end(edit.context[context].rotation),
                  tuning.context[context].rotation_degrees);
        for (unsigned contact = 0u;
             contact < MDKR_MODERN_CHARACTER_CONTACTS; ++contact) {
            std::copy(std::begin(edit.context[context].contacts[contact]),
                      std::end(edit.context[context].contacts[contact]),
                      tuning.contact_offset[context][contact]);
        }
    }
    return tuning;
}

bool applyCharacterStudioRuntime(const CharacterTuningEdit &edit) {
    MdkrModernCharacterTuning tuning = characterRuntimeTuning(edit);
    char error[192] = {};
    if (mdkr_modern_character_set_tuning(
            0, &tuning, error, sizeof(error))) return true;
    setStatus(
        error[0] != '\0' ? error
                          : "The exact renderer rejected this fit change.",
        AppTheme::bad());
    return false;
}

bool durableCharacterStudioTuning(
    const MdkrModernCharacterEntry *entry, CharacterTuningEdit &out) {
    if (g_characterActiveDrafts.find(entry->id) !=
        g_characterActiveDrafts.end()) {
        if (persistedActiveCharacterDraftTuning(entry, out)) return true;
        setStatus(
            "The named draft baseline could not be read; this edit was cancelled without changing the draft.",
            AppTheme::bad());
        return false;
    }
    out = persistedCharacterTuning(0, entry->id);
    return true;
}

bool persistCharacterStudioTuning(
    const MdkrModernCharacterEntry *entry,
    const CharacterTuningEdit &edit) {
    if (g_characterActiveDrafts.find(entry->id) ==
        g_characterActiveDrafts.end()) {
        return persistCharacterTuning(entry->id, edit);
    }
    g_characterPreviewResults.erase(entry->id);
    if (autosaveActiveCharacterDraft(entry)) {
        setStatus("Fit change saved in the named draft.", AppTheme::good());
        return true;
    }
    setStatus(
        "The fit change could not be saved in the named draft.",
        AppTheme::bad());
    return false;
}

void rollbackCharacterStudioPersistence(
    const MdkrModernCharacterEntry *entry, CharacterTuningEdit &edit,
    const CharacterTuningEdit &persisted) {
    edit = persisted;
    if (g_characterActiveDrafts.find(entry->id) ==
        g_characterActiveDrafts.end()) {
        stageCharacterTuningConfig(entry->id, persisted);
    }
    (void)applyCharacterStudioRuntime(edit);

    /* An undo/redo or coalesced drag may already have moved the Fit track.
     * Storage failure restores the durable profile, so retaining that moved
     * stack would make its labels lie about the state they will restore. */
    CharacterPackageHistory &package = g_characterEditHistories[entry->id];
    package.tracks[static_cast<size_t>(CharacterHistoryTool::Fit)] =
        CharacterEditHistory::Track{};
}

}  // namespace

SettingsCharacterStudioFrame Settings_drawCharacterOffsetStudio(
    SDL_Window *window, const char *packageId,
    MdkrCharacterPreviewContext previewContext, bool initializeRuntime) {
    const WorkshopStatusCapture capture;
    (void)window;
    SettingsCharacterStudioFrame frame;
    const MdkrModernCharacterEntry *entry = characterStudioEntry(packageId);
    if (entry == nullptr ||
        previewContext < MDKR_CHARACTER_PREVIEW_SELECT ||
        previewContext > MDKR_CHARACTER_PREVIEW_PLANE) {
        ImGui::TextColored(
            AppTheme::bad(),
            "This character or preview context is no longer available.");
        ui::TextSubtleWrapped(
            "Return to the Workshop and reopen the exact context. No game or package data was changed here.");
        frame.returnRequested = ImGui::Button(
            "Return to Workshop", ui::kBtnFullWidth());
        return frame;
    }

    const unsigned context =
        static_cast<unsigned>(previewContext - MDKR_CHARACTER_PREVIEW_SELECT);
    static const char *contextNames[MDKR_CHARACTER_CONTEXT_COUNT] = {
        "Character select", "Car", "Hovercraft", "Plane",
    };
    CharacterTuningEdit &edit = loadCharacterTuning(0, entry->id);
    const CharacterTuningEdit frameStart = edit;
    if (initializeRuntime && !applyCharacterStudioRuntime(edit)) {
        ui::TextSubtleWrapped(
            "The saved fit remains unchanged. Return to the Workshop and reopen this exact context after resolving the renderer error.");
    }
    ImGui::TextColored(AppTheme::accent(), "%s", entry->display_name);
    ImGui::SameLine();
    ImGui::TextDisabled("· %s · exact game renderer", contextNames[context]);
    ui::TextSubtleWrapped(
        context == MDKR_CHARACTER_CONTEXT_SELECT
            ? "Adjust the model against the real selection-room floor, donor animation, and game camera. Changes appear in the scene on the next rendered frame."
            : "Adjust the model against the real donor, vehicle, seat frame, animation, and game camera. Changes appear in the scene on the next rendered frame.");
    ui::TextSubtleWrapped(
        "Changes are previewed live and stay in this fit draft until you return to the Workshop.");

    CharacterHistoryFrame history = beginCharacterHistory(
        entry, CharacterHistoryTool::Fit);
    if (history.actionApplied) {
        CharacterTuningEdit persisted;
        if (!durableCharacterStudioTuning(entry, persisted)) {
            rollbackCharacterStudioPersistence(entry, edit, frameStart);
        } else if (!applyCharacterStudioRuntime(edit) ||
                   !persistCharacterStudioTuning(entry, edit)) {
            rollbackCharacterStudioPersistence(entry, edit, persisted);
        }
    }
    CharacterTuningEdit before = edit;
    CharacterTuningEdit::Context &placement = edit.context[context];

    ImGui::SeparatorText("Source correction");
    bool edited = false;
    bool commit = false;
    const auto speakScalar = [](const char *label, float value) {
        char spoken[48];
        std::snprintf(spoken, sizeof(spoken), "%.3f", static_cast<double>(value));
        ui::SpeakFocusedItem(label, spoken, "Adjusts the live fit draft.");
    };
    const auto speakVector = [](const char *label, const float *value) {
        char spoken[120];
        std::snprintf(spoken, sizeof(spoken), "X %.3f, Y %.3f, Z %.3f",
                      static_cast<double>(value[0]), static_cast<double>(value[1]),
                      static_cast<double>(value[2]));
        ui::SpeakFocusedItem(label, spoken, "Adjusts the live fit draft.");
    };
    edited |= ImGui::SliderFloat(
        "Character size", &edit.scale, 0.1f, 5.0f, "%.2fx",
        ImGuiSliderFlags_AlwaysClamp);
    speakScalar("Character size", edit.scale);
    commit |= ImGui::IsItemDeactivatedAfterEdit();
    edited |= ImGui::DragFloat3(
        "Source rotation", edit.rotation, 0.5f, -180.0f, 180.0f,
        "%.1f°", ImGuiSliderFlags_AlwaysClamp);
    speakVector("Source rotation", edit.rotation);
    commit |= ImGui::IsItemDeactivatedAfterEdit();
    if (ImGui::Button("Turn around 180°")) {
        edit.rotation[1] = characterWorkshopWrappedDegrees(
            edit.rotation[1] + 180.0f);
        edited = commit = true;
    }
    ui::SpeakFocusedItem(
        "Turn model around 180 degrees", nullptr,
        "Corrects a model that faces backward in every game context.");

    ImGui::SeparatorText("This context");
    edited |= ImGui::SliderFloat(
        "Context size", &placement.scale, 0.5f, 2.0f, "%.2fx",
        ImGuiSliderFlags_AlwaysClamp);
    speakScalar("Context size", placement.scale);
    commit |= ImGui::IsItemDeactivatedAfterEdit();
    edited |= ImGui::DragFloat3(
        "Position", placement.offset, 0.01f, -10.0f, 10.0f,
        "%.3f m", ImGuiSliderFlags_AlwaysClamp);
    speakVector("Position", placement.offset);
    commit |= ImGui::IsItemDeactivatedAfterEdit();
    edited |= ImGui::DragFloat3(
        "Rotation", placement.rotation, 0.5f, -180.0f, 180.0f,
        "%.1f°", ImGuiSliderFlags_AlwaysClamp);
    speakVector("Rotation", placement.rotation);
    commit |= ImGui::IsItemDeactivatedAfterEdit();
    ui::TextSubtleWrapped(
        "Position is relative to the automatic %s anchor. Y moves up/down; Z moves forward/back; X moves left/right.",
        context == MDKR_CHARACTER_CONTEXT_SELECT ? "ground" : "seat");

    if (context != MDKR_CHARACTER_CONTEXT_SELECT) {
        const bool contactReady = entry->rig_present != 0u &&
            entry->rig_mode == MDKR_MODERN_RIG_HUMANOID_RETARGET_V1 &&
            (entry->rig_flags & MDKR_MODERN_RIG_REVIEWED) != 0u &&
            entry->rig_role_mask == MDKR_CHARACTER_RIG_HUMANOID_MASK;
        if (ImGui::TreeNodeEx(
                "Hand and foot contact fine-tuning",
                ImGuiTreeNodeFlags_None)) {
            ui::TextSubtleWrapped(
                "Move each solved contact relative to the donor vehicle target. Use these only after body position and rotation are correct.");
            static const char *contactNames[
                MDKR_MODERN_CHARACTER_CONTACTS] = {
                    "Left hand", "Right hand", "Left foot", "Right foot",
                };
            if (!contactReady) ImGui::BeginDisabled();
            for (unsigned contact = 0u;
                 contact < MDKR_MODERN_CHARACTER_CONTACTS; ++contact) {
                edited |= ImGui::DragFloat3(
                    contactNames[contact], placement.contacts[contact],
                    0.005f, -1.0f, 1.0f, "%.3f m",
                    ImGuiSliderFlags_AlwaysClamp);
                speakVector(contactNames[contact], placement.contacts[contact]);
                commit |= ImGui::IsItemDeactivatedAfterEdit();
            }
            if (!contactReady) ImGui::EndDisabled();
            if (!contactReady) {
                ui::TextSubtleWrapped(
                    "Available after the inferred humanoid rig and its contact chains are reviewed.");
            }
            ImGui::TreePop();
        }
    }

    if (ImGui::Button("Reset this context")) {
        placement = CharacterTuningEdit::Context{};
        edited = commit = true;
    }
    ui::SpeakFocusedItem("Reset this context", nullptr, "Restores the placement for this game context.");
    ImGui::SameLine();
    if (ImGui::Button("Reset source correction")) {
        edit.scale = 1.0f;
        std::fill(std::begin(edit.offset), std::end(edit.offset), 0.0f);
        std::fill(std::begin(edit.rotation), std::end(edit.rotation), 0.0f);
        edited = commit = true;
    }

    ui::SpeakFocusedItem("Reset source correction", nullptr, "Restores the source size and rotation for all contexts.");

    if (edited) {
        if (!applyCharacterStudioRuntime(edit)) {
            edit = before;
            (void)applyCharacterStudioRuntime(edit);
        }
    }
    if (commit && edit.loaded &&
        characterFitReviewSignature(entry, before, context) !=
            characterFitReviewSignature(entry, edit, context)) {
        CharacterTuningEdit persisted;
        if (!durableCharacterStudioTuning(entry, persisted)) {
            rollbackCharacterStudioPersistence(entry, edit, frameStart);
        } else if (!persistCharacterStudioTuning(entry, edit)) {
            rollbackCharacterStudioPersistence(entry, edit, persisted);
        }
    }

    MdkrModernCharacterFitDiagnostics diagnostics{};
    frame.fitReady = mdkr_modern_character_player_fit_diagnostics(
        0, static_cast<MdkrModernCharacterContext>(context),
        &diagnostics) != 0;
    frame.measurementReady = frame.fitReady &&
        g_mdkrCharacterPreviewResult != nullptr &&
        g_mdkrCharacterPreviewResult->warmup_complete;
    ImGui::SeparatorText("Exact renderer status");
    if (frame.measurementReady) {
        ImGui::TextColored(
            AppTheme::good(),
            "Current fit rendered · height %.3f m · anchor Y %.3f m",
            static_cast<double>(diagnostics.bounds_max[1] -
                                diagnostics.bounds_min[1]),
            static_cast<double>(diagnostics.anchor[1]));
    } else if (frame.fitReady) {
        ImGui::TextColored(
            AppTheme::accent(),
            "Fit is visible · measuring the warmed exact scene…");
    } else {
        ImGui::TextColored(
            AppTheme::accent(),
            "Updating the exact scene…");
    }
    ui::TextSubtleWrapped(
        "Returning records renderer measurements for this fit, but performance approval remains a separate clean test without editor interaction.");

    const bool editing = ImGui::IsAnyItemActive();
    if (editing) ImGui::BeginDisabled();
    frame.returnRequested = ui::PrimaryButton(
        "Save & return to Workshop", ui::kBtnFullWidth());
    if (editing) ImGui::EndDisabled();
    ui::SpeakFocusedItem(
        "Save and return to Character Workshop",
        frame.measurementReady
            ? "Current fit rendered and measured"
            : "Waiting for exact renderer measurement",
        "Waits for the edited fit to render once, then returns to the same Workshop context with current measurements.");

    finishCharacterHistory(entry, history);
    return frame;
}

bool Settings_commitCharacterOffsetStudio(
    const char *packageId, MdkrCharacterPreviewContext previewContext) {
    const MdkrModernCharacterEntry *entry = characterStudioEntry(packageId);
    if (entry == nullptr ||
        previewContext < MDKR_CHARACTER_PREVIEW_SELECT ||
        previewContext > MDKR_CHARACTER_PREVIEW_PLANE) {
        setStatus(
            "The character or exact context is no longer available; return was cancelled without changing its files.",
            AppTheme::bad());
        return false;
    }

    CharacterTuningEdit &edit = loadCharacterTuning(0, entry->id);
    const unsigned context = static_cast<unsigned>(
        previewContext - MDKR_CHARACTER_PREVIEW_SELECT);
    CharacterTuningEdit persisted;
    if (!durableCharacterStudioTuning(entry, persisted)) return false;
    if (characterFitReviewSignature(entry, edit, context) ==
        characterFitReviewSignature(entry, persisted, context)) {
        return true;
    }
    if (persistCharacterStudioTuning(entry, edit)) return true;
    rollbackCharacterStudioPersistence(entry, edit, persisted);
    return false;
}

std::string Settings_characterPreviewCurrentFitSignature(
    const std::string &packageId,
    MdkrCharacterPreviewContext previewContext) {
    const MdkrModernCharacterEntry *entry = characterStudioEntry(
        packageId.c_str());
    if (entry == nullptr ||
        previewContext < MDKR_CHARACTER_PREVIEW_SELECT ||
        previewContext > MDKR_CHARACTER_PREVIEW_PLANE) return {};
    const CharacterTuningEdit &edit = loadCharacterTuning(0, entry->id);
    return characterTestTuningSignature(
        entry, edit,
        static_cast<unsigned>(previewContext -
                              MDKR_CHARACTER_PREVIEW_SELECT));
}

void Settings_publishCharacterPreviewResult(
    const std::string &packageId,
    const std::string &sourceSha256,
    const std::string &fitSha256,
    const std::string &presentationSha256,
    const std::string &capturePng,
    const SettingsCharacterPreviewDisposition &disposition,
    const MdkrCharacterPreviewResult &result,
    const MdkrCharacterMotionReviewResult *motionReview) {
    const bool launcherOwnedCapture = disposition.launcherOwnedCapture;
    const bool portraitSourceHandoff = disposition.portraitSourceHandoff;
    const bool interactiveStudio = disposition.interactiveStudio;
    const bool representativeMotionReview =
        disposition.representativeMotionReview;
    const bool donorReference = disposition.donorReference;
    if (packageId.empty()) return;
    const MdkrModernCharacterEntry *resultEntry =
        characterStudioEntry(packageId.c_str());
    if (representativeMotionReview) {
        const bool jointDiagnosticsExpected =
            characterJointDiagnosticsExpected(resultEntry);
        const bool stoppedByAuthor = motionReview != nullptr &&
            motionReview->started && !motionReview->completed &&
            motionReview->failed_sample == 0u;
        if (stoppedByAuthor) {
            auto queued = g_characterSceneReviewRuns.find(packageId);
            if (queued != g_characterSceneReviewRuns.end()) {
                queued->second.active = false;
                queued->second.refreshAll = false;
            }
            setStatus(
                "Character review stopped safely. The incomplete course was discarded; every previously completed course remains current and resumable.",
                AppTheme::subtle());
            if (std::getenv("MDKR_APP_UI_TRACE") != nullptr) {
                std::fprintf(
                    stderr,
                    "[app-ui] character-motion-review accepted=0 "
                    "cancelled=1 package=%s scene=%u completed-mask=%x\n",
                    packageId.c_str(),
                    static_cast<unsigned>(motionReview->scene),
                    motionReview->completed_mask);
            }
            return;
        }
        unsigned expectedCount = 0u;
        const CharacterMotionReviewDefinition *expected =
            motionReview != nullptr
                ? characterMotionReviewDefinitions(
                      motionReview->context, expectedCount)
                : nullptr;
        const bool vehicle = motionReview != nullptr &&
            motionReview->context != MDKR_CHARACTER_PREVIEW_SELECT;
        bool valid = motionReview != nullptr &&
            expected != nullptr && expectedCount != 0u &&
            motionReview->version ==
                MDKR_CHARACTER_MOTION_REVIEW_RESULT_VERSION &&
            motionReview->started && motionReview->completed &&
            motionReview->context >= MDKR_CHARACTER_PREVIEW_SELECT &&
            motionReview->context <= MDKR_CHARACTER_PREVIEW_PLANE &&
            motionReview->context == result.context &&
            motionReview->scene == disposition.scene &&
            motionReview->scene >=
                MDKR_CHARACTER_PREVIEW_SCENE_BASELINE &&
            motionReview->scene < MDKR_CHARACTER_PREVIEW_SCENE_COUNT &&
            (vehicle || motionReview->scene ==
                MDKR_CHARACTER_PREVIEW_SCENE_BASELINE) &&
            motionReview->sample_count == expectedCount &&
            motionReview->completed_mask ==
                MDKR_CHARACTER_MOTION_REVIEW_SAMPLE_MASK(expectedCount) &&
            motionReview->failed_sample == 0u &&
            characterDigestTextValid(sourceSha256) &&
            characterDigestTextValid(fitSha256) &&
            characterDigestTextValid(presentationSha256) &&
            capturePng.empty() && !launcherOwnedCapture &&
            !portraitSourceHandoff && !interactiveStudio;
        if (valid) {
            valid = characterMotionReviewContactStabilityValid(*motionReview);
        }
        if (valid) {
            for (unsigned index = 0u; index < expectedCount; ++index) {
                const MdkrCharacterPreviewResult &sample =
                    motionReview->samples[index];
                valid = sample.version ==
                            MDKR_CHARACTER_PREVIEW_RESULT_VERSION &&
                    sample.started && sample.warmup_complete &&
                    sample.context == motionReview->context &&
                    sample.players == 1 &&
                    sample.pose == expected[index].pose &&
                    sample.pose_phase_milli == expected[index].phaseMilli &&
                    sample.transition_from_pose ==
                        MDKR_CHARACTER_PREVIEW_POSE_LIVE &&
                    sample.transition_from_phase_milli == 0u &&
                    sample.transition_from_motion_source >
                        MDKR_CHARACTER_PREVIEW_MOTION_NONE &&
                    sample.transition_from_motion_source <
                        MDKR_CHARACTER_PREVIEW_MOTION_COUNT &&
                    sample.transition_to_motion_source ==
                        MDKR_CHARACTER_PREVIEW_MOTION_NONE &&
                    sample.inspection_pose_ticks != 0u &&
                    sample.inspection_pose_fallback_ticks <=
                        sample.inspection_pose_ticks &&
                    sample.reference_draws == 0u &&
                    sample.reference_primitives == 0u &&
                    sample.replacement_draws >= 60u &&
                    sample.view_yaw_degrees == 0 &&
                    sample.view_pitch_degrees == 0 &&
                    sample.lighting ==
                        MDKR_WORKSHOP_PREVIEW_LIGHTING_NEUTRAL &&
                    sample.camera_override_ticks == 0u &&
                    sample.lighting_override_draws == 0u &&
                    !sample.capture_requested && !sample.capture_armed &&
                    !sample.capture_written &&
                    sample.capture_png_bytes == 0u &&
                    characterPreviewFitDiagnosticsValid(sample) &&
                    characterPreviewJointDiagnosticsValid(sample) &&
                    (!jointDiagnosticsExpected ||
                     sample.joint_excursion_mask ==
                         MDKR_CHARACTER_RIG_HUMANOID_MASK) &&
                    sample.fit_diagnostics_valid &&
                    characterPreviewCameraProjectionValid(sample) &&
                    sample.camera_projection_valid &&
                    characterPreviewVehicleSurfaceValid(sample) &&
                    (vehicle ? sample.vehicle_surface_valid != 0
                             : sample.vehicle_surface_valid == 0) &&
                    (vehicle ||
                     (sample.contact_solves == 0u &&
                      sample.contact_error_mean_micrometres == 0u &&
                      sample.contact_error_max_micrometres == 0u &&
                      sample.contact_witness_mask == 0u)) &&
                    characterPreviewOpaqueVisibilityValid(sample) &&
                    sample.opaque_visibility_valid &&
                    characterPreviewContactDiagnosticsValid(sample);
                if (!valid) break;
            }
        }
        if (valid) {
            for (unsigned index = expectedCount;
                 index < MDKR_CHARACTER_MOTION_REVIEW_SAMPLE_COUNT;
                 ++index) {
                const MdkrCharacterPreviewResult &unused =
                    motionReview->samples[index];
                if (unused.version != 0u || unused.started ||
                    unused.warmup_complete || unused.replacement_draws != 0u ||
                    unused.reference_draws != 0u ||
                    unused.reference_primitives != 0u ||
                    unused.fit_diagnostics_valid ||
                    !characterPreviewJointDiagnosticsValid(unused) ||
                    unused.camera_projection_valid ||
                    unused.vehicle_surface_valid ||
                    unused.opaque_visibility_valid) {
                    valid = false;
                    break;
                }
            }
        }
        if (!valid) {
            auto queued = g_characterSceneReviewRuns.find(packageId);
            if (queued != g_characterSceneReviewRuns.end()) {
                queued->second.active = false;
                queued->second.refreshAll = false;
            }
            setStatus(
                motionReview != nullptr && motionReview->failed_sample != 0u
                    ? "Semantic motion review stopped before every state produced fresh renderer evidence. No review was recorded."
                    : "Semantic motion review returned inconsistent or incomplete evidence. No review was recorded.",
                AppTheme::bad());
            if (std::getenv("MDKR_APP_UI_TRACE") != nullptr) {
                std::fprintf(
                    stderr,
                    "[app-ui] character-motion-review accepted=0 package=%s failed=%u mask=%x\n",
                    packageId.c_str(),
                    motionReview != nullptr
                        ? motionReview->failed_sample : 0u,
                    motionReview != nullptr
                        ? motionReview->completed_mask : 0u);
            }
            return;
        }
        g_characterMotionReviewResults[packageId][
            characterMotionReviewSceneKey(
                motionReview->context, motionReview->scene)] = {
            *motionReview, sourceSha256, fitSha256, presentationSha256,
        };
        auto queued = g_characterSceneReviewRuns.find(packageId);
        const bool guidedRunHandled =
            queued != g_characterSceneReviewRuns.end() &&
            queued->second.active;
        if (guidedRunHandled) {
            CharacterSceneReviewRun &run = queued->second;
            const bool matches = run.context == motionReview->context &&
                run.nextScene == motionReview->scene &&
                run.sourceSha256 == sourceSha256 &&
                run.fitSha256 == fitSha256 &&
                run.presentationSha256 == presentationSha256;
            const unsigned sceneCount =
                characterMotionReviewSceneCount(motionReview->context);
            if (!matches) {
                run.active = false;
                run.refreshAll = false;
                setStatus(
                    "The guided scene review changed identity while the game was running. Completed evidence was kept, but the sequence stopped safely.",
                    AppTheme::accent());
            } else {
                const MdkrModernCharacterEntry *entry =
                    characterStudioEntry(packageId.c_str());
                uint32_t currentSceneMask = 0u;
                if (entry != nullptr) {
                    const CharacterTuningEdit &edit =
                        loadCharacterTuning(0, entry->id);
                    for (unsigned sceneIndex = 0u;
                         sceneIndex < sceneCount; ++sceneIndex) {
                        if (currentCharacterMotionReview(
                                entry, edit, motionReview->context,
                                static_cast<MdkrCharacterPreviewScene>(
                                    sceneIndex)) != nullptr) {
                            currentSceneMask |= 1u << sceneIndex;
                        }
                    }
                }
                const unsigned nextMissing =
                    CharacterWorkshop_nextSceneReview(
                        sceneCount,
                        static_cast<unsigned>(motionReview->scene),
                        currentSceneMask, run.refreshAll);
                if (entry == nullptr) {
                    run.active = false;
                    run.refreshAll = false;
                    setStatus(
                        "The character was removed before the next scene could start. Completed evidence was kept.",
                        AppTheme::accent());
                } else if (nextMissing < sceneCount) {
                    run.nextScene =
                        static_cast<MdkrCharacterPreviewScene>(nextMissing);
                    requestCharacterPreview(
                        entry, motionReview->context, 1,
                        MDKR_CHARACTER_PREVIEW_POSE_RACE_STEER, 0u,
                        0, 0, MDKR_WORKSHOP_PREVIEW_LIGHTING_NEUTRAL,
                        nullptr, MDKR_CHARACTER_PREVIEW_CAPTURE_SCENE,
                        MDKR_CHARACTER_PREVIEW_POSE_LIVE, 0u,
                        representativeMotionReviewRoute(run.nextScene));
                    if (g_characterPreviewRequested) {
                        setStatus(
                            "Scene review saved. Opening the next qualified course automatically…",
                            AppTheme::good());
                    } else {
                        run.active = false;
                        run.refreshAll = false;
                    }
                } else {
                    run.active = false;
                    run.refreshAll = false;
                    setStatus(
                        vehicle
                            ? "Complete race and scene review is ready: all 11 semantics were checked across all five qualified courses."
                            : "Complete character-select motion review is ready: idle, hover, and confirm all have current framing and visibility evidence.",
                        AppTheme::good());
                }
            }
        }
        if (!guidedRunHandled) {
            setStatus(
                vehicle
                ? "Complete race-motion review is ready: every semantic now has current framing, vehicle-body, visibility, and contact evidence."
                : "Complete character-select motion review is ready: idle, hover, and confirm all have current framing and visibility evidence.",
                AppTheme::good());
        }
        if (std::getenv("MDKR_APP_UI_TRACE") != nullptr) {
            std::fprintf(
                stderr,
                "[app-ui] character-motion-review accepted=1 package=%s context=%u scene=%u samples=%u fit=%s\n",
                packageId.c_str(),
                static_cast<unsigned>(motionReview->context),
                static_cast<unsigned>(motionReview->scene),
                static_cast<unsigned>(
                    expectedCount),
                fitSha256.c_str());
        }
        return;
    }
    if (!donorReference && characterJointDiagnosticsExpected(resultEntry) &&
        result.joint_excursion_mask != MDKR_CHARACTER_RIG_HUMANOID_MASK) {
        if (std::getenv("MDKR_APP_UI_TRACE") != nullptr) {
            std::fprintf(
                stderr,
                "[app-ui] character-preview-result rejected-evidence=joint-travel-contract package=%s mask=%x\n",
                packageId.c_str(), result.joint_excursion_mask);
        }
        setStatus(
            "The exact renderer omitted complete joint-travel evidence for this reviewed humanoid. No fit, motion, capture, or performance result was recorded.",
            AppTheme::bad());
        return;
    }
    if (donorReference) {
        bool retained = false;
        bool capacityReached = false;
        const MdkrModernCharacterEntry *entry =
            characterStudioEntry(packageId.c_str());
        const MdkrCharacterPreviewPose expectedPose =
            result.context == MDKR_CHARACTER_PREVIEW_SELECT
                ? MDKR_CHARACTER_PREVIEW_POSE_SELECT_IDLE
                : MDKR_CHARACTER_PREVIEW_POSE_RACE_STEER;
        const CharacterInspectionPose *pose =
            characterInspectionPose(expectedPose);
        const std::string sceneRegistration =
            characterSceneRegistrationSignature(result);
        auto comparisonRun = g_characterComparisonRuns.find(packageId);
        const bool guidedComparison =
            comparisonRun != g_characterComparisonRuns.end() &&
            comparisonRun->second.active &&
            comparisonRun->second.awaitingDonor &&
            comparisonRun->second.context == result.context &&
            comparisonRun->second.sourceSha256 == sourceSha256 &&
            comparisonRun->second.fitSha256 == fitSha256 &&
            comparisonRun->second.presentationSha256 ==
                presentationSha256;
        const int expectedComparisonYaw =
            result.context == MDKR_CHARACTER_PREVIEW_SELECT ? 0 : 180;
        const bool contextSupported = entry != nullptr &&
            (result.context == MDKR_CHARACTER_PREVIEW_SELECT ||
             (result.context >= MDKR_CHARACTER_PREVIEW_CAR &&
              result.context <= MDKR_CHARACTER_PREVIEW_PLANE &&
              (entry->vehicle_mask &
               (1u << static_cast<unsigned>(
                   result.context - MDKR_CHARACTER_PREVIEW_CAR))) != 0u));
        const bool valid =
            contextSupported &&
            sourceSha256 == characterDigestHex(entry->source_sha256) &&
            launcherOwnedCapture && !portraitSourceHandoff &&
            !interactiveStudio && !representativeMotionReview &&
            motionReview == nullptr &&
            result.version == MDKR_CHARACTER_PREVIEW_RESULT_VERSION &&
            result.started && result.warmup_complete &&
            result.donor_reference == 1 &&
            result.donor_reference_batches != 0u &&
            result.reference_draws != 0u &&
            result.reference_primitives != 0u &&
            result.replacement_draws == 0u &&
            result.replacement_primitives == 0u &&
            result.hidden_donor_batches == 0u &&
            result.players == 1 &&
            result.context >= MDKR_CHARACTER_PREVIEW_SELECT &&
            result.context <= MDKR_CHARACTER_PREVIEW_PLANE &&
            result.pose == expectedPose && pose != nullptr &&
            result.pose_phase_milli == 500u &&
            result.transition_from_pose ==
                MDKR_CHARACTER_PREVIEW_POSE_LIVE &&
            result.transition_from_phase_milli == 0u &&
            result.inspection_pose_ticks != 0u &&
            result.inspection_pose_fallback_ticks <=
                result.inspection_pose_ticks &&
            result.transition_from_motion_source >
                MDKR_CHARACTER_PREVIEW_MOTION_NONE &&
            result.transition_from_motion_source <
                MDKR_CHARACTER_PREVIEW_MOTION_COUNT &&
            result.transition_to_motion_source ==
                MDKR_CHARACTER_PREVIEW_MOTION_NONE &&
            result.view_yaw_degrees >= -180 &&
            result.view_yaw_degrees <= 180 &&
            result.view_pitch_degrees >=
                MDKR_WORKSHOP_PREVIEW_PITCH_MIN_DEGREES &&
            result.view_pitch_degrees <=
                MDKR_WORKSHOP_PREVIEW_PITCH_MAX_DEGREES &&
            (result.context != MDKR_CHARACTER_PREVIEW_SELECT ||
             (result.view_yaw_degrees == 0 &&
              result.view_pitch_degrees == 0)) &&
            (!guidedComparison ||
             (result.view_yaw_degrees == expectedComparisonYaw &&
              result.view_pitch_degrees == 0)) &&
            result.lighting == MDKR_WORKSHOP_PREVIEW_LIGHTING_NEUTRAL &&
            ((result.view_yaw_degrees == 0 &&
              result.view_pitch_degrees == 0)
                 ? result.camera_override_ticks == 0u
                 : result.camera_override_ticks != 0u) &&
            result.lighting_override_draws == 0u &&
            result.capture_requested && result.capture_armed &&
            result.capture_written &&
            result.capture_kind == MDKR_CHARACTER_PREVIEW_CAPTURE_SCENE &&
            result.capture_stable_frames >=
                MDKR_CHARACTER_PREVIEW_CAPTURE_STABLE_FRAMES &&
            result.capture_png_bytes != 0u &&
            result.output_width >= 1u && result.output_width <= 16384u &&
            result.output_height >= 1u && result.output_height <= 16384u &&
            characterDigestTextValid(sourceSha256) &&
            characterDigestTextValid(fitSha256) &&
            characterDigestTextValid(presentationSha256) &&
            !sceneRegistration.empty() &&
            !capturePng.empty() &&
            characterCaptureIsLauncherOwned(packageId, capturePng) &&
            characterPreviewFitDiagnosticsValid(result) &&
            characterPreviewCameraProjectionValid(result) &&
            characterPreviewVehicleSurfaceValid(result) &&
            characterPreviewOpaqueVisibilityValid(result) &&
            characterPreviewProjectionValid(result) &&
            characterPreviewContactDiagnosticsValid(result) &&
            mdkr_modern_character_gpu_timing_metrics_valid(
                &result.gpu_timing) != 0;
        if (valid) {
            auto &captures = g_characterVisualCaptures[packageId];
            CharacterVisualReport::Capture capture{};
            capture.pngPath = capturePng;
            capture.sourceSha256 = sourceSha256;
            capture.fitSha256 = fitSha256;
            capture.presentationSha256 = presentationSha256;
            capture.sceneRegistrationSha256 = sceneRegistration;
            capture.context = characterPreviewResultContext(
                result.context);
            capture.pose = pose->label;
            capture.lighting = "Neutral";
            capture.renderProduct =
                CharacterVisualReport::RenderProduct::Scene;
            capture.subject =
                CharacterVisualReport::Subject::RetailDonor;
            capture.referenceDonor = donorName(entry->donor);
            capture.scene = static_cast<uint32_t>(disposition.scene);
            capture.players = 1u;
            capture.phaseMilli = 500u;
            capture.viewYawDegrees = result.view_yaw_degrees;
            capture.viewPitchDegrees = result.view_pitch_degrees;
            capture.width = result.output_width;
            capture.height = result.output_height;
            capture.stableFrames = result.capture_stable_frames;
            std::string captureError;
            const CharacterVisualReport::StoreResult stored =
                bindAndStoreInlineCharacterCapture(
                    packageId, captures, capture, captureError);
            capacityReached = stored ==
                CharacterVisualReport::StoreResult::Full;
            if (stored == CharacterVisualReport::StoreResult::Added ||
                stored == CharacterVisualReport::StoreResult::Replaced) {
                retained = true;
                retirePreviousInlineCharacterCaptures(packageId, capture);
                setStatus(
                    "Retail donor reference captured and labeled comparison-only. It cannot satisfy custom-character approval or portrait requirements.",
                    AppTheme::good());
            } else if (!capacityReached) {
                setStatus(
                    ("The donor reference was discarded because its PNG could not be validated: " +
                     captureError).c_str(),
                    AppTheme::accent());
            }
        }
        if (retained && guidedComparison) {
            CharacterComparisonRun &run = comparisonRun->second;
            run.awaitingDonor = false;
            std::string customCapturePath;
            if (prepareInlineCharacterCapture(
                    entry, result.context, customCapturePath)) {
                requestCharacterPreview(
                    entry, result.context, 1, expectedPose, 500u,
                    result.view_yaw_degrees,
                    result.view_pitch_degrees,
                    MDKR_WORKSHOP_PREVIEW_LIGHTING_NEUTRAL,
                    customCapturePath.c_str(),
                    MDKR_CHARACTER_PREVIEW_CAPTURE_SCENE,
                    MDKR_CHARACTER_PREVIEW_POSE_LIVE, 0u,
                    inlineCharacterStillRoute());
            }
            if (!g_characterPreviewRequested) {
                run.active = false;
                setStatus(
                    "The donor reference was retained, but the matching custom still could not be queued. Retry the registered comparison pair.",
                    AppTheme::accent());
            }
        } else if (comparisonRun != g_characterComparisonRuns.end() &&
                   comparisonRun->second.active &&
                   comparisonRun->second.awaitingDonor) {
            comparisonRun->second.active = false;
        }
        if (!retained) {
            std::string directory;
            if (characterPreviewCacheDirectory(directory)) {
                (void)CharacterPreviewCache::removeOwnedPath(
                    directory, packageId, capturePng);
            }
            if (!valid) {
                setStatus(
                    "The donor reference returned inconsistent comparison metadata and was discarded. No custom-character evidence changed.",
                    AppTheme::bad());
            } else if (capacityReached) {
                setStatus(
                    "The donor reference was discarded because the visual report tray reached its safety capacity. Export or clear captures, then try again.",
                    AppTheme::accent());
            }
        }
        return;
    }
    if (result.donor_reference != 0 ||
        result.donor_reference_batches != 0u ||
        result.reference_draws != 0u ||
        result.reference_primitives != 0u) {
        setStatus(
            "A donor-reference result reached a custom-character route and was rejected. No evidence changed.",
            AppTheme::bad());
        return;
    }
    auto comparisonRun = g_characterComparisonRuns.find(packageId);
    const bool completingComparison =
        comparisonRun != g_characterComparisonRuns.end() &&
        comparisonRun->second.active &&
        !comparisonRun->second.awaitingDonor &&
        comparisonRun->second.context == result.context &&
        comparisonRun->second.sourceSha256 == sourceSha256 &&
        comparisonRun->second.fitSha256 == fitSha256 &&
        comparisonRun->second.presentationSha256 == presentationSha256 &&
        result.players == 1 && result.pose_phase_milli == 500u &&
        result.view_yaw_degrees ==
            (result.context == MDKR_CHARACTER_PREVIEW_SELECT ? 0 : 180) &&
        result.view_pitch_degrees == 0 &&
        result.capture_kind == MDKR_CHARACTER_PREVIEW_CAPTURE_SCENE;
    if (comparisonRun != g_characterComparisonRuns.end() &&
        comparisonRun->second.active &&
        !comparisonRun->second.awaitingDonor) {
        /* This return consumes the second half of the bounded workflow even
         * when publication later refuses it; Retry always starts clean. */
        comparisonRun->second.active = false;
    }
    if (result.pose == MDKR_CHARACTER_PREVIEW_POSE_LIVE &&
        result.context >= MDKR_CHARACTER_PREVIEW_SELECT &&
        result.context <= MDKR_CHARACTER_PREVIEW_PLANE) {
        /* A new live result supersedes the frame the author inspected. Keep
         * contact-exception intent, but require the composed scene itself to
         * be acknowledged again before fit approval. */
        g_characterPendingSceneReviews[packageId] &=
            ~(1u << static_cast<unsigned>(
                result.context - MDKR_CHARACTER_PREVIEW_SELECT));
    }
    g_characterPreviewResults[packageId] = CharacterPreviewSessionResult{
        result, sourceSha256, fitSha256, presentationSha256, capturePng,
        launcherOwnedCapture,
    };
    if (interactiveStudio) {
        if (fitSha256.empty() ||
            result.version != MDKR_CHARACTER_PREVIEW_RESULT_VERSION ||
            !result.started || !result.warmup_complete ||
            !characterPreviewFitDiagnosticsValid(result) ||
            !characterPreviewJointDiagnosticsValid(result) ||
            !characterPreviewCameraProjectionValid(result) ||
            !characterPreviewVehicleSurfaceValid(result) ||
            !characterPreviewOpaqueVisibilityValid(result) ||
            !characterPreviewContactDiagnosticsValid(result)) {
            g_characterPreviewResults.erase(packageId);
            setStatus(
                "The exact Offset Studio returned without a current renderer fit; reopen this context before reviewing it.",
                AppTheme::accent());
        } else {
            setStatus(
                "Exact fit saved and measured. Review this context, then run its clean performance test when ready.",
                AppTheme::good());
        }
        return;
    }
    if (result.pose != MDKR_CHARACTER_PREVIEW_POSE_LIVE) {
        bool launcherCaptureRetained = false;
        const CharacterInspectionPose *pose =
            characterInspectionPose(result.pose);
        const CharacterInspectionLighting *lighting =
            characterInspectionLighting(result.lighting);
        const bool portraitHandoffValid = portraitSourceHandoff &&
            launcherOwnedCapture &&
            result.context > MDKR_CHARACTER_PREVIEW_SELECT &&
            result.context <= MDKR_CHARACTER_PREVIEW_PLANE &&
            result.players == 1 &&
            result.pose == MDKR_CHARACTER_PREVIEW_POSE_SELECT_IDLE &&
            result.pose_phase_milli == 500u &&
            result.transition_from_pose ==
                MDKR_CHARACTER_PREVIEW_POSE_LIVE &&
            result.view_yaw_degrees == 180 &&
            result.view_pitch_degrees == 0 &&
            result.lighting == MDKR_WORKSHOP_PREVIEW_LIGHTING_BRIGHT &&
            result.capture_kind ==
                MDKR_CHARACTER_PREVIEW_CAPTURE_MODEL_ALPHA;
        if (result.capture_written) {
            auto &captures = g_characterVisualCaptures[packageId];
            const std::string sceneRegistration =
                characterSceneRegistrationSignature(result);
            const bool recordValid =
                result.version == MDKR_CHARACTER_PREVIEW_RESULT_VERSION &&
                result.started && result.warmup_complete &&
                characterPreviewFitDiagnosticsValid(result) &&
                characterPreviewJointDiagnosticsValid(result) &&
                characterPreviewCameraProjectionValid(result) &&
                characterPreviewVehicleSurfaceValid(result) &&
                characterPreviewOpaqueVisibilityValid(result) &&
                characterPreviewProjectionValid(result) &&
                mdkr_modern_character_gpu_timing_metrics_valid(
                    &result.gpu_timing) != 0 &&
                characterPreviewContactDiagnosticsValid(result) &&
                result.capture_requested && result.capture_armed &&
                result.capture_kind >=
                    MDKR_CHARACTER_PREVIEW_CAPTURE_SCENE &&
                result.capture_kind <
                    MDKR_CHARACTER_PREVIEW_CAPTURE_COUNT &&
                result.capture_stable_frames >=
                    MDKR_CHARACTER_PREVIEW_CAPTURE_STABLE_FRAMES &&
                result.capture_png_bytes != 0u &&
                !capturePng.empty() && pose != nullptr && lighting != nullptr &&
                (!launcherOwnedCapture ||
                 characterCaptureIsLauncherOwned(packageId, capturePng)) &&
                result.context >= MDKR_CHARACTER_PREVIEW_SELECT &&
                result.context <= MDKR_CHARACTER_PREVIEW_PLANE &&
                result.players >= 1 && result.players <= 4 &&
                result.pose_phase_milli <= 1000u &&
                result.inspection_pose_ticks != 0u &&
                result.inspection_pose_fallback_ticks <=
                    result.inspection_pose_ticks &&
                result.transition_from_pose ==
                    MDKR_CHARACTER_PREVIEW_POSE_LIVE &&
                result.transition_from_phase_milli == 0u &&
                result.inspection_transition_switches == 0u &&
                result.inspection_transition_blending_ticks == 0u &&
                result.inspection_transition_completions == 0u &&
                result.transition_from_motion_source >
                    MDKR_CHARACTER_PREVIEW_MOTION_NONE &&
                result.transition_from_motion_source <
                    MDKR_CHARACTER_PREVIEW_MOTION_COUNT &&
                result.transition_to_motion_source ==
                    MDKR_CHARACTER_PREVIEW_MOTION_NONE &&
                result.view_yaw_degrees >= -180 &&
                result.view_yaw_degrees <= 180 &&
                result.view_pitch_degrees >=
                    MDKR_WORKSHOP_PREVIEW_PITCH_MIN_DEGREES &&
                result.view_pitch_degrees <=
                    MDKR_WORKSHOP_PREVIEW_PITCH_MAX_DEGREES &&
                (result.context != MDKR_CHARACTER_PREVIEW_SELECT ||
                 (result.view_yaw_degrees == 0 &&
                  result.view_pitch_degrees == 0 &&
                  result.camera_override_ticks == 0u)) &&
                ((result.view_yaw_degrees == 0 &&
                  result.view_pitch_degrees == 0) ||
                 result.camera_override_ticks != 0u) &&
                result.lighting >=
                    MDKR_WORKSHOP_PREVIEW_LIGHTING_NEUTRAL &&
                result.lighting < MDKR_WORKSHOP_PREVIEW_LIGHTING_COUNT &&
                (result.lighting ==
                     MDKR_WORKSHOP_PREVIEW_LIGHTING_NEUTRAL
                     ? result.lighting_override_draws == 0u
                     : result.lighting_override_draws != 0u) &&
                result.output_width >= 1u &&
                result.output_width <= 16384u &&
                result.output_height >= 1u &&
                result.output_height <= 16384u &&
                characterDigestTextValid(sourceSha256) &&
                characterDigestTextValid(fitSha256);
            if (recordValid &&
                (!portraitSourceHandoff || portraitHandoffValid)) {
                CharacterVisualReport::Capture capture{};
                capture.pngPath = capturePng;
                capture.sourceSha256 = sourceSha256;
                capture.fitSha256 = fitSha256;
                capture.presentationSha256 = presentationSha256;
                capture.scene = static_cast<uint32_t>(disposition.scene);
                capture.context = characterPreviewResultContext(result.context);
                capture.pose = pose->label;
                capture.lighting = lighting->label;
                capture.renderProduct =
                    result.capture_kind ==
                            MDKR_CHARACTER_PREVIEW_CAPTURE_MODEL_ALPHA
                        ? CharacterVisualReport::RenderProduct::ModelAlpha
                        : CharacterVisualReport::RenderProduct::Scene;
                if (capture.renderProduct ==
                    CharacterVisualReport::RenderProduct::Scene) {
                    capture.sceneRegistrationSha256 = sceneRegistration;
                }
                capture.players = static_cast<uint32_t>(result.players);
                capture.phaseMilli = result.pose_phase_milli;
                capture.viewYawDegrees = result.view_yaw_degrees;
                capture.viewPitchDegrees = result.view_pitch_degrees;
                capture.width = result.output_width;
                capture.height = result.output_height;
                capture.stableFrames = result.capture_stable_frames;
                capture.exactPose = result.inspection_pose_ticks != 0u &&
                    result.inspection_pose_fallback_ticks == 0u;
                if (result.fit_projection_valid) {
                    static_assert(
                        CharacterVisualReport::kFitProjectionPoints ==
                            MDKR_CHARACTER_PREVIEW_PROJECTION_POINTS,
                        "capture report and engine projection point counts must match");
                    capture.fitProjection.valid = true;
                    capture.fitProjection.width =
                        result.fit_projection_width;
                    capture.fitProjection.height =
                        result.fit_projection_height;
                    capture.fitProjection.primitiveDraws =
                        result.fit_projection_primitive_draws;
                    for (unsigned component = 0u; component < 4u;
                         ++component) {
                        capture.fitProjection.viewport[component] =
                            result.fit_projection_viewport[component];
                        capture.fitProjection.scissor[component] =
                            result.fit_projection_scissor[component];
                    }
                    for (unsigned point = 0u;
                         point < MDKR_CHARACTER_PREVIEW_PROJECTION_POINTS;
                         ++point) {
                        capture.fitProjection.pixelMilli[point][0] =
                            result.fit_projection_pixel_milli[point][0];
                        capture.fitProjection.pixelMilli[point][1] =
                            result.fit_projection_pixel_milli[point][1];
                        capture.fitProjection.depthMillionths[point] =
                            result.fit_projection_depth_millionths[point];
                        capture.fitProjection.clipFlags[point] =
                            result.fit_projection_clip_flags[point];
                    }
                }
                std::string captureError;
                CharacterVisualReport::StoreResult stored =
                    CharacterVisualReport::StoreResult::Full;
                bool captureBound = false;
                stored = launcherOwnedCapture
                    ? bindAndStoreInlineCharacterCapture(
                          packageId, captures, capture, captureError)
                    : CharacterVisualReport::bindAndStore(
                          captures, capture, captureError);
                captureBound =
                    stored == CharacterVisualReport::StoreResult::Added ||
                    stored == CharacterVisualReport::StoreResult::Replaced;
                if (!captureBound &&
                    stored == CharacterVisualReport::StoreResult::Full &&
                    portraitHandoffValid) {
                    /* Portrait handoff remains useful when the report tray is
                     * full. Bind it for the reversible editor without
                     * exceeding the tray's safety capacity. */
                    captureBound = CharacterVisualReport::bindPng(
                        capture, captureError);
                }
                if (captureBound) {
                    launcherCaptureRetained = launcherOwnedCapture;
                    if (launcherOwnedCapture &&
                        (stored ==
                             CharacterVisualReport::StoreResult::Added ||
                         stored ==
                             CharacterVisualReport::StoreResult::Replaced)) {
                        retirePreviousInlineCharacterCaptures(
                            packageId, capture);
                    }
                    if (portraitHandoffValid) {
                        g_characterPendingPortraitSources[packageId] = {
                            capture.pngPath, capture.pngSha256, true,
                        };
                        persistCharacterWorkshopTab(
                            CharacterWorkshopTab::Identity, true);
                    }
                    const bool comparisonRegistered =
                        completingComparison &&
                        std::any_of(
                            captures.begin(), captures.end(),
                            [&capture](const auto &candidate) {
                                return CharacterVisualReport::
                                    registeredComparison(
                                        capture, candidate);
                            });
                    setStatus(
                        completingComparison
                            ? comparisonRegistered
                                ? "Registered donor/custom comparison ready. The overlay uses identical renderer-authenticated pixel coordinates."
                                : "Both comparison frames were retained, but their renderer witnesses differ. No overlay was inferred; retry the pair after the scene is stable."
                        : portraitHandoffValid
                            ? "Portrait model capture validated and returned to the reversible framing workflow."
                        : launcherOwnedCapture
                            ? "Exact still captured, digest-bound, and returned inline."
                            : "Inspection PNG saved, digest-bound, and added to the visual report tray.",
                        completingComparison && !comparisonRegistered
                            ? AppTheme::accent() : AppTheme::good());
                } else {
                    setStatus(
                        ((launcherOwnedCapture
                              ? "The inline still was discarded because it could not be validated: "
                              : "The PNG was saved, but it could not enter the session tray: ") +
                         captureError).c_str(),
                        AppTheme::accent());
                }
            } else {
                /* A matching record cannot remain valid after this path was
                 * recreated, even when the returned metadata is rejected. */
                const auto existing = std::find_if(
                    captures.begin(), captures.end(),
                    [&capturePng](
                        const CharacterVisualReport::Capture &capture) {
                        return capture.pngPath == capturePng;
                    });
                if (existing != captures.end()) captures.erase(existing);
                setStatus(
                        portraitSourceHandoff
                            ? "The portrait source was discarded because its exact inspection metadata was inconsistent."
                        : launcherOwnedCapture
                        ? recordValid
                            ? "The inline still was discarded because the session report is full; export or clear the tray before trying again."
                            : "The inline still was discarded because its inspection metadata was inconsistent."
                        : recordValid
                            ? "The PNG was saved, but the session report reached its safety capacity; export or clear the tray before capturing more."
                            : "The PNG was saved, but inconsistent inspection metadata prevented adding it to the report tray.",
                    AppTheme::accent());
            }
        } else if (completingComparison) {
            setStatus(
                "The donor reference was retained, but the matching custom frame did not complete. Retry the registered comparison pair; no overlay or approval was inferred.",
                AppTheme::accent());
        }
        if (launcherOwnedCapture && !launcherCaptureRetained) {
            std::string directory;
            if (characterPreviewCacheDirectory(directory)) {
                (void)CharacterPreviewCache::removeOwnedPath(
                    directory, packageId, capturePng);
            }
        }
        if (std::getenv("MDKR_APP_UI_TRACE") != nullptr) {
            std::fprintf(
                stderr,
                "[app-ui] character-pose-inspection session-only=1 package=%s context=%u players=%d pose=%d phase=%u transitionFrom=%d transitionPhase=%u switches=%llu completed=%llu source=%d,%d capture=%d kind=%d tray=%zu\n",
                packageId.c_str(), static_cast<unsigned>(result.context),
                result.players, static_cast<int>(result.pose),
                result.pose_phase_milli,
                static_cast<int>(result.transition_from_pose),
                result.transition_from_phase_milli,
                result.inspection_transition_switches,
                result.inspection_transition_completions,
                static_cast<int>(result.transition_from_motion_source),
                static_cast<int>(result.transition_to_motion_source),
                result.capture_written,
                static_cast<int>(result.capture_kind),
                g_characterVisualCaptures[packageId].size());
        }
        return;
    }
    if (result.pose_phase_milli != 0u ||
        result.transition_from_pose !=
            MDKR_CHARACTER_PREVIEW_POSE_LIVE ||
        result.transition_from_phase_milli != 0u ||
        result.inspection_pose_ticks != 0u ||
        result.inspection_pose_fallback_ticks != 0u ||
        result.inspection_transition_switches != 0u ||
        result.inspection_transition_blending_ticks != 0u ||
        result.inspection_transition_completions != 0u ||
        result.transition_from_blend_milli != 0u ||
        result.transition_to_blend_milli != 0u ||
        result.transition_from_motion_source !=
            MDKR_CHARACTER_PREVIEW_MOTION_NONE ||
        result.transition_to_motion_source !=
            MDKR_CHARACTER_PREVIEW_MOTION_NONE ||
        result.view_yaw_degrees != 0 ||
        result.view_pitch_degrees != 0 ||
        result.lighting != MDKR_WORKSHOP_PREVIEW_LIGHTING_NEUTRAL ||
        result.camera_override_ticks != 0u ||
        result.lighting_override_draws != 0u ||
        result.capture_kind != MDKR_CHARACTER_PREVIEW_CAPTURE_SCENE ||
        result.capture_requested || result.capture_armed ||
        result.capture_stable_frames != 0u || result.capture_written ||
        result.capture_png_bytes != 0u || !capturePng.empty()) {
        if (std::getenv("MDKR_APP_UI_TRACE") != nullptr) {
            std::fprintf(
                stderr,
                "[app-ui] character-preview-result rejected-evidence=mixed-mode package=%s phase=%u poseTicks=%llu poseFallback=%llu\n",
                packageId.c_str(), result.pose_phase_milli,
                result.inspection_pose_ticks,
                result.inspection_pose_fallback_ticks);
        }
        setStatus(
            "The engine returned mixed live-test and pose-inspection fields; the session is visible for diagnosis but no durable performance evidence was saved.",
            AppTheme::bad());
        return;
    }
    if (result.version != MDKR_CHARACTER_PREVIEW_RESULT_VERSION ||
        !result.started || !characterPreviewFitDiagnosticsValid(result) ||
        !characterPreviewJointDiagnosticsValid(result) ||
        !characterPreviewCameraProjectionValid(result) ||
        !characterPreviewVehicleSurfaceValid(result) ||
        !characterPreviewOpaqueVisibilityValid(result) ||
        !characterPreviewProjectionValid(result) ||
        !characterPreviewContactDiagnosticsValid(result)) {
        if (std::getenv("MDKR_APP_UI_TRACE") != nullptr) {
            std::fprintf(
                stderr,
                "[app-ui] character-preview-result rejected-evidence=spatial-contact-contract package=%s version=%u started=%d fit=%d camera=%d cameraFlags=%x surface=%d crossingPairs=%u contactMask=%x\n",
                packageId.c_str(), result.version, result.started,
                result.fit_diagnostics_valid,
                result.camera_projection_valid,
                result.camera_bounds_clip_flags,
                result.vehicle_surface_valid,
                result.vehicle_surface_crossing_pairs,
                result.contact_witness_mask);
        }
        setStatus(
            "The engine returned an invalid renderer fit, gameplay-camera, vehicle-surface, or contact contract; the session is visible for diagnosis but no durable performance evidence was saved.",
            AppTheme::bad());
        return;
    }
    if (!mdkr_modern_character_gpu_timing_metrics_valid(
            &result.gpu_timing)) {
        if (std::getenv("MDKR_APP_UI_TRACE") != nullptr) {
            std::fprintf(
                stderr,
                "[app-ui] character-preview-result rejected-evidence=gpu-timing-contract package=%s timingVersion=%u status=%u scopes=%x\n",
                packageId.c_str(), result.gpu_timing.version,
                characterGpuTimingStatusRepresentation(result.gpu_timing),
                result.gpu_timing.supported_scopes);
        }
        setStatus(
            "The engine returned an invalid GPU timing contract; the session is visible for diagnosis but no durable performance evidence was saved.",
            AppTheme::bad());
        return;
    }
    if (result.context >= MDKR_CHARACTER_PREVIEW_SELECT &&
        result.context <= MDKR_CHARACTER_PREVIEW_PLANE &&
        result.players >= 1 && result.players <= 4) {
        g_characterTestEvidenceSelectedCell[packageId] =
            (static_cast<unsigned>(result.context) - 1u) * 4u +
            static_cast<unsigned>(result.players - 1);
    }
    loadCharacterTestEvidence();
    if (!g_characterTestEvidenceWritable) return;
    CharacterTestEvidenceStore::Inventory replacement =
        g_characterTestEvidence;
    CharacterTestEvidenceStore::Evidence evidence =
        characterTestEvidenceFromResult(
            packageId, sourceSha256, fitSha256, presentationSha256, result);
    std::string error;
    if (!CharacterTestEvidenceStore::upsert(
            replacement, evidence, error)) {
        g_characterTestEvidenceError = error;
        setStatus(
            ("The exact test returned, but its evidence was invalid and was not saved: " +
             error).c_str(),
            AppTheme::bad());
        return;
    }
    if (!replaceCharacterTestEvidence(std::move(replacement))) {
        setStatus(
            ("The exact test returned for this session, but its evidence could not be saved: " +
             g_characterTestEvidenceError).c_str(),
            AppTheme::bad());
        return;
    }
    if (std::getenv("MDKR_APP_UI_TRACE") != nullptr) {
        std::fprintf(
            stderr,
            "[app-ui] character-test-evidence saved=1 package=%s context=%u players=%u qualified=%d records=%zu\n",
            packageId.c_str(), evidence.context, evidence.players,
            CharacterTestEvidenceStore::qualified(evidence) ? 1 : 0,
            g_characterTestEvidence.records.size());
    }
}

void Settings_cancelAudioPreview() {
    mdkr_audio_config_runtime_cancel_preview();
    for (MdkrVideoKey key : {MDKR_AUDIO_MASTER_VOLUME,
                             MDKR_AUDIO_MUSIC_VOLUME,
                             MDKR_AUDIO_EFFECTS_VOLUME}) {
        EditState &edit = g_edits[static_cast<size_t>(key)];
        edit.initialized = false;
        edit.active = false;
        edit.dirty = false;
        edit.error.clear();
    }
}

void Settings_loadUiScalePreference() {
    const std::string stored = AppConfig::get("ui_scale", "1.0");
    float parsed = 1.0f;
    const float scale = AppUi_parseScale(stored.c_str(), &parsed) ? parsed : 1.0f;
    AppTheme::setUiScale(scale);
    g_uiScaleEdit = scale;
    g_uiScaleInitialized = true;
    g_uiScaleDirty = false;
    g_uiScaleError.clear();
    g_smokeGamepadFocusUsed = false;
    if (std::getenv("MDKR_APP_UI_TRACE")) {
        std::fprintf(stderr, "[app-ui] ui-scale loaded=%.2f\n",
                     static_cast<double>(scale));
    }
}

bool Settings_smokeFrameLimitCenter(int *x, int *y) {
    if (!x || !y || !g_frameLimitRectValid) return false;
    *x = static_cast<int>((g_frameLimitRectMin.x + g_frameLimitRectMax.x) * 0.5f);
    *y = static_cast<int>((g_frameLimitRectMin.y + g_frameLimitRectMax.y) * 0.5f);
    return true;
}

bool Settings_smokeFrameLimitPopup(int *focusedIndex) {
    if (!focusedIndex || !g_frameLimitPopupOpen) return false;
    *focusedIndex = g_frameLimitFocusedIndex;
    return true;
}

int Settings_smokeFrameLimitDownSteps(const char *from, const char *to) {
    if (!from || !to) return -1;
    int fromIndex = -1;
    int toIndex = -1;
    for (int i = 0; i < static_cast<int>(std::size(kFrameLimit)); ++i) {
        if (std::strcmp(kFrameLimit[i].value, from) == 0) fromIndex = i;
        if (std::strcmp(kFrameLimit[i].value, to) == 0) toIndex = i;
    }
    return fromIndex >= 0 && toIndex >= fromIndex ? toIndex - fromIndex : -1;
}

bool Settings_smokeFrameLimitRetryCenter(int *x, int *y) {
    if (!x || !y || !g_frameLimitRetryRectValid) return false;
    *x = static_cast<int>(
        (g_frameLimitRetryRectMin.x + g_frameLimitRetryRectMax.x) * 0.5f);
    *y = static_cast<int>(
        (g_frameLimitRetryRectMin.y + g_frameLimitRetryRectMax.y) * 0.5f);
    return true;
}

bool Settings_smokePresentationPaceCenter(const char *pace, int *x, int *y) {
    if (!pace || !x || !y) return false;
    const int resolved = mdkr_video_presentation_pace_from_name(pace);
    if (resolved <= 0 ||
        resolved >= static_cast<int>(std::size(g_paceRectValid)) ||
        !g_paceRectValid[resolved]) {
        return false;
    }
    *x = static_cast<int>(
        (g_paceRectMin[resolved].x + g_paceRectMax[resolved].x) * 0.5f);
    *y = static_cast<int>(
        (g_paceRectMin[resolved].y + g_paceRectMax[resolved].y) * 0.5f);
    return true;
}

bool Settings_smokeUiScaleRect(int *minX, int *minY, int *maxX, int *maxY) {
    if (!minX || !minY || !maxX || !maxY || !g_uiScaleRectValid) return false;
    *minX = static_cast<int>(g_uiScaleRectMin.x);
    *minY = static_cast<int>(g_uiScaleRectMin.y);
    *maxX = static_cast<int>(g_uiScaleRectMax.x);
    *maxY = static_cast<int>(g_uiScaleRectMax.y);
    return true;
}

void Settings_dumpSchemaContract() {
    std::printf(
        "[app] frame-limit UI contract: recommended=\"%s\" group=\"%s\" "
        "caveat=\"%s\"\n",
        kOriginalFrameLimitLabel, kModernFrameLimitGroup,
        kFrameLimitHelp);

    /*
     * The control inventory, one row per schema key: the name a voice would
     * say, the value it would say, and whether the product offers the setting
     * at all.
     *
     * tests/check_a11y_shell.py grades the walk against THIS, rather than
     * against a list kept in the test, which is the whole point: a setting
     * added tomorrow gets a row here the moment it has a schema entry, and the
     * gate then demands an utterance for it without anybody remembering to
     * extend the test. The label and value come from the same displayValue()
     * the announcement uses, so the expectation and the utterance cannot drift
     * apart while both still look right.
     *
     * Visibility is reported for the qualified WebGPU renderer with widescreen
     * engaged -- the shipped configuration. A diagnostic OpenGL session offers
     * one setting MORE (MSAA), which can only ever add an utterance the gate
     * did not require, never remove one it did.
     */
    const MdkrVideoConfig *config = mdkr_video_config_desired();
    for (int i = 0; i < MDKR_VIDEO_KEY_COUNT; ++i) {
        const MdkrVideoKey     key = static_cast<MdkrVideoKey>(i);
        const MdkrVideoSchema *s   = mdkr_video_schema(key);
        if (s == nullptr) continue;
        char value[MDKR_VIDEO_STRING_MAX];
        displayValue(key, s, config != nullptr ? &config->values[i] : nullptr,
                     value, sizeof(value));
        /* The DRAWN label -- the Copy table's where one exists -- for the same
         * reason the value comes from displayValue(): the gate's expectation
         * and the on-screen text must be one string, and the announcement
         * speaks the drawn label. */
        const Copy *copy = copyFor(key);
        std::printf(
            "[app-a11y] control key=%s visible=%d label=\"%s\" value=\"%s\"\n",
            s->name,
            AppUi_videoSettingVisible(key, /*webGpuRenderer=*/true,
                                      /*legacyStretchActive=*/false) ? 1 : 0,
            copy != nullptr ? copy->label : s->label, value);
        // Report the same finite-domain route used by drawKey(), not a second
        // inventory. This makes an accidental fallback to free text testable.
        Options options;
        if (optionsFor(key, options)) {
            std::printf("[app] choices key=%s count=%d", s->name, options.count);
            for (int option = 0; option < options.count; ++option) {
                std::printf(" %s=\"%s\"", options.items[option].value,
                            options.items[option].label);
            }
            std::printf("\n");
        }
    }
}

bool Settings_restartPending() {
    /* Keep the launcher, overlay, and original in-game settings on one
     * predicate. In particular, Video.Mode is a preset label rather than a
     * staged engine override; the runtime helper correctly evaluates the
     * individual values expanded by that preset. */
    return mdkr_video_config_restart_pending() != 0;
}

void Settings_requestControllerSection() {
    g_controllerSectionRequested = true;
}

const char *Settings_effectiveLabel(int videoKey) {
    const MdkrVideoKey key = static_cast<MdkrVideoKey>(videoKey);
    // Video.Mode is a preset label the player recognizes as the presentation
    // style ("Restored"); the individual keys read their own option label.
    const MdkrVideoValue *value = desired(key);
    if (value == nullptr) return "";
    return optionLabel(key, value->text);
}

const char *Settings_effectivePaceLabel() {
    // The frame rate is now ONE merged control (drawFrameRate) with the choices
    // Original / Smooth / Custom, so its effective value is named in that
    // vocabulary rather than by the underlying Frame limit option label the
    // player no longer selects directly. Read from the desired (effective)
    // config so a staged edit shows immediately, exactly like the raw labels.
    const MdkrVideoConfig *config = mdkr_video_config_desired();
    if (config == nullptr) return "";
    const MdkrPresentationPace pace = mdkr_video_presentation_pace(config);
    for (const PaceChoice &choice : kPaceChoices) {
        if (choice.pace == pace) return choice.label;
    }
    // Custom is a revealed state rather than a kPaceChoices value; it shares its
    // one spelling with the "Custom" radio in drawFrameRate.
    return "Custom";
}

int Settings_collectStagedOverrides(const char **out, int cap) {
    // Static storage: the caller (the launcher's boot config) holds these
    // pointers until mdkr64_engine_boot copies them, which happens on the same
    // stack, so a per-key static buffer is both sufficient and lifetime-safe.
    static char s_buf[MDKR_VIDEO_KEY_COUNT][MDKR_VIDEO_NAME_MAX + MDKR_VIDEO_STRING_MAX + 2];
    int n = 0;
    for (int i = 0; i < MDKR_VIDEO_KEY_COUNT && n < cap; ++i) {
        MdkrVideoKey k = (MdkrVideoKey)i;
        const MdkrVideoSchema *s = mdkr_video_schema(k);
        if (!s || s->scope != MDKR_VIDEO_SCOPE_RESTART) continue;
        if (!differsFromLive(k, s)) continue;
        // Video.Mode is a preset label, not a single engine override. Passing it
        // here would re-expand the preset over the individual keys the player
        // just staged; the engine reads the already-persisted resolved config.
        if (k == MDKR_VIDEO_MODE) continue;
        char v[MDKR_VIDEO_STRING_MAX];
        formatValue(k, s, desired(k), v, sizeof(v));
        std::snprintf(s_buf[n], sizeof(s_buf[n]), "%s=%s", s->name, v);
        out[n] = s_buf[n];
        ++n;
    }
    return n;
}

bool Settings_draw(SDL_Window *window, bool compact) {
    bool changed = false;
    g_frameLimitPopupOpen = false;
    g_frameLimitFocusedIndex = -1;
    /*
     * Every widget-rect flag starts each frame false, and only the widget's own
     * submission can raise it again. This is the half IsItemVisible() cannot
     * cover: a collapsed section returns from here without ever reaching the
     * widget, so nothing would run to lower a flag left true by an earlier
     * frame -- which is precisely the stale latch this panel used to have. The
     * whole set is cleared in one place so a rect added later is either listed
     * here or is not per-frame, rather than being quietly sticky.
     *
     * Limit worth knowing: this is per Settings_draw() call, so it says nothing
     * about frames where the panel is not drawn at all (another launcher tab,
     * or the overlay with settings hidden). Every scripted gate pins
     * MDKR_APP_PANEL=Settings, so for them "drawn" and "this frame" coincide.
     */
    g_frameLimitRectValid = false;
    g_frameLimitRetryRectValid = false;
    g_uiScaleRectValid = false;
    g_sectionsDrawn = 0;
    for (bool &paceValid : g_paceRectValid) paceValid = false;
    MdkrVideoRuntimeResult windowResult = MDKR_VIDEO_RUNTIME_INVALID;
    bool windowResultFresh = false;
    if (AppWindow_consumeCompleted(&windowResult, &windowResultFresh)) {
        const MdkrVideoSchema *schema = mdkr_video_schema(MDKR_WINDOW_MODE);
        EditState &edit = g_edits[static_cast<size_t>(MDKR_WINDOW_MODE)];
        // A stale completion still resynchronizes the widget from the
        // authoritative desired value; only its status line is suppressed.
        if (windowResultFresh) reportResult(windowResult, schema);
        if (resultSucceeded(windowResult)) {
            edit.dirty = false;
            edit.initialized = false;
            edit.error.clear();
            changed = true;
        } else if (windowResultFresh) {
            edit.error = g_status;
        }
    }
    const bool controllerSettingsSmoke =
        std::getenv("MDKR_APP_SMOKE_CONTROLLER_SETTINGS") != nullptr;
    const bool smokeControllerRestore =
        std::getenv("MDKR_APP_SMOKE_CONTROLLER_RESTORE") != nullptr;
    /* Both scripted pacing gates need the same thing: the frame-rate controls
     * in view without scrolling, so a queued click lands on the widget rather
     * than on whatever the panel happened to have scrolled under it. */
    const bool selectingFrameLimit =
        std::getenv("MDKR_APP_SMOKE_SELECT_FRAME_LIMIT") != nullptr ||
        std::getenv("MDKR_APP_SMOKE_SELECT_PRESENTATION_PACE") != nullptr;
    /* Same need, one group further down: the scripted interface-scale drag
     * holds a real pointer on the slider, so the slider has to be on screen
     * without a scroll the script has no way to perform. */
    const bool draggingUiScale =
        std::getenv("MDKR_APP_SMOKE_UI_SCALE_DRAG") != nullptr;
    int controllerMappingWidgets = 0;
    int controllerRumbleWidgets = 0;
    bool controllerRestoreAvailable = false;
    bool controllerRestoreSucceeded = false;

    const bool webGpuRenderer =
        mdkr_render_backend() == MDKR_BACKEND_WEBGPU;
    /* Video.Widescreen is normally hidden because no preset ever selects its
     * 0 branch (see AppUi_videoSettingVisible). A config that already resolved
     * to 0 is the exception: the player is looking at the pre-widescreen
     * stretch and needs a control to leave it. */
    const bool legacyStretchActive =
        mdkr_video_config_current()
            ->values[MDKR_VIDEO_WIDESCREEN].number == 0.0f;

    /*
     * WHY THE GROUPS ARE NAMED HERE AND NOT TAKEN FROM MdkrVideoCategory.
     *
     * The schema's categories answer "which subsystem owns this key", which is
     * the right question for the config layer and the wrong one for a player.
     * It put Camera and Menu languages under Presentation because both are
     * published by the presentation path, and it put Simulation cadence beside
     * Frame limit under Pacing because both are about time -- which is exactly
     * the confusion behind the reports that Enhanced was a frame-rate setting.
     *
     * So the page groups by what a player came to do, and the schema stays the
     * source of truth for everything else. The safety net is `drawnKey`: any
     * visible key no group claims is rendered under Other settings at the
     * bottom, so a key added to the schema tomorrow can never silently vanish
     * from the panel the way an explicit list would normally allow.
     */
    bool drawnKey[MDKR_VIDEO_KEY_COUNT] = {};
    const auto visible = [&](MdkrVideoKey key) {
        return AppUi_videoSettingVisible(key, webGpuRenderer,
                                         legacyStretchActive);
    };
    const auto row = [&](MdkrVideoKey key) {
        if (!visible(key)) return;
        // Keys the routing policy assigns to a dedicated section
        // (Accessibility, Enhancements, Content) are drawn by that section,
        // never under a group here -- one owner per control.
        if (AppUi_settingsSection(key) != AppUiSettingsSection::Category) return;
        drawnKey[static_cast<size_t>(key)] = true;
        changed |= drawKey(window, key, compact);
    };
    const auto flagsFor = [](bool open) {
        return open ? ImGuiTreeNodeFlags_DefaultOpen : ImGuiTreeNodeFlags_None;
    };

    /* The packaged-default proof. verify_unsigned_release greps this exact
     * row, and check_app_ui_input's recovery arm reads it after a reload. It
     * reports the DESIRED value from the config, deliberately not the drawn
     * row: the frame-limit control lives inside a collapsed-by-default tree,
     * and a proof of the shipped default must not depend on whether a player
     * (or a passive smoke) happened to open it. */
    if (std::getenv("MDKR_APP_UI_TRACE") != nullptr) {
        static bool tracedFrameLimit = false;
        const MdkrVideoValue *frameLimit = desired(MDKR_VIDEO_FRAME_LIMIT);
        if (!tracedFrameLimit && frameLimit != nullptr) {
            std::fprintf(stderr,
                         "[app-ui] frame-limit value=%s label=%s restartPending=%d\n",
                         frameLimit->text,
                         optionLabel(MDKR_VIDEO_FRAME_LIMIT, frameLimit->text),
                         Settings_restartPending() ? 1 : 0);
            std::fprintf(
                stderr,
                "[app-ui] frame-limit-contract recommended=\"%s\" "
                "group=\"%s\" caveat=\"%s\"\n",
                kOriginalFrameLimitLabel, kModernFrameLimitGroup,
                kFrameLimitHelp);
            tracedFrameLimit = true;
        }
    }

    if (mdkr_video_config_is_readonly()) {
        // Explicit --pure locks this session's resolved values. Timing and
        // smoothing are intentionally independent of art-direction presets,
        // so never describe a retained enhanced choice as "original".
        ui::CautionBox(
            "Original session — picture and timing are locked",
            "Frame limit, Motion smoothing, and Simulation cadence keep the values selected "
            "before launch, so a timing comparison stays honest. Sound, window and "
            "controller settings still work.");
        ui::Gap(ui::kGapM);
    }

    /*
     * NINE GROUPS, NAMED FOR WHAT A PLAYER CAME TO DO.
     *
     * There were eleven, and they answered three different questions. Picture,
     * Sound and Camera named a SUBSYSTEM. Accessibility and Gameplay named a
     * player CONCERN. App window named neither -- it was a lid over the window
     * mode, the update check and the developer-tools switch, which have nothing
     * to do with each other or with a window. Camera held exactly one row.
     *
     * Six of the eleven opened expanded, so the first screen was a wall rather
     * than a menu. Two open by default now -- Display, because it is what most
     * players came for, and Accessibility, because someone who needs it needs
     * it before they can use anything below it.
     *
     * See docs/architecture/launcher-design.md for the full mapping. The safety
     * net at the bottom is unchanged and still catches any visible key no group
     * claims, so regrouping cannot silently lose a setting.
     */
    const ImGuiTreeNodeFlags openUnlessScripted =
        flagsFor(!controllerSettingsSmoke && !draggingUiScale);

    // --- Display ------------------------------------------------------------
    if (drawSettingsSectionHeader(
            "Display",
            "Restored is the recommended default: widescreen and sharper "
            "output, with the original art direction untouched.",
            openUnlessScripted, compact)) {
        row(MDKR_VIDEO_MODE);
        // The preset's third state, said out loud. A default session reads
        // "Custom (Individual Settings)" -- a value that is not in the control's
        // own list -- and the page used to leave the player to work out why.
        const MdkrVideoValue *mode = desired(MDKR_VIDEO_MODE);
        if (mode != nullptr && std::strcmp(mode->text, "custom") == 0 &&
            !compact) {
            ui::TextSubtleWrapped(
                "Custom means your Graphics settings below no longer match any "
                "of the three presets. Choosing one here sets them all again.");
            ui::Gap(ui::kGapS);
        }
        if (webGpuRenderer) {
            // A chip, not a loose sentence. The unhealthy case already answers
            // this question with a card; the healthy one answered it with an
            // unanchored line of prose between two labelled rows. This is the
            // vocabulary the page already uses for a short fact about state.
            // The exact sentence tests/test_product_claim_boundaries.py pins:
            // this is a product CLAIM (WebGPU is the qualified path), not copy
            // to trim for shape. The chip carries it verbatim.
            ui::Chip("Graphics backend: WebGPU (recommended)",
                     AppTheme::good());
            ui::Gap(ui::kGapS);
        } else if (!compact) {
            if (ui::CardBegin("##renderer-warning", AppTheme::accent(), 0.0f)) {
                ImGui::PushStyleColor(ImGuiCol_Text, AppTheme::accent());
                ImGui::TextUnformatted("OpenGL diagnostic renderer active");
                ImGui::PopStyleColor();
                ui::TextSubtleWrapped(
                    "For the qualified visual path, use WebGPU with Restored.");
            }
            ui::CardEnd();
            ui::Gap(ui::kGapS);
        }

        const bool pacingVisible = visible(MDKR_VIDEO_FRAME_LIMIT) &&
                                   visible(MDKR_VIDEO_MOTION_SMOOTHING);
        if (pacingVisible) {
            changed |= drawFrameRate(window, compact, selectingFrameLimit);
            // drawFrameRate owns these three rows, so it owns claiming them:
            // the safety net below asks "did any group draw this key", and a
            // key drawn by a dedicated control is drawn.
            for (MdkrVideoKey key : {MDKR_VIDEO_FRAME_LIMIT,
                                     MDKR_VIDEO_MOTION_SMOOTHING,
                                     MDKR_VIDEO_ALLOW_TEARING}) {
                drawnKey[static_cast<size_t>(key)] = true;
            }
            if (std::getenv("MDKR_APP_UI_TRACE") != nullptr) {
                static bool tracedFrameRateControls = false;
                if (!tracedFrameRateControls) {
                    std::fprintf(
                        stderr,
                        "[app-ui] frame-rate-controls visible=1 "
                        "gameplay-accuracy-separated=1\n");
                    tracedFrameRateControls = true;
                }
            }
        }

        // The Camera group held this one row and nothing else. It changes what
        // you see and not how the game plays, so it belongs here; Camera shake
        // is an access need first and the routing policy keeps it under
        // Accessibility.
        row(MDKR_VIDEO_CAMERA_OBSTRUCTION);
        row(MDKR_VIDEO_GAMEPLAY_FOV);
        row(MDKR_VIDEO_ASPECT);
        row(MDKR_WINDOW_MODE);
        row(MDKR_VIDEO_WIDESCREEN);
        ImGui::Unindent(ui::kGapM);
    }

    // --- Graphics -----------------------------------------------------------
    if (drawSettingsSectionHeader(
            "Graphics",
            "Image quality only. None of these change the art direction.",
            flagsFor(false), compact)) {
        row(MDKR_VIDEO_RENDER_SCALE);
        row(MDKR_VIDEO_MSAA);
        row(MDKR_VIDEO_ANISOTROPY);
        row(MDKR_VIDEO_MIPMAPS);
        row(MDKR_VIDEO_HIRES_TEXT);
        row(MDKR_VIDEO_WORLD_SHADOWS);
        row(MDKR_VIDEO_REMASTER_FX);
        ImGui::Unindent(ui::kGapM);
    }

    // --- Audio --------------------------------------------------------------
    if (drawSettingsSectionHeader(
            "Audio", "Volume levels, remembered as you set them.",
            flagsFor(false), compact)) {
        row(MDKR_AUDIO_MASTER_VOLUME);
        row(MDKR_AUDIO_MUSIC_VOLUME);
        row(MDKR_AUDIO_EFFECTS_VOLUME);
        ImGui::Unindent(ui::kGapM);
    }

    // --- Controls -----------------------------------------------------------
    if (g_controllerSectionRequested) {
        ImGui::SetNextItemOpen(true, ImGuiCond_Always);
    }
    if (drawSettingsSectionHeader(
            "Controls",
            "Rumble, and which N64 button each control presses. The left "
            "stick is always steering.",
            flagsFor(controllerSettingsSmoke), compact)) {
        if (g_controllerSectionRequested) ImGui::SetScrollHereY(0.0f);
        row(MDKR_INPUT_RUMBLE_ENABLED);
        row(MDKR_INPUT_RUMBLE_PROFILE);
        if (visible(MDKR_INPUT_RUMBLE_ENABLED)) controllerRumbleWidgets++;
        if (visible(MDKR_INPUT_RUMBLE_PROFILE)) controllerRumbleWidgets++;
        // Shell preference, not a schema key, so it cannot arrive via row().
        // Routed like UI scale so "drawn in exactly one section" stays a
        // property tests/test_app_ui_policy.cpp can read.
        if (AppUi_shellPreferenceSection(
                AppUiShellPreference::MenuToggleButton) ==
            AppUiSettingsSection::Category) {
            changed |= drawMenuToggleButton(compact);
        }
        if (g_controllerSectionRequested) {
            ImGui::SetNextItemOpen(true, ImGuiCond_Always);
        }
        if (ImGui::TreeNodeEx("Button mapping",
                              ImGuiTreeNodeFlags_SpanAvailWidth |
                                  flagsFor(controllerSettingsSmoke))) {
            for (int i = MDKR_INPUT_CONTROLLER_A;
                 i <= MDKR_INPUT_CONTROLLER_RIGHT_STICK_RIGHT; ++i) {
                const MdkrVideoKey key = static_cast<MdkrVideoKey>(i);
                if (!visible(key)) continue;
                row(key);
                controllerMappingWidgets++;
            }
            const bool restorePressed = ImGui::Button(
                "Restore defaults", ui::kBtnWide());
            controllerRestoreAvailable = true;
            static bool smokeRestoreAttempted = false;
            const bool runSmokeRestore = controllerSettingsSmoke &&
                smokeControllerRestore && !smokeRestoreAttempted;
            if (restorePressed || runSmokeRestore) {
                if (runSmokeRestore) smokeRestoreAttempted = true;
                const bool restored = restoreControllerDefaults();
                controllerRestoreSucceeded |= restored;
                changed |= restored;
            }
            ImGui::TreePop();
        }
        ImGui::Unindent(ui::kGapM);
    }
    g_controllerSectionRequested = false;

    // --- Accessibility ------------------------------------------------------
    // Open by default: a player who needs it needs it before they can use
    // anything else on the page. Rows come from the routing policy, so an
    // accessibility key added tomorrow is drawn -- and voiced -- here.
    if (drawSettingsSectionHeader(
            "Accessibility",
            "How the game reads and speaks. None of these change how it "
            "plays.",
            flagsFor(draggingUiScale ||
                     (!controllerSettingsSmoke && !selectingFrameLimit)),
            compact)) {
        ImGui::Unindent(ui::kGapM);  // the section helper manages its own indent
        changed |= drawAccessibilitySection(window, compact, webGpuRenderer,
                                            legacyStretchActive);
    }

    // --- Gameplay -----------------------------------------------------------
    if (drawSettingsSectionHeader(
            "Gameplay",
            "The only settings on this page that change how the game plays.",
            flagsFor(false), compact)) {
        if (visible(MDKR_VIDEO_SIMULATION_CADENCE) && !compact) {
            const MdkrVideoValue *cadence =
                desired(MDKR_VIDEO_SIMULATION_CADENCE);
            const bool enhanced =
                cadence != nullptr &&
                std::strcmp(cadence->text, "enhanced") == 0;
            ui::CautionBox(
                enhanced ? "Enhanced is on — experimental, and races run off pace"
                         : "Enhanced is experimental and changes how the game plays",
                "Enhanced runs DKR's logic at 60 Hz instead of the 30 Hz it "
                "was written for. The boss rematches are winnable, but they "
                "still finish measurably off the pace the game intends, "
                "because the original physics is written around the 30 Hz "
                "step rather than derived from it. Original is exact — "
                "bit for bit the game as it shipped. Frame rate under Display "
                "gives you a smooth 60 FPS picture without changing the game "
                "at all, and is the recommended way to get one.");
            ui::Gap(ui::kGapS);
        }
        row(MDKR_VIDEO_SIMULATION_CADENCE);
        row(MDKR_VIDEO_MENU_LANGUAGES);
        ImGui::Unindent(ui::kGapM);
    }

    // Two sections that are not a schema category. Both gather keys the
    // categories would otherwise scatter -- see AppUi_settingsSection -- and
    // both add something no generated row can: the extras get one action that
    // resets them and nothing else, and the content packs get the list of what
    // the scan actually found.
    if (drawSettingsSectionHeader(
            "Extras",
            "Things you opt into. Each one says whether it changes how the "
            "game plays.",
            ImGuiTreeNodeFlags_None, compact)) {
        ImGui::Unindent(ui::kGapM);  // the section helper manages its own indent
        changed |= drawEnhancementsSection(window, compact, webGpuRenderer,
                                           legacyStretchActive);
    }

    /*
     * Packs and characters moved to the Content destination, so the launcher
     * page points at their new address rather than drawing them twice.
     *
     * The IN-GAME overlay keeps them. It draws this same page with compact=1,
     * and there is no Content destination behind a paused race -- removing the
     * rows there would have taken the durable pack switch away from the one
     * place a player is actually looking at a pack while deciding about it.
     * Tab is a momentary A/B, not a substitute for the setting.
     */
    if (compact) {
        const MdkrModRegistry *packs = platform_content_packs_registry();
        const MdkrVideoConfig *liveConfig = mdkr_video_config_current();
        const char *disabledList = liveConfig != nullptr
            ? liveConfig->values[MDKR_CONTENT_PACK_DISABLED].text : "";
        traceContentPacks(packs, disabledList);
        const bool anyPacks = mdkr_mod_registry_count(packs) > 0 ||
                              mdkr_mod_registry_skipped(packs) > 0;
        if (drawSettingsSectionHeader(
                "Content packs",
                "Packs that replace artwork or music, from the mods folder.",
                anyPacks ? ImGuiTreeNodeFlags_DefaultOpen
                         : ImGuiTreeNodeFlags_None,
                compact)) {
            ImGui::Unindent(ui::kGapM);
            changed |= drawContentSection(window, compact, packs, disabledList);
        }
    } else {
        ui::Gap(ui::kGapM);
        ui::TextSubtleWrapped(
            "Content packs and custom characters moved to Content, in the "
            "navigation on the left.");
        ui::Gap(ui::kGapM);
    }

    // --- Advanced -----------------------------------------------------------
    // What "App window" used to hold once the window mode moved to Display: the
    // update check and the developer-tools switch, which are diagnostic rather
    // than about a window. The catch-all loop comes with them, so a key like a
    // future Interface option still cannot end up with a schema row, an
    // environment variable, and no control anywhere in the product. The
    // unclaimed-key safety net is folded in here too, so the page has one
    // last-resort home rather than two.
    int unclaimed = 0;
    for (int i = 0; i < MDKR_VIDEO_KEY_COUNT; ++i) {
        const MdkrVideoKey key = static_cast<MdkrVideoKey>(i);
        if (drawnKey[i] || !visible(key)) continue;
        if (AppUi_settingsSection(key) != AppUiSettingsSection::Category)
            continue;  // owned by a dedicated section above
        if (mdkr_video_schema(key) == nullptr) continue;
        ++unclaimed;
    }
    if (unclaimed > 0 && drawSettingsSectionHeader(
            "Advanced",
            "Updates, developer tools, and anything without a home above.",
            flagsFor(false), compact)) {
        for (int i = 0; i < MDKR_VIDEO_KEY_COUNT; ++i) {
            const MdkrVideoKey key = static_cast<MdkrVideoKey>(i);
            if (drawnKey[i]) continue;
            row(key);
        }
        ui::Gap(ui::kGapS);
        ImGui::Unindent(ui::kGapM);
    }

    if (controllerSettingsSmoke) {
        static bool tracedControllerSettings = false;
        if (!tracedControllerSettings) {
            std::fprintf(
                stderr,
                "[app-ui] controller settings rendered mappings=%d rumble=%d "
                "restoreAvailable=%d restoreSucceeded=%d\n",
                controllerMappingWidgets, controllerRumbleWidgets,
                controllerRestoreAvailable ? 1 : 0,
                controllerRestoreSucceeded ? 1 : 0);
            tracedControllerSettings = true;
        }
    }

    /* No third "your changes are staged" line here. The card at the top of the
     * page names the action, and each staged row already says what will run
     * next and what is running now; a footer repeating it made one fact appear
     * three times on one page. */

    if (!g_status.empty()) {
        ui::Gap(ui::kGapS);
        ImGui::PushStyleColor(ImGuiCol_Text, g_statusColor);
        ImGui::TextWrapped("%s", g_status.c_str());
        ImGui::PopStyleColor();
    }

    return changed;
}
